#!/usr/bin/env python3
"""
logscan.py - Print log lines at a given level.

Usage: python logscan.py PATH LEVEL [--at-least] [--limit N]

Options may appear before or after positional arguments.
"""

import argparse
import os
import sys
from typing import Optional

LEVELS = ["INFO", "WARN", "ERROR"]
LEVEL_MAP = {name: i for i, name in enumerate(LEVELS)}


def print_usage(file=sys.stderr):
    file.write("usage: logscan.py PATH LEVEL [--at-least] [--limit N]\n")


def parse_args(argv: list[str]) -> tuple[str, str, Optional[bool], Optional[int]]:
    """
    Parse arguments manually to allow options before positional args.
    Returns: (path, level, at_least, limit)
    """
    if len(argv) < 3:
        print_usage()
        sys.exit(2)

    # Normalize options: --at-least and --limit can appear anywhere
    args = argv[1:]
    path: Optional[str] = None
    level_raw: Optional[str] = None
    at_least: bool = False
    limit: Optional[int] = None
    has_path = False
    has_level = False

    i = 0
    while i < len(args):
        arg = args[i]
        if arg.startswith("--"):
            if arg == "--at-least":
                at_least = True
            elif arg == "--limit":
                if i + 1 >= len(args):
                    print_usage()
                    sys.exit(2)
                try:
                    limit = int(args[i + 1])
                    if limit < 0:
                        print_usage()
                        sys.exit(2)
                except ValueError:
                    print_usage()
                    sys.exit(2)
                i += 2
            else:
                # Unknown option
                print_usage()
                sys.exit(2)
        else:
            if not has_path:
                path = arg
                has_path = True
            elif not has_level:
                level_raw = arg
                has_level = True
            else:
                # Extra non-option arg after both positional args found
                # Treat as error if it looks like an option (already handled)
                # But if it's just extra, we ignore it? The spec says positional are PATH and LEVEL.
                # Any extra non-option is likely a mistake, but spec doesn't explicitly forbid.
                # We'll ignore extra positional arguments for robustness.
                pass
        i += 1

    if not has_path:
        print_usage()
        sys.exit(2)
    if not has_level:
        print_usage()
        sys.exit(2)

    if level_raw not in LEVEL_MAP:
        print_usage()
        sys.exit(2)

    level = LEVEL_MAP[level_raw.upper()]
    return path, level_raw, at_least, limit


def main():
    if len(sys.argv) < 2:
        print_usage()
        sys.exit(2)

    path, level_raw, at_least, limit = parse_args(sys.argv)

    if not os.path.isfile(path):
        sys.stderr.write(f"logscan.py: cannot open {path}\n")
        sys.exit(1)

    level_target = LEVEL_MAP[level_raw.upper()]

    total_matches = 0
    printed = 0

    try:
        with open(path, "r", encoding="utf-8") as f:
            for line in f:
                # Normalize line to have a newline for processing, but we must output original
                original_line = line

                # Ensure line ends with newline for splitting logic, but preserve original for output
                if not line.endswith('\n'):
                    line = line + '\n'

                parts = line.split()
                if len(parts) < 3:
                    continue

                level_str = parts[2]
                if level_str not in LEVEL_MAP:
                    continue

                level_val = LEVEL_MAP[level_str]

                if at_least:
                    if level_val >= level_target:
                        if printed < limit or limit is None:
                            # Output original line without added newline if we modified it
                            # But we added a newline above only if missing.
                            # To be safe, reconstruct:
                            if original_line.endswith('\n'):
                                sys.stdout.write(original_line)
                            else:
                                sys.stdout.write(original_line + '\n')
                            printed += 1
                            total_matches += 1
                        else:
                            # Limit reached, but still count matches
                            total_matches += 1
                    else:
                        pass
                else:
                    if level_val == level_target:
                        if printed < limit or limit is None:
                            sys.stdout.write(original_line)
                            printed += 1
                            total_matches += 1
                        else:
                            total_matches += 1
                    else:
                        pass

    except Exception:
        # In case of any unexpected read error, though spec only mentions non-exist/non-regular
        sys.stderr.write(f"logscan.py: cannot open {path}\n")
        sys.exit(1)

    sys.stderr.write(f"count={total_matches}\n")
    sys.exit(0)


if __name__ == "__main__":
    main()
