"""
SemVer 2.0.0 implementation.

This module provides a simple implementation of Semantic Versioning 2.0.0
including parsing, comparison, bumping, and version range satisfaction.
"""

import re
import hashlib
from functools import total_ordering
from typing import Tuple, Optional, Union, List

__all__ = ["Version", "satisfies"]


class Version:
    """
    A Semantic Version 2.0.0 class.

    Attributes:
        major (int): Major version number.
        minor (int): Minor version number.
        patch (int): Patch version number.
        prerelease (tuple): Tuple of pre-release identifiers, empty if absent.
        build (tuple): Tuple of build metadata identifiers, empty if absent.
    """

    _parse_pattern = re.compile(
        r'^'
        r'(0|[1-9]\d*)'       # MAJOR
        r'\.'
        r'(0|[1-9]\d*)'       # MINOR
        r'\.'
        r'(0|[1-9]\d*)'       # PATCH
        r'(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?'  # PRERELEASE
        r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?'  # BUILD
        r'$',
        re.VERBOSE
    )

    def __init__(
        self,
        major: int,
        minor: int,
        patch: int,
        prerelease: Optional[tuple] = None,
        build: Optional[tuple] = None
    ):
        if prerelease is None:
            prerelease = ()
        if build is None:
            build = ()

        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = tuple(prerelease) if prerelease else ()
        self.build = tuple(build) if build else ()

    @classmethod
    def parse(cls, text: str) -> "Version":
        """
        Parse a version string according to SemVer 2.0.0.

        Args:
            text: The version string to parse.

        Returns:
            A new Version instance.

        Raises:
            ValueError: If the text is not a valid SemVer string.
        """
        text = text.strip()
        if not text:
            raise ValueError("Empty version string")

        if text.startswith('v'):
            raise ValueError("Leading 'v' is not allowed")

        match = cls._parse_pattern.match(text)
        if not match:
            raise ValueError(f"Invalid version string: {text}")

        major_str, minor_str, patch_str = match.group(1), match.group(2), match.group(3)

        # Validate no leading zeros (already handled by regex for 0|[1-9]\d*)
        major = int(major_str)
        minor = int(minor_str)
        patch = int(patch_str)

        prerelease_str = match.group(4)
        build_str = match.group(5)

        if prerelease_str:
            prerelease = tuple(prerelease_str.split('.'))
            # Check for empty identifiers in prerelease
            if any(iden == '' for iden in prerelease):
                raise ValueError("Empty identifier in pre-release")
            # Check for leading zeros in numeric prerelease identifiers
            for iden in prerelease:
                if iden.isdigit():
                    if len(iden) > 1 and iden[0] == '0':
                        raise ValueError(f"Leading zero in numeric pre-release identifier: {iden}")

        else:
            prerelease = ()

        if build_str:
            build = tuple(build_str.split('.'))
            # Build identifiers can have leading zeros, but cannot be empty
            if any(iden == '' for iden in build):
                raise ValueError("Empty identifier in build metadata")

        return cls(major, minor, patch, prerelease, build)

    def __str__(self) -> str:
        """Return the canonical representation of the version."""
        result = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            result += f"-{'.'.join(self.prerelease)}"
        if self.build:
            result += f"+{'.'.join(self.build)}"
        return result

    def __repr__(self) -> str:
        return f"Version({self.major}, {self.minor}, {self.patch}, {self.prerelease}, {self.build})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented

        # Build metadata is ignored in comparison
        return (
            self.major == other.major and
            self.minor == other.minor and
            self.patch == other.patch and
            self.prerelease == other.prerelease
        )

    def __hash__(self) -> int:
        # Hash must agree with equality
        return hash((self.major, self.minor, self.patch, self.prerelease))

    def __lt__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) < 0

    def __le__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) <= 0

    def __gt__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) > 0

    def __ge__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) >= 0

    def __ne__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return self._compare(other) != 0

    def _compare(self, other: "Version") -> int:
        """
        Compare this version with another.
        Returns -1 if self < other, 0 if self == other, 1 if self > other.
        """
        # Compare major, minor, patch
        for part in [self.major, self.minor, self.patch]:
            other_part = getattr(other, part)
            if part < 0:
                return -1
            elif part > other_part:
                return 1

        # Compare pre-release
        # A version without pre-release is greater than one with pre-release
        if not self.prerelease and other.prerelease:
            return 1
        if self.prerelease and not other.prerelease:
            return -1

        # Both have pre-release or both don't
        pre_compare = self._compare_prerelease(other.prerelease)
        if pre_compare != 0:
            return pre_compare

        return 0

    def _compare_prerelease(self, other_prerelease: tuple) -> int:
        """
        Compare two pre-release tuples.
        Returns -1, 0, or 1.
        """
        # Compare identifier by identifier
        for i in range(max(len(self.prerelease), len(other_prerelease))):
            if i >= len(self.prerelease):
                return -1  # self is shorter, so smaller
            if i >= len(other_prerelease):
                return 1   # other is shorter, so smaller

            self_id = self.prerelease[i]
            other_id = other_prerelease[i]

            self_is_num = self_id.isdigit()
            other_is_num = other_id.isdigit()

            if self_is_num and other_is_num:
                # Both numeric: compare numerically
                if int(self_id) < int(other_id):
                    return -1
                elif int(self_id) > int(other_id):
                    return 1
            elif self_is_num and not other_is_num:
                # Numeric < alphanumeric
                return -1
            elif not self_is_num and other_is_num:
                # Alphanumeric > numeric
                return 1
            else:
                # Both alphanumeric: ASCII order
                if self_id < other_id:
                    return -1
                elif self_id > other_id:
                    return 1

        return 0

    def bump(self, kind: str) -> "Version":
        """
        Bump the version by the specified kind.

        Args:
            kind: One of 'major', 'minor', or 'patch'.

        Returns:
            A new Version with the bumped part.

        Raises:
            ValueError: If kind is not valid.
        """
        if kind == 'major':
            return Version(self.major + 1, 0, 0)
        elif kind == 'minor':
            return Version(self.major, self.minor + 1, 0)
        elif kind == 'patch':
            return Version(self.major, self.minor, self.patch + 1)
        else:
            raise ValueError(f"Invalid bump kind: {kind}")


def satisfies(version_input: Union[str, Version], spec: str) -> bool:
    """
    Check if a version satisfies a version range specification.

    Args:
        version_input: A Version object or version string.
        spec: A version range specification string.

    Returns:
        True if the version satisfies all comparators in the spec.

    Raises:
        ValueError: If spec is empty/malformed or version_input is invalid.
    """
    if not spec:
        raise ValueError("Empty specification")

    version = Version.parse(version_input)

    # Split spec by whitespace
    comparators = [c.strip() for c in spec.split()]
    if not comparators:
        raise ValueError("No comparators found in specification")

    for comp in comparators:
        if not comp:
            raise ValueError("Empty comparator")

        if not _satisfies_single(comp, version):
            return False

    return True


def _satisfies_single(comp: str, version: Version) -> bool:
    """
    Check if a version satisfies a single comparator.
    """
    if comp.startswith('^'):
        return _satisfies_caret(comp[1:], version)
    elif comp.startswith('~'):
        return _satisfies_tilde(comp[1:], version)
    elif comp.startswith('>='):
        return _satisfies_geq(comp[2:], version)
    elif comp.startswith('>'):
        return _satisfies_gt(comp[1:], version)
    elif comp.startswith('<='):
        return _satisfies_leq(comp[2:], version)
    elif comp.startswith('<'):
        return _satisfies_lt(comp[1:], version)
    elif comp.startswith('='):
        return _satisfies_eq(comp[1:], version)
    else:
        # Bare version means =V
        return _satisfies_eq(comp, version)


def _normalize_version(ver_str: str) -> Version:
    """
    Normalize a version string to a full Version object.
    Partial versions (e.g., '1', '1.2') are expanded.
    Pre-release and build metadata are not allowed in normalized versions.
    """
    v = Version.parse(ver_str)

    # Check for pre-release or build in the original string
    if v.prerelease or v.build:
        raise ValueError(f"Partial versions cannot have pre-release or build metadata: {ver_str}")

    # Expand partial versions
    if v.major == 0 and v.minor == 0 and v.patch == 0:
        # 0.0.0 stays 0.0.0
        return v

    # If it was provided as '1' or '1.2', we need to ensure it's treated as 1.0.0 or 1.2.0
    # But our parse already gives us the numbers. We just need to make sure
    # that if the input was short, we treat it as having .0.0 suffix.
    # Actually, the parsing already handles this correctly by converting strings to ints.
    # The issue is if someone passes "1" which parses as 1.0.0, that's fine.
    # The constraint is that the ORIGINAL string cannot have pre-release/build.
    # Our parse will fail if there's a pre-release/build in the input.

    return v


def _satisfies_caret(ver_str: str, version: Version) -> bool:
    """
    Caret (^) allows changes that do not modify the left-most non-zero part.
    ^1.2.3 = >=1.2.3 <2.0.0
    ^0.2.3 = >=0.2.3 <0.3.0
    ^0.0.3 = >=0.0.3 <0.0.4
    """
    try:
        base = _normalize_version(ver_str)
    except ValueError:
        raise ValueError(f"Invalid version in caret spec: {ver_str}")

    # Caret comparison:
    # 1. Must be >= base
    if version < base:
        return False

    # 2. Upper bound depends on the left-most non-zero part
    if base.major != 0:
        upper = Version(base.major + 1, 0, 0)
    elif base.minor != 0:
        upper = Version(0, base.minor + 1, 0)
    else:
        # base is 0.0.x
        upper = Version(0, 0, base.patch + 1)

    # If the version has a pre-release, it might be less than upper even if numerically greater
    # But we need version < upper
    if version >= upper:
        return False

    return True


def _satisfies_tilde(ver_str: str, version: Version) -> bool:
    """
    Tilde (~) allows patch-level changes.
    ~1.2.3 = >=1.2.3 <1.3.0
    ~1.2 = >=1.2.0 <1.3.0
    ~1 = >=1.0.0 <2.0.0
    """
    try:
        base = _normalize_version(ver_str)
    except ValueError:
        raise ValueError(f"Invalid version in tilde spec: {ver_str}")

    # Tilde comparison:
    # 1. Must be >= base
    if version < base:
        return False

    # 2. Upper bound: increment minor if minor exists, else major
    if base.minor != 0:
        upper = Version(base.major, base.minor + 1, 0)
    else:
        # base is x.0.x
        if base.major != 0:
            upper = Version(base.major + 1, 0, 0)
        else:
            # base is 0.0.x
            upper = Version(0, 1, 0)

    if version >= upper:
        return False

    return True


def _satisfies_geq(ver_str: str, version: Version) -> bool:
    """
    Greater than or equal (>=).
    """
    try:
        target = _normalize_version(ver_str)
    except ValueError:
        raise ValueError(f"Invalid version in >= spec: {ver_str}")

    return version >= target


def _satisfies_gt(ver_str: str, version: Version) -> bool:
    """
    Greater than (>).
    """
    try:
        target = _normalize_version(ver_str)
    except ValueError:
        raise ValueError(f"Invalid version in > spec: {ver_str}")

    return version > target


def _satisfies_leq(ver_str: str, version: Version) -> bool:
    """
    Less than or equal (<=).
    """
    try:
        target = _normalize_version(ver_str)
    except ValueError:
        raise ValueError(f"Invalid version in <= spec: {ver_str}")

    return version <= target


def _satisfies_lt(ver_str: str, version: Version) -> bool:
    """
    Less than (<).
    """
    try:
        target = _normalize_version(ver_str)
    except ValueError:
        raise ValueError(f"Invalid version in < spec: {ver_str}")

    return version < target


def _satisfies_eq(ver_str: str, version: Version) -> bool:
    """
    Equal (=).
    """
    try:
        target = _normalize_version(ver_str)
    except ValueError:
        raise ValueError(f"Invalid version in = spec: {ver_str}")

    return version == target
