from fractions import Fraction
from typing import List, Tuple, Optional, Dict, Any, Union

class CalcError(Exception):
    def __init__(self, message: str, position: int):
        super().__init__(message)
        self.position = position

def tokenize(expr: str) -> List[Tuple[int, str]]:
    """
    Tokenize the expression into a list of (position, token_value).
    Raises CalcError with the position of the first invalid character.
    """
    tokens = []
    i = 0
    n = len(expr)

    while i < n:
        # Skip whitespace
        if expr[i] in ' \t':
            i += 1
            continue

        # Name (variable or function)
        if expr[i].isalpha() or expr[i] == '_':
            start = i
            while i < n and (expr[i].isalnum() or expr[i] == '_'):
                i += 1
            tokens.append((start, expr[start:i]))
            continue

        # Number
        if expr[i].isdigit() or (expr[i] == '.' and i + 1 < n and expr[i+1].isdigit()):
            start = i
            if expr[i] == '.':
                i += 1
            # Digits
            while i < n and expr[i].isdigit():
                i += 1
            # Optional fractional part
            if i < n and expr[i] == '.':
                i += 1
                while i < n and expr[i].isdigit():
                    i += 1
            tokens.append((start, expr[start:i]))
            continue

        # Operators: +, -, *, /, (, ), **
        if expr[i] == '(' or expr[i] == ')':
            tokens.append((i, expr[i]))
            i += 1
            continue

        if expr[i] == '+':
            tokens.append((i, '+'))
            i += 1
            continue

        if expr[i] == '-':
            tokens.append((i, '-'))
            i += 1
            continue

        if expr[i] == '*':
            # Check for **
            if i + 1 < n and expr[i+1] == '*':
                tokens.append((i, '**'))
                i += 2
                continue
            tokens.append((i, '*'))
            i += 1
            continue

        if expr[i] == '/':
            tokens.append((i, '/'))
            i += 1
            continue

        if expr[i] == ',':
            tokens.append((i, ','))
            i += 1
            continue

        # Unknown character
        raise CalcError(f"Unexpected character '{expr[i]}'", i)

    return tokens

def evaluate(expr: str, variables: Optional[Dict[str, Union[int, Fraction]]] = None) -> Fraction:
    if variables is None:
        variables = {}

    tokens = tokenize(expr)

    if not tokens:
        raise CalcError("Empty expression", 0)

    pos = 0
    tokens_list = tokens
    expr_len = len(expr)

    def peek() -> Tuple[int, str]:
        if pos < len(tokens_list):
            return tokens_list[pos]
        return None, None

    def consume() -> Tuple[int, str]:
        nonlocal pos
        if pos < len(tokens_list):
            return tokens_list[pos]
        return None, None

    def parse_expr() -> Any:
        nonlocal pos
        result = parse_term()

        while True:
            tok = peek()
            if tok is None:
                break
            if tok[0] in ('+', '-'):
                op_pos, op = tok
                pos += 1
                right = parse_term()
                if op == '+':
                    result = result + right
                else:
                    result = result - right
            else:
                break
        return result

    def parse_term() -> Any:
        nonlocal pos
        result = parse_power()

        while True:
            tok = peek()
            if tok is None:
                break
            if tok[0] == '*':
                # Not **, handled in parse_power
                op_pos, op = tok
                pos += 1
                right = parse_power()
                result = result * right
            elif tok[0] == '/':
                op_pos, op = tok
                pos += 1
                right = parse_power()
                if right == 0:
                    raise CalcError("Division by zero", op_pos)
                result = result / right
            else:
                break
        return result

    def parse_power() -> Any:
        nonlocal pos
        base = parse_factor()

        tok = peek()
        if tok is not None and tok[0] == '**':
            pos += 1  # consume **
            exp_pos = tok[0]
            exponent = parse_factor()

            # Check exponent is integer
            if isinstance(exponent, Fraction) and exponent.denominator != 1:
                raise CalcError("Exponent must be an integer", exp_pos)

            exponent_int = int(exponent)

            # Check 0^negative
            if base == 0 and exponent_int < 0:
                raise CalcError("0 raised to a negative power", exp_pos)

            # Compute power
            # Since Fraction supports **, this is safe and exact
            result = base ** exponent_int
            return result
        return base

    def parse_factor() -> Any:
        nonlocal pos
        tok = peek()
        if tok is None:
            raise CalcError("Unexpected end of expression", expr_len)

        if tok[0] == '-':
            pos += 1
            val = parse_factor()
            return -val

        elif tok[0] == '(':
            pos += 1  # consume '('
            val = parse_expr()
            next_tok = peek()
            if next_tok is None or next_tok[0] != ')':
                if next_tok is None:
                    raise CalcError("Missing closing parenthesis", expr_len)
                else:
                    raise CalcError("Missing closing parenthesis", next_tok[0])
            pos += 1  # consume ')'
            return val

        elif tok[0] == ')':
            raise CalcError("Unexpected closing parenthesis", tok[0])

        elif tok[0] == ',':
            raise CalcError("Unexpected comma", tok[0])

        elif tok[0].isalpha() or tok[0] == '_':
            # Function or Variable
            name = tok[1]
            pos += 1

            # Check for function call
            next_tok = peek()
            is_func_call = False
            func_start_pos = tok[0]

            if next_tok is not None and next_tok[0] == '(':
                is_func_call = True
                pos += 1  # consume '('
                args = parse_args()
                # Expect ')'
                next_tok = peek()
                if next_tok is None or next_tok[0] != ')':
                    if next_tok is None:
                        raise CalcError("Missing closing parenthesis", expr_len)
                    else:
                        raise CalcError("Missing closing parenthesis", next_tok[0])
                pos += 1 # consume ')'

                # Evaluate function
                if name not in ('abs', 'min', 'max'):
                    raise CalcError(f"Unknown function '{name}'", func_start_pos)

                if name == 'abs':
                    if len(args) != 1:
                        raise CalcError("abs takes exactly one argument", func_start_pos)
                    val = args[0]
                    if val < 0:
                        return -val
                    return val

                elif name == 'min':
                    if len(args) < 1:
                        raise CalcError("min takes at least one argument", func_start_pos)
                    # min is left-associative? Usually min(a,b,c) = min(min(a,b),c)
                    # Fractions support comparison.
                    # We need to find the minimum.
                    # Note: args are evaluated left-to-right.
                    # Python's min does this.
                    # However, we must ensure no division by zero or other errors happened in args.
                    # Since we evaluate args one by one, errors propagate.
                    # We need to handle the case where multiple args exist.
                    # The spec says "first one met when evaluating left to right".
                    # But min itself doesn't raise unless arguments are invalid?
                    # The error "wrong number of arguments" is checked.
                    # What if arguments are valid but min logic fails? Fractions don't fail on comparison.
                    # Just return min.
                    return min(args)

                elif name == 'max':
                    if len(args) < 1:
                        raise CalcError("max takes at least one argument", func_start_pos)
                    return max(args)

            else:
                # Variable
                # Check if it's a valid variable name (letters, digits, _)
                # We already consumed it.
                if name not in variables:
                    raise CalcError(f"Unknown variable '{name}'", func_start_pos)
                return variables[name]

        else:
            # Number
            pos += 1
            num_str = tok[1]
            try:
                return Fraction(num_str)
            except ValueError:
                raise CalcError(f"Invalid number: {num_str}", tok[0])

    def parse_args() -> List[Any]:
        """Parse comma separated arguments for a function call."""
        args = []

        # First argument
        first = parse_term()
        args.append(first)

        while True:
            tok = peek()
            if tok is None or tok[0] != ',':
                break
            pos += 1 # consume ','

            # Next argument
            next_tok = peek()
            if next_tok is None:
                raise CalcError("Trailing comma in function arguments", next_tok[0] if next_tok else expr_len)

            arg = parse_term()
            args.append(arg)

        return args

    try:
        result = parse_expr()
    except RecursionError:
        raise CalcError("Invalid expression structure", expr_len)

    # Check for trailing tokens
    if pos < len(tokens_list):
        raise CalcError("Unexpected token at end of expression", tokens_list[pos][0])

    return result
