"""
A Python module for parsing bank transaction CSVs and computing running balances
with overdraft protection.
"""

import csv
import decimal
from dataclasses import dataclass, field
from datetime import datetime
from typing import Optional

from decimal import Decimal, InvalidOperation


class LedgerError(Exception):
    """Raised when parsing or processing the ledger fails."""

    def __init__(self, message: str, line: int):
        super().__init__(message)
        self.line = line


class OverdraftError(LedgerError):
    """Raised when a transaction would cause an account to overdraw beyond its limit."""

    def __init__(self, message: str, line: int, account: str, balance: Decimal):
        super().__init__(message, line)
        self.account = account
        self.balance = balance


@dataclass(frozen=True)
class Transaction:
    date: datetime.date
    account: str
    amount: Decimal
    line: int


def _parse_date(date_str: str) -> datetime.date:
    """Parse a date string in YYYY-MM-DD format."""
    try:
        return datetime.strptime(date_str, "%Y-%m-%d").date()
    except ValueError as e:
        raise LedgerError(f"Invalid date format: {date_str}", 1) from e


def _parse_amount(amount_str: str) -> Decimal:
    """
    Parse an amount string.
    Accepts integers, floats with up to two decimal places, and optional leading '+'.
    Surrounding spaces are allowed.
    """
    s = amount_str.strip()
    if not s:
        raise LedgerError("Empty amount field", 1)

    if s.startswith("+"):
        s = s[1:]

    if not s:
        raise LedgerError("Amount becomes empty after stripping '+' sign", 1)

    # Check for more than two decimal places
    if "." in s:
        integer_part, decimal_part = s.split(".")
        if len(decimal_part) > 2:
            raise LedgerError(f"Amount has more than two decimal places: {amount_str}", 1)

    try:
        return Decimal(s)
    except InvalidOperation:
        raise LedgerError(f"Invalid amount: {amount_str}", 1)


def parse(text: str) -> list[Transaction]:
    """
    Parse CSV text into a list of Transaction objects.

    - Header must contain 'date', 'account', 'amount' (any order).
    - Blank lines are skipped but count towards line numbers.
    - Rows with too few fields or invalid data raise LedgerError.
    """
    if not text.strip():
        raise LedgerError("Empty text", 1)

    lines = text.splitlines()
    transactions = []

    # We need to track line numbers including blank lines
    line_counter = 1

    reader = csv.reader(lines)

    # Read header
    header_row = None
    try:
        header_row = next(reader)
    except StopIteration:
        raise LedgerError("Empty CSV (no header)", 1)

    # Check header columns
    header_lower = [col.strip().lower() for col in header_row]
    required_cols = {'date', 'account', 'amount'}

    if not required_cols.issubset(set(header_lower)):
        raise LedgerError(f"Missing required columns: {required_cols - set(header_lower)}", 1)

    # Map column names to indices
    col_indices = {}
    for idx, col in enumerate(header_row):
        clean_col = col.strip().lower()
        if clean_col in required_cols:
            col_indices[clean_col] = idx

    # Process data rows
    for row in reader:
        current_line = line_counter

        # Skip blank rows (rows with no content or all whitespace)
        if not any(field.strip() for field in row):
            line_counter += 1
            continue

        # Check if row has enough fields
        max_idx = max(col_indices.values())
        if len(row) <= max_idx:
            raise LedgerError(f"Not enough columns in row {current_line}", current_line)

        # Extract and validate fields
        date_str = row[col_indices['date']].strip()
        account = row[col_indices['account']].strip()
        amount_str = row[col_indices['amount']].strip()

        if not date_str:
            raise LedgerError(f"Empty date in row {current_line}", current_line)

        if not account:
            raise LedgerError(f"Empty account in row {current_line}", current_line)

        if not amount_str:
            raise LedgerError(f"Empty amount in row {current_line}", current_line)

        try:
            date = _parse_date(date_str)
            acc = account
            amount = _parse_amount(amount_str)
        except LedgerError:
            raise
        except Exception as e:
            raise LedgerError(f"Error parsing row {current_line}: {e}", current_line)

        transactions.append(Transaction(
            date=date,
            account=acc,
            amount=amount,
            line=current_line
        ))

        line_counter += 1

    return transactions


def running_balances(
    transactions: list[Transaction],
    opening: Optional[dict[str, Decimal]] = None,
    limits: Optional[dict[str, Decimal]] = None
) -> list[tuple[Transaction, Decimal]]:
    """
    Compute running balances for transactions.

    - Transactions are sorted by date, then by original order.
    - Overdraft errors are raised immediately upon first violation.
    """
    if opening is None:
        opening = {}
    if limits is None:
        limits = {}

    # Sort transactions by date, preserving original order for same dates
    sorted_txns = sorted(
        transactions,
        key=lambda t: (t.date, t.line)
    )

    # Initialize balances
    balances: dict[str, Decimal] = {}
    for acc, bal in opening.items():
        balances[acc] = bal

    # Set limits (default 0)
    def get_limit(acc: str) -> Decimal:
        return limits.get(acc, Decimal('0'))

    results = []

    for txn in sorted_txns:
        account = txn.account
        amount = txn.amount
        current_balance = balances.get(account, Decimal('0'))

        # Check if this account exists in opening (to initialize if not)
        if account not in balances:
            balances[account] = Decimal('0')

        new_balance = current_balance + amount
        limit = get_limit(account)

        # Overdraft check: balance cannot go below -limit
        if new_balance < -limit:
            raise OverdraftError(
                f"Account {account} would overdraw to {new_balance}",
                txn.line,
                account=account,
                balance=new_balance
            )

        # Update balance
        balances[account] = new_balance
        results.append((txn, new_balance))

    return results


def final_balances(
    transactions: list[Transaction],
    opening: Optional[dict[str, Decimal]] = None,
    limits: Optional[dict[str, Decimal]] = None
) -> dict[str, Decimal]:
    """
    Return final balances for all accounts after processing transactions.
    Includes accounts that only appear in opening dict.
    """
    if opening is None:
        opening = {}
    if limits is None:
        limits = {}

    # Run the same logic as running_balances but only return final state
    try:
        running_balances(transactions, opening, limits)
    except OverdraftError:
        # Re-raise the error as expected
        raise

    # Build final balances dict including only accounts from opening and transactions
    final: dict[str, Decimal] = {}

    # Include all opening accounts
    for acc in opening:
        final[acc] = opening[acc]

    # Update with transaction results
    # We need to re-run the logic to get final balances without raising error again
    # But we can just use the internal state from running_balances if we could,
    # so let's just re-run the computation silently

    balances: dict[str, Decimal] = dict(opening)

    sorted_txns = sorted(
        transactions,
        key=lambda t: (t.date, t.line)
    )

    def get_limit(acc: str) -> Decimal:
        return limits.get(acc, Decimal('0'))

    for txn in sorted_txns:
        account = txn.account
        amount = txn.amount

        if account not in balances:
            balances[account] = Decimal('0')

        new_balance = balances[account] + amount
        limit = get_limit(account)

        if new_balance < -limit:
            raise OverdraftError(
                f"Account {account} would overdraw to {new_balance}",
                txn.line,
                account=account,
                balance=new_balance
            )

        balances[account] = new_balance

    return balances
