class LookupError(Exception):
    """Base exception for lookup failures."""
    pass

class PathError(LookupError):
    """Exception raised for invalid paths or missing values during lookup.

    Attributes:
        path: The path string that caused the error.
    """
    def __init__(self, path: str, message: str = ""):
        super().__init__(message or f"Invalid path: {path}")
        self.path = path

def parse(path: str) -> List[Union[str, int]]:
    """
    Parses a path string into a list of segments.

    Segments are either:
    - A string (for dict keys, including quoted keys with special chars)
    - An integer (for list/tuple indexing)

    Args:
        path: The path string (e.g., "a.b[2].c" or 'a["x.y"][-1]')

    Returns:
        List of segments representing the path

    Raises:
        PathError: If the path syntax is invalid
    """
    if not isinstance(path, str):
        raise PathError(path, "Path must be a string")

    if path == "":
        return []

    segments = []
    i = 0
    n = len(path)

    while i < n:
        # Skip whitespace? The spec doesn't mention it, but let's be strict
        # "Anything else is a syntax error" implies no whitespace handling

        if i >= n:
            break

        # Check for segment start
        if path[i] == '.':
            # Name must be preceded by start of string or '.'
            # But '.' itself is not allowed as start of name
            i += 1
            if i >= n:
                raise PathError(path, "Empty name after dot")

            # Check if next char is '.' (empty name like a..)
            if path[i] == '.':
                raise PathError(path, "Empty name (consecutive dots)")

            # Start reading name
            start = i
            while i < n and path[i] not in ['.', '[', '"']:
                i += 1

            name = path[start:i]
            if not name:
                raise PathError(path, "Empty name")

            segments.append(name)

        elif path[i] == '[':
            i += 1
            if i >= n:
                raise PathError(path, "Unclosed bracket")

            if path[i] == '"':
                # Quoted key
                i += 1
                start = i
                while i < n and path[i] != '"':
                    if path[i] == '\\' and i + 1 < n:
                        i += 1
                        # Check for valid escape sequences
                        if path[i] == '"':
                            i += 1
                        elif path[i] == '\\':
                            i += 1
                        else:
                            raise PathError(path, "Invalid escape sequence")
                    elif path[i] == '"':
                        # End of string
                        i += 1
                        break
                    else:
                        i += 1

                if i >= n:
                    raise PathError(path, "Unclosed quote")

                key = path[start:i-1]  # Remove quotes
                segments.append(key)

            elif path[i].isdigit() or (path[i] == '-' and i + 1 < n and path[i+1].isdigit()):
                # Integer index
                start = i
                if path[i] == '-':
                    i += 1
                    if i >= n or not path[i].isdigit():
                        raise PathError(path, "Invalid integer index")
                while i < n and path[i].isdigit():
                    i += 1

                if i == start:
                    raise PathError(path, "Empty index")

                try:
                    val = int(path[start:i])
                    segments.append(val)
                except ValueError:
                    raise PathError(path, "Invalid integer index")

            else:
                raise PathError(path, f"Invalid segment after '[': '{path[i]}'")

        elif path[i] == '"':
            raise PathError(path, "Unexpected quote at start of segment")

        else:
            # First segment could be a bare name starting with this char
            # But we already handled '.' and '['
            # Any other char starting a segment is invalid unless it's part of a name
            # Wait, we need to handle the case where the path starts with a name
            # The logic above handles names after '.' but not at the start

            # Actually, let's refactor: we need to handle the first segment differently
            # because it doesn't have a preceding '.'

            if not segments:
                # First segment
                if path[i] in ['.', '[', '"']:
                    raise PathError(path, f"Segment must start with a name: '{path[i]}'")

                start = i
                while i < n and path[i] not in ['.', '[', '"']:
                    i += 1

                name = path[start:i]
                if not name:
                    raise PathError(path, "Empty name")

                segments.append(name)
            else:
                raise PathError(path, f"Unexpected character '{path[i]}' after segments")

    return segments

def get(obj: Any, path: str, default: Any = None) -> Any:
    """
    Retrieves a value from a nested data structure using a path string.

    Args:
        obj: The root object (dict, list, etc.)
        path: The path string (e.g., "a.b[2].c")
        default: Value to return if the path is not found

    Returns:
        The value at the specified path, or default if not found

    Raises:
        PathError: If the path is syntactically invalid
    """
    # Check for syntax errors first
    try:
        segments = parse(path)
    except PathError:
        raise

    current = obj

    for segment in segments:
        if isinstance(current, (str, int, float, bool, type(None))):
            # Scalars cannot be indexed
            raise PathError(path, f"Cannot index scalar value of type {type(current).__name__}")

        try:
            if isinstance(segment, int):
                # Must be list or tuple
                if not isinstance(current, (list, tuple)):
                    raise PathError(path, f"Cannot index with integer on {type(current).__name__}")

                # Check bounds
                if segment < -len(current) or segment >= len(current):
                    raise PathError(path, f"Index {segment} out of range for list of length {len(current)}")

                current = current[segment]

            elif isinstance(segment, str):
                # Must be a mapping
                if not isinstance(current, collections.abc.Mapping):
                    raise PathError(path, f"Cannot lookup key in {type(current).__name__}")

                # Check if key exists
                if segment not in current:
                    raise PathError(path, f"Key '{segment}' not found")

                current = current[segment]

            else:
                raise PathError(path, f"Invalid segment type: {type(segment).__name__}")

        except (KeyError, IndexError, TypeError, ValueError) as e:
            # Re-raise as PathError with better message if needed
            if isinstance(e, (KeyError, IndexError)):
                raise PathError(path, f"Missing value: {e}")
            raise PathError(path, str(e))

    return current
