        # Check for segment start
        if path[i] == '.':
            i += 1
            if i >= n:
                raise PathError(path, "Empty name after dot")

            if path[i] == '.':
                raise PathError(path, "Empty name (consecutive dots)")

            start = i
            while i < n and path[i] not in ['.', '[', '"']:
                i += 1

            name = path[start:i]
            if not name:
                raise PathError(path, "Empty name")

            segments.append(name)

        elif path[i] == '[':
            i += 1
            if i >= n:
                raise PathError(path, "Unclosed bracket")

            if path[i] == '"':
                # Quoted key
                i += 1
                start = i
                while i < n and path[i] != '"':
                    if path[i] == '\\' and i + 1 < n:
                        i += 1
                        if path[i] == '"':
                            i += 1
                        elif path[i] == '\\':
                            i += 1
                        else:
                            raise PathError(path, "Invalid escape sequence")
                    elif path[i] == '"':
                        i += 1
                        break
                    else:
                        i += 1

                if i >= n:
                    raise PathError(path, "Unclosed quote")

                key = path[start:i-1]
                segments.append(key)

            elif path[i] == '*':
                segments.append(WILDCARD)
                i += 1

            elif path[i].isdigit() or (path[i] == '-' and i + 1 < n and path[i+1].isdigit()):
                start = i
                if path[i] == '-':
                    i += 1
                    if i >= n or not path[i].isdigit():
                        raise PathError(path, "Invalid integer index")
                while i < n and path[i].isdigit():
                    i += 1

                if i == start:
                    raise PathError(path, "Empty index")

                try:
                    val = int(path[start:i])
                    segments.append(val)
                except ValueError:
                    raise PathError(path, "Invalid integer index")

            else:
                raise PathError(path, f"Invalid segment after '[': '{path[i]}'")

        elif path[i] == '"':
            raise PathError(path, "Unexpected quote at start of segment")

        else:
