        segments = parse(path)
    except PathError:
        raise

    has_wildcard = WILDCARD in segments

    if has_wildcard:
        return _get_with_wildcard(obj, segments)
    else:
        return _get_standard(obj, segments, default)

def _get_standard(obj: Any, segments: List[Union[str, int]], default: Any) -> Any:
    """Standard get without wildcards."""
    current = obj

    for segment in segments:
        if isinstance(current, (str, int, float, bool, type(None))):
            raise PathError(obj.path if hasattr(obj, 'path') else segments[0], 
                           f"Cannot index scalar value of type {type(current).__name__}")

        try:
            if isinstance(segment, int):
                if not isinstance(current, (list, tuple)):
                    raise PathError(segments[0], f"Cannot index with integer on {type(current).__name__}")

                if segment < -len(current) or segment >= len(current):
                    raise PathError(segments[0], f"Index {segment} out of range for list of length {len(current)}")

                current = current[segment]

            elif isinstance(segment, str):
                if not isinstance(current, collections.abc.Mapping):
                    raise PathError(segments[0], f"Cannot lookup key in {type(current).__name__}")

                if segment not in current:
                    raise PathError(segments[0], f"Key '{segment}' not found")

                current = current[segment]

            else:
                raise PathError(segments[0], f"Invalid segment type: {type(segment).__name__}")

        except (KeyError, IndexError, TypeError, ValueError) as e:
            if isinstance(e, (KeyError, IndexError)):
                raise PathError(segments[0], f"Missing value: {e}")
            raise PathError(segments[0], str(e))

    return current

def _get_with_wildcard(obj: Any, segments: List[Union[str, int, object]]) -> List[Any]:
    """Get with wildcard support."""
    # Find the first wildcard position
    wildcard_idx = segments.index(WILDCARD)
    before_segments = segments[:wildcard_idx]
    after_segments = segments[wildcard_idx + 1:]

    results: List[List[Any]] = []

    def traverse(current: Any, path_segments: List[Union[str, int, object]]) -> None:
        if not path_segments:
            results.append(current)
            return

        segment = path_segments[0]
        rest = path_segments[1:]

        if segment is WILDCARD:
            if isinstance(current, (list, tuple)):
                for item in current:
                    traverse(item, rest)
            elif isinstance(current, collections.abc.Mapping):
                for item in current.values():
                    traverse(item, rest)
            # If current is scalar or other type, this branch matches nothing
            return

        if isinstance(segment, int):
            if not isinstance(current, (list, tuple)):
                return # Skip this branch

            if segment < -len(current) or segment >= len(current):
                return # Out of range, skip

            traverse(current[segment], rest)

        elif isinstance(segment, str):
            if not isinstance(current, collections.abc.Mapping):
                return # Skip this branch

            if segment not in current:
                return # Missing key, skip

            traverse(current[segment], rest)

        else:
            pass # Should not happen if logic is correct

    traverse(obj, before_segments)

    # Flatten the results (list of lists)
    flattened = []
    for r in results:
        flattened.extend(r)

    return flattened

def set(obj: Any, path: str, value: Any) -> None:
    """
    Stores value at path, changing obj in place.

    Args:
        obj: The root object
        path: The path string
        value: The value to store

    Raises:
        PathError: If path is invalid, contains wildcards, or operation fails
    """
    if not path:
        raise PathError(path, "Empty path")

    segments = parse(path)

    if WILDCARD in segments:
        raise PathError(path, "Cannot use wildcard in set path")

    if not segments:
        raise PathError(path, "Path must have at least one segment")

    current = obj

    # Traverse all segments except the last one
    for i, segment in enumerate(segments[:-1]):
        # Check if current is mutable and correct type
        if isinstance(segment, int):
            if not isinstance(current, (list, tuple)):
                raise PathError(path, f"Cannot index {type(current).__name__} with integer")

            # If we are creating a new container, it must be a list
            if current not in obj and isinstance(current, dict):
                # This case shouldn't happen if we check below, 
                # but logic ensures we only create lists for indices
                pass

            # Determine if index is valid for existing or creation
            if segment >= len(current):
                if segment != len(current):
                    raise PathError(path, f"Index {segment} out of range")
                # Valid append index
            elif segment < -len(current):
                raise PathError(path, f"Index {segment} out of range")

            # If it's a tuple, we can't append or modify, so current must be a list
            # Actually, the spec says "a newly created list only accepts index 0"
            # and "Any other index raises".
            # Also "an index segment on a dict" raises.
            # And "on a string, number, None or a tuple that would have to change" raises.
            # So if current is tuple, we can't set anything? 
            # The spec says "When the value at a segment is missing, a new container is created".
            # Tuples are immutable, so we can't create/modify them. 
            # Thus, if current is tuple, and we need to go deeper, it's an error?
            # Or does it mean we can't create a tuple? 
            # "A container can only be created... inside a dict... or a list".
            # So if we hit a tuple, we can't continue.
            if isinstance(current, tuple):
                raise PathError(path, "Cannot modify tuple")

        elif isinstance(segment, str):
            if not isinstance(current, collections.abc.Mapping):
                raise PathError(path, f"Cannot lookup key in {type(current).__name__}")

        else:
            raise PathError(path, f"Invalid segment type: {type(segment).__name__}")

        # Check if key/index exists
        if isinstance(segment, int):
            if segment < 0 or segment >= len(current):
                # Missing element, need to create
                # Only index 0 is allowed for new lists
                if segment != 0:
                    raise PathError(path, f"Cannot create list element at index {segment}")
                # Create new list
                current = []
            # Else: element exists, replace it
        else:
            if segment not in current:
                # Missing key, need to create
                # Next segment determines type
                next_seg = segments[i + 1]
                if isinstance(next_seg, int):
                    current[segment] = []
                else:
                    current[segment] = {}

            current = current[segment]

        # If we created a new container, verify it matches expectations for future steps
        # If we are at the second to last segment and created something:
        # If next segment is int, we created a list -> OK
        # If next segment is str, we created a dict -> OK

    # Final segment
    last_segment = segments[-1]

    if isinstance(last_segment, int):
        if not isinstance(current, (list, tuple)):
            raise PathError(path, f"Cannot set index on {type(current).__name__}")

        # If tuple, we can't set
        if isinstance(current, tuple):
            raise PathError(path, "Cannot set index on tuple")

        if last_segment >= len(current) and last_segment != len(current):
            raise PathError(path, f"Index {last_segment} out of range")

        if last_segment < -len(current):
            raise PathError(path, f"Index {last_segment} out of range")

        current[last_segment] = value

    elif isinstance(last_segment, str):
        if not isinstance(current, collections.abc.Mapping):
            raise PathError(path, f"Cannot set key in {type(current).__name__}")

        if last_segment in current:
            current[last_segment] = value
        else:
            current[last_segment] = value
        # If key didn't exist, we added it. That's allowed.

    else:
        raise PathError(path, f"Invalid segment type: {type(last_segment).__name__}")

def delete(obj: Any, path: str) -> Any:
    """
    Removes the value at path from its parent and returns it.

    Args:
        obj: The root object
        path: The path string

    Returns:
        The deleted value

    Raises:
        PathError: If path is invalid, contains wildcards, value missing, or parent wrong type
    """
    if not path:
        raise PathError(path, "Path cannot be empty")

    segments = parse(path)

    if WILDCARD in segments:
        raise PathError(path, "Cannot use wildcard in delete path")

    if not segments:
        raise PathError(path, "Path must have at least one segment")

    current = obj

    # Traverse all segments except the last one
    for i, segment in enumerate(segments[:-1]):
        if isinstance(segment, int):
            if not isinstance(current, (list, tuple)):
                raise PathError(path, f"Cannot index {type(current).__name__} with integer")

            if segment < -len(current) or segment >= len(current):
                raise PathError(path, f"Index {segment} out of range")

            if isinstance(current, tuple):
                raise PathError(path, "Cannot delete from tuple")

        elif isinstance(segment, str):
            if not isinstance(current, collections.abc.Mapping):
                raise PathError(path, f"Cannot lookup key in {type(current).__name__}")

            if segment not in current:
                raise PathError(path, f"Key '{segment}' not found")

        else:
            raise PathError(path, f"Invalid segment type: {type(segment).__name__}")

        # Move to next level
        if isinstance(segment, int):
            current = current[segment]
        else:
            current = current[segment]

    # Final segment: the one to delete
    last_segment = segments[-1]

    if isinstance(last_segment, int):
        if not isinstance(current, (list, tuple)):
            raise PathError(path, f"Cannot delete by index from {type(current).__name__}")

        if last_segment < -len(current) or last_segment >= len(current):
            raise PathError(path, f"Index {last_segment} out of range")

        if isinstance(current, tuple):
            raise PathError(path, "Cannot delete from tuple")

        deleted = current.pop(last_segment)
        return deleted

    elif isinstance(last_segment, str):
        if not isinstance(current, collections.abc.Mapping):
            raise PathError(path, f"Cannot delete key from {type(current).__name__}")

        if last_segment not in current:
            raise PathError(path, f"Key '{last_segment}' not found")

        deleted = current.pop(last_segment)
        return deleted

    else:
        raise PathError(path, f"Invalid segment type: {type(last_segment).__name__}")
