        if not isinstance(row, list) or len(row) != 9:
            raise ValueError(f"Row {i} must have 9 columns.")
        for val in row:
            if not isinstance(val, int) or val < 0 or val > 9:
                raise ValueError(f"Cell value must be an integer between 0 and 9.")


def parse(text: str) -> List[List[int]]:
    """
    Read 81 cells from text in row-major order.

    - Digits '1'-'9' are givens.
    - '0' and '.' represent empty cells.
    - Whitespace is ignored anywhere.
    - Any other character or incorrect cell count raises ValueError.
    """
    # Remove all whitespace
    cleaned = "".join(ch for ch in text if not ch.isspace())

    if len(cleaned) != 81:
        raise ValueError("Input must contain exactly 81 cells.")

    grid = []
    for i in range(9):
        row = []
        for j in range(9):
            idx = i * 9 + j
            ch = cleaned[idx]
            if ch == '0' or ch == '.':
                row.append(0)
            elif ch.isdigit():
                if '0' <= ch <= '9':
                    val = int(ch)
                    if val == 0:
                        # Explicit 0 is allowed as input for empty cells
                        row.append(0)
                    else:
                        row.append(val)
                else:
                    raise ValueError(f"Invalid digit '{ch}' at position {idx}.")
            else:
                raise ValueError(f"Invalid character '{ch}' at position {idx}.")
        grid.append(row)

    return grid


def to_string(grid: List[List[int]]) -> str:
    """
    Convert a grid to a single line string.

    - Digits 1-9 as themselves.
    - Empty cells (0) as '.'.
    - No whitespace.
    """
    _validate_grid(grid)
    parts = []
    for row in grid:
        for val in row:
            if val == 0:
                parts.append('.')
            else:
                parts.append(str(val))
    return "".join(parts)


def is_valid(grid: List[List[int]]) -> bool:
    """
    Check if the grid has no conflicts for digits 1-9.

    Empty cells (0) never conflict. The grid need not be complete.
    """
    _validate_grid(grid)

    # Check rows
    for row in grid:
        seen = [False] * 10
        for val in row:
            if 1 <= val <= 9 and seen[val]:
                return False
            if 1 <= val <= 9:
                seen[val] = True

    # Check columns
    for col in range(9):
        seen = [False] * 10
        for row in grid:
            val = row[col]
            if 1 <= val <= 9 and seen[val]:
                return False
            if 1 <= val <= 9:
                seen[val] = True

    # Check 3x3 boxes
    for box_row in range(3):
        for box_col in range(3):
            seen = [False] * 10
            for i in range(3):
                for j in range(3):
                    r = box_row * 3 + i
                    c = box_col * 3 + j
                    val = grid[r][c]
                    if 1 <= val <= 9 and seen[val]:
                        return False
                    if 1 <= val <= 9:
                        seen[val] = True

    return True


def _is_position_safe(grid: List[List[int]], row: int, col: int, num: int) -> bool:
    """Check if placing 'num' at (row, col) is valid."""
    # Check row
    for c in range(9):
        if grid[row][c] == num:
            return False

    # Check column
    for r in range(9):
        if grid[r][col] == num:
            return False

    # Check 3x3 box
    box_r_start = (row // 3) * 3
    box_c_start = (col // 3) * 3
    for r in range(box_r_start, box_r_start + 3):
        for c in range(box_c_start, box_c_start + 3):
            if grid[r][c] == num:
                return False

    return True


def _solve_recursive(grid: List[List[int]], empty_cells: List[tuple[int, int]]) -> List[List[int]] | None:
    """
    Recursive backtracking solver.

    Args:
        grid: Current state of the grid (modified in place during recursion).
        empty_cells: List of (row, col) indices that are empty (0).

    Returns:
        A solved grid (new list of lists) if found, None otherwise.
    """
    if not empty_cells:
        return [row[:] for row in grid]  # Return a deep copy of the solved grid

    row, col = empty_cells[0]

    for num in range(1, 10):
        if _is_position_safe(grid, row, col, num):
            # Place number
            grid[row][col] = num

            # Remove current cell from empty_cells and recurse
            new_empty = empty_cells[1:]
            result = _solve_recursive(grid, new_empty)

            if result is not None:
                return result

            # Backtrack
            grid[row][col] = 0

    return None


def solve(grid: List[List[int]]) -> List[List[int]] | None:
    """
    Solve the Sudoku puzzle.

    Returns a completed, valid grid that keeps every given of `grid`,
    or None if no solution exists.

    The argument is never modified; the result is a new grid.
    """
    _validate_grid(grid)

    # Create a deep copy to avoid modifying the original
    working_grid = [row[:] for row in grid]

    # Collect empty cells
    empty_cells = []
    for r in range(9):
        for c in range(9):
            if working_grid[r][c] == 0:
                empty_cells.append((r, c))

    # Sort empty cells by most constrained first (MRV heuristic) could improve performance,
    # but simple order is sufficient for correctness. Let's stick to row-major for simplicity.

    return _solve_recursive(working_grid, empty_cells)


def count_solutions(grid: List[List[int]], limit: int = 2) -> int:
    """
    Count the number of solutions to the Sudoku puzzle.

    Stops counting as soon as `limit` solutions are found.
    Returns min(number of solutions, limit).

    Args:
        grid: The puzzle grid.
        limit: Maximum number of solutions to count (default 2). Must be >= 1.

    Returns:
        The number of solutions found, capped at limit.

    Raises:
        ValueError: If limit < 1.
    """
    if limit < 1:
        raise ValueError("limit must be at least 1.")

    _validate_grid(grid)

    if not is_valid(grid):
        return 0

    count = 0
    solutions_found = 0

    # Create a deep copy to avoid modifying the original
    working_grid = [row[:] for row in grid]

    # Collect empty cells
    empty_cells = []
    for r in range(9):
        for c in range(9):
            if working_grid[r][c] == 0:
                empty_cells.append((r, c))

    def backtrack(current_grid: List[List[int]], current_empty: List[tuple[int, int]]) -> None:
        nonlocal count, solutions_found

        if solutions_found >= limit:
            return

        if not current_empty:
            count += 1
            solutions_found += 1
            if solutions_found >= limit:
                return
            return

        row, col = current_empty[0]

        for num in range(1, 10):
            if _is_position_safe(current_grid, row, col, num):
                current_grid[row][col] = num
                backtrack(current_grid, current_empty[1:])
                if solutions_found >= limit:
                    return
                current_grid[row][col] = 0

    backtrack(working_grid, empty_cells)

    return count
