    # 2. Look for Hidden Single
    # Order: Rows 0-8, Cols 0-8, Boxes 0-8
    # For each unit, check digits 1-9

    units_to_check = []

    # Rows
    for r in range(9):
        for d in range(1, 10):
            # Find empty cells in this row that can take 'd'
            candidates_in_row = []
            for c in range(9):
                if grid[r][c] == 0:
                    if d in _get_candidates(grid, r, c):
                        candidates_in_row.append(c)

            if len(candidates_in_row) == 1:
                c = candidates_in_row[0]
                return (r, c, d, 'hidden single in row')

