                r = candidates_in_col[0]
                return (r, c, d, 'hidden single in column')

    # Boxes
    for b in range(9):
        box_r_start = (b // 3) * 3
        box_c_start = (b % 3) * 3

        for d in range(1, 10):
            candidates_in_box = []
            for i in range(3):
                for j in range(3):
                    r = box_r_start + i
                    c = box_c_start + j
                    if grid[r][c] == 0:
                        if d in _get_candidates(grid, r, c):
                            candidates_in_box.append((r, c))

