    """
    Calculate difficulty based on logical steps.

    Simulates solving the puzzle using only 'hint' steps.
    Returns {'naked': N, 'hidden': H} if solved logically.
    Returns None if the puzzle requires guessing or has no solution.
    """
    _validate_grid(grid)

    if not is_valid(grid):
        raise ValueError("Grid is not valid.")

    # Work on a deep copy
    work_grid = [row[:] for row in grid]
    naked_count = 0
    hidden_count = 0
    steps = 0
    max_steps = 81  # Max possible empty cells

    while True:
        # Check if complete
        is_complete = True
        for r in range(9):
            for c in range(9):
                if work_grid[r][c] == 0:
                    is_complete = False
                    break
            if not is_complete:
                break

        if is_complete:
            return {'naked': naked_count, 'hidden': hidden_count}

        # Check if grid became invalid (shouldn't happen with valid logic, but safety)
        if not is_valid(work_grid):
            return None

        hint_res = hint(work_grid)
        if hint_res is None:
            # No logical step available
            return None

        row, col, digit, reason = hint_res

        if reason == 'naked single':
            naked_count += 1
        else:
            hidden_count += 1

        # Apply the step
        work_grid[row][col] = digit

        steps += 1
        if steps > max_steps:
            # Should not happen if logic is sound, but safety break
            return None

