from typing import Any

RE_TAG_PATTERN = re.compile(r'^[a-z0-9][a-z0-9_-]*$')
RE_DATE_PATTERN = re.compile(r'^\d{4}-\d{2}-\d{2}$')

# Priority order for sorting
PRIORITY_ORDER = {"high": 0, "normal": 1, "low": 2}


def normalize_title(title: str) -> str:
    """Strip surrounding whitespace and return the result."""
    stripped = title.strip()
    if not stripped:
        raise ValueError("Title cannot be empty")
    return stripped


def normalize_tag(tag: str) -> str:
    """Strip surrounding whitespace, lowercase, and validate against regex."""
    stripped = tag.strip().lower()
    if not stripped:
        raise ValueError("Tag cannot be empty")
    if not RE_TAG_PATTERN.fullmatch(stripped):
        raise ValueError(f"Invalid tag format: '{tag}'")
    return stripped


def normalize_priority(p: str) -> str:
    """Strip and lowercase priority. Must be 'high', 'normal', or 'low'."""
    stripped = p.strip().lower()
    if stripped not in ("high", "normal", "low"):
        raise ValueError(f"Invalid priority: '{p}'")
    return stripped


def parse_date(s: str) -> datetime.date:
    """Parse a date string in YYYY-MM-DD format."""
    if not RE_DATE_PATTERN.match(s):
        raise ValueError(f"Invalid date format: '{s}'")

    try:
        year, month, day = map(int, s.split('-'))
        return datetime(year, month, day).date()
    except ValueError:
        raise ValueError(f"Invalid calendar date: '{s}'")


@dataclass
class Task:
    id: int
    title: str
    tags: list[str]
    done: bool = False
    priority: str = field(default="normal", init=False)
    due: str = field(default=None, init=False)  # Stored as string YYYY-MM-DD or None

    def __post_init__(self):
        """Ensure priority and due are in canonical form after creation."""
        if not hasattr(self, '_priority_set') or self.priority != "normal":
            self.priority = "normal"
        if self.due is not None and not hasattr(self, '_due_set'):
            self.due = None

    # Re-implementing post_init logic specifically for the fields added
    # Since dataclass fields don't run arbitrary code easily on init without complex logic,
    # we will rely on the setter logic or ensure initialization is clean.
    # However, for `from_dict`, we set them explicitly.
    # For `add`, we set them explicitly.
    # The only tricky part is ensuring `priority` defaults to "normal" and `due` to None.
    # The dataclass defaults handle this.

    def to_dict(self) -> dict[str, Any]:
        """Returns a dict with keys in a specific order."""
        # Using a list of tuples to ensure order
        return [
            ("id", self.id),
            ("title", self.title),
            ("tags", self.tags),
            ("done", self.done),
            ("priority", self.priority),
            ("due", self.due),
        ]

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "Task":
        """Builds a task from a dict."""
        # Check required keys (id, title, tags, done are mandatory)
        required_keys = {"id", "title", "tags", "done"}
        if not required_keys.issubset(d.keys()):
            missing = required_keys - set(d.keys())
            raise ValueError(f"Missing keys: {missing}")

        # Type checks
        if not isinstance(d["id"], int):
            raise ValueError("id must be an integer")
        if not isinstance(d["title"], str):
            raise ValueError("title must be a string")
        if not isinstance(d["tags"], list):
            raise ValueError("tags must be a list")
        if not all(isinstance(t, str) for t in d["tags"]):
            raise ValueError("tags must be a list of strings")
        if not isinstance(d["done"], bool):
            raise ValueError("done must be a boolean")

        # Optional fields types
        if "priority" in d:
            if not isinstance(d["priority"], str):
                raise ValueError("priority must be a string")
        if "due" in d:
            if d["due"] is not None and not isinstance(d["due"], str):
                raise ValueError("due must be a string or null")
            if d["due"] is None and not isinstance(d["due"], type(None)):
                raise ValueError("due must be a string or null")

        # Validate and normalize content
        try:
            normalized_title = normalize_title(d["title"])
        except ValueError:
            raise ValueError(f"Invalid title: '{d['title']}'")

        # Validate and normalize tags
        normalized_tags = []
        for tag in d["tags"]:
            normalized = normalize_tag(tag)
            normalized_tags.append(normalized)
        normalized_tags = sorted(set(normalized_tags))

        # Handle priority
        priority = d.get("priority", "normal")
        if not isinstance(priority, str):
            priority = "normal"
        try:
            normalized_priority = normalize_priority(priority)
        except ValueError:
            raise ValueError(f"Invalid priority: '{priority}'")

        # Handle due
        due = d.get("due")
        if due is not None:
            try:
                normalized_due = parse_date(due)
                # Store as string
                normalized_due = normalized_due.isoformat()
            except ValueError:
                raise ValueError(f"Invalid date: '{due}'")
        else:
            normalized_due = None

        return cls(
            id=d["id"], 
            title=normalized_title, 
            tags=normalized_tags, 
            done=d["done"],
            priority=normalized_priority,
            due=normalized_due
        )
