```python
"""Storage layer for Todo tasks using a JSON file."""

import io
import json
import os
import shutil
import tempfile
from datetime import date
from pathlib import Path
from typing import Any

from todo.model import Task, normalize_priority, parse_date

# Import here to avoid circular imports
try:
    from todo.model import Task
except ImportError:
    from model import Task

class StoreError(Exception):
    """Raised when the store file cannot be read or is invalid."""
    pass

class TodoStore:
    def __init__(self, path: str | Path):
        self._path = Path(path)
        self._data: dict[str, Any] | None = None
        self._tasks: dict[int, Task] = {}

        # Load data if file exists
        if self._path.exists():
            try:
                raw = self._path.read_text(encoding="utf-8")
                self._data = json.loads(raw)

                # Validate structure
                if not isinstance(self._data, dict):
                    raise StoreError("Root must be a JSON object")
                if "version" not in self._data or "next_id" not in self._data or "tasks" not in self._data:
                    raise StoreError("Missing required keys (version, next_id, tasks)")

                version = self._data["version"]
                if version not in (1, 2):
                    raise StoreError(f"Unsupported version: {version}")

                if self._data["version"] != 1 and self._data["version"] != 2:
                    raise StoreError(f"Unsupported version: {self._data['version']}")

                raw_tasks = self._data["tasks"]
                if not isinstance(raw_tasks, list):
                    raise StoreError("Tasks must be a list")

                # Build tasks list
                loaded_tasks: list[Task] = []
                current_id = self._data["next_id"]

                for item in raw_tasks:
                    try:
                        t = Task.from_dict(item)
                        loaded_tasks.append(t)
                    except ValueError as e:
                        raise StoreError(f"Invalid task data: {e}")

                # Reorder to ensure increasing ID order and check for gaps/duplicates
                seen_ids = set()
                valid_tasks = []
                for t in loaded_tasks:
                    if t.id in seen_ids:
                        raise StoreError(f"Duplicate task id: {t.id}")
                    seen_ids.add(t.id)
                    if t.id >= current_id:
                         raise StoreError(f"Task id {t.id} is not below next_id {current_id}")
                    valid_tasks.append(t)

                # Check order
                for i in range(len(valid_tasks) - 1):
                    if valid_tasks[i].id > valid_tasks[i+1].id:
                        raise StoreError("Tasks are not in increasing id order")

                # Reconstruct internal state
                self._tasks = {t.id: t for t in valid_tasks}

            except json.JSONDecodeError as e:
                raise StoreError(f"Invalid JSON: {e}")
            except KeyError as e:
                raise StoreError(f"Invalid file structure: {e}")
        else:
            # Missing file is an empty store. Do not create the file.
            self._data = {"version": 2, "next_id": 1, "tasks": []}
            self._tasks = {}

    def _save(self) -> None:
        """Writes the current state to disk atomically."""
        # Serialize to dict in order
        # We need to iterate by ID to ensure order
        tasks_list = []
        for i in range(1, self._data["next_id"]):
            if i in self._tasks:
                tasks_list.append(self._tasks[i])

        output = {
            "version": 2,  # Always write version 2
            "next_id": self._data["next_id"],
            "tasks": [t.to_dict() for t in tasks_list]
        }

        # Write to temp file and replace
        temp_fd, temp_path = tempfile.mkstemp(suffix=".json", dir=self._path.parent)
        try:
            with os.fdopen(temp_fd, "w", encoding="utf-8") as f:
                json.dump(output, f, separators=(",", ":"))

            # Atomic replace
            shutil.move(temp_path, self._path)
        except Exception:
            if os.path.exists(temp_path):
                os.remove(temp_path)
            raise

    def add(self, title: str, tags: tuple = (), priority: str = "normal", due: date | None = None) -> Task:
        """Adds a new task."""
        norm_title = normalize_title(title)

        norm_tags = []
        for t in tags:
            nt = normalize_tag(t)
            norm_tags.append(nt)
        norm_tags = sorted(set(norm_tags))

        try:
            norm_priority = normalize_priority(priority)
        except ValueError:
            raise ValueError(f"Invalid priority: {priority}")

        if due is not None:
            due_str = due.isoformat()
        else:
            due_str = None

        new_id = self._data["next_id"]
        self._data["next_id"] += 1

        new_task = Task(id=new_id, title=norm_title, tags=norm_tags, done=False, priority=norm_priority, due=due_str)
        self._tasks[new_id] = new_task

        self._save()
        return new_task

    def get(self, task_id: int) -> Task:
        """Returns a task or raises KeyError."""
        if task_id not in self._tasks:
            raise KeyError(f"Task id {task_id} not found")
        return self._tasks[task_id]

    def list(self, status: str = "open", tags: tuple = (), overdue: bool = False, today: date | None = None, sort: str = "id") -> list[Task]:
        """Returns tasks matching filters and sorting."""
        if status not in ("open", "done", "all"):
            raise ValueError(f"Invalid status: {status}")

        if overdue and today is None:
            raise ValueError("overdue=True requires today to be set")

        if sort not in ("id", "priority", "due"):
            raise ValueError(f"Invalid sort: {sort}")

        # Normalize filter tags
        filter_tags = []
        for t in tags:
            normalize_tag(t)
            filter_tags.append(t)

        result = []
        for t in self._tasks.values():
            # Check status
            match_status = (
                (status == "all") or 
                (status == "open" and not t.done) or 
                (status == "done" and t.done)
            )
            if not match_status:
                continue

            # Check tags
            match_tags = True
            if filter_tags:
                t_tags_normalized = set(normalize_tag(tag) for tag in t.tags)
                for ft in filter_tags:
                    if ft not in t_tags_normalized:
                        match_tags = False
                        break
            if not match_tags:
                continue

            # Check overdue
            if overdue:
                if t.done:
                    continue
                # Parse due date string to date object for comparison
                due_date_str = t.due
                if due_date_str is None:
                    continue
                due_date = date.fromisoformat(due_date_str)
                if due_date >= today:
                    continue

            result.append(t)

        # Sort
        def sort_key(t):
            if sort == "id":
                return (0, t.id)
            elif sort == "priority":
                prio_val = PRIORITY_ORDER.get(t.priority, 1)
                return (prio_val, t.id)
            elif sort == "due":
                has_due = 1 if t.due else 0
                due_date = date.fromisoformat(t.due) if t.due else date.max
                return (has_due, due_date, t.id)
            return (0, t.id)

        result.sort(key=sort_key)
        return result

    def mark_done(self, task_id: int) -> Task:
        """Marks a task done."""
        if task_id not in self._tasks:
            raise KeyError(f"Task id {task_id} not found")

        self._tasks[task_id].done = True
        self._save()
        return self._tasks[task_id]

    def remove(self, task_id: int) -> Task:
        """Removes a task."""
        if task_id not in self._tasks:
            raise KeyError(f"Task id {task_id} not found")

        task = self._tasks.pop(task_id)
        self._save()
        return task

    def edit(self, task_id: int, title: str | None = None, add_tags: tuple = (), remove_tags: tuple = (), 
             priority: str | None = None, due: date | None = None, clear_due: bool = False) -> Task:
        """Edits a task."""
        if task_id not in self._tasks:
            raise KeyError(f"Task id {task_id} not found")

        task = self._tasks[task_id]

        # Check for conflicting due/clear_due
        if due is not None and clear_due:
            raise ValueError("Cannot set due date and clear due date at the same time")

        # Validate title if provided
        if title is not None:
            try:
                task.title = normalize_title(title)
            except ValueError:
                raise ValueError(f"Invalid title: '{title}'")

        # Validate and add new tags
        new_tags_to_add = []
        for t in add_tags:
            try:
                nt = normalize_tag(t)
                new_tags_to_add.append(nt)
            except ValueError:
                raise ValueError(f"Invalid tag: '{t}'")

        # Remove specified tags
        task_tags_set = set(task.tags)
        for rt in remove_tags:
            task_tags_set.discard(normalize_tag(rt))

        # Update tags
        all_tags = list(task_tags_set) + new_tags_to_add
        task.tags = sorted(set(all_tags))

        # Update priority
        if priority is not None:
            try:
                task.priority = normalize_priority(priority)
            except ValueError:
                # Invalid value changes nothing (as per spec: "invalid value changes nothing")
                pass

        # Update due
        if clear_due:
            task.due = None
        elif due is not None:
            try:
                task.due = due.isoformat()
            except ValueError:
                # Invalid value changes nothing
                pass

        self._save()
        return task
