"""Command-line interface for the Todo manager."""

import argparse
import sys
from datetime import date
from pathlib import Path

from todo.store import TodoStore, StoreError

def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="todo", description="A simple CLI todo manager")
    parser.add_argument("--file", type=str, default="todo.json", help="Path to the JSON store file")
    parser.add_argument("--today", type=str, default=None, help="Date in YYYY-MM-DD format used as 'today'")

    subparsers = parser.add_subparsers(dest="command", required=True)

    # add command
    add_parser = subparsers.add_parser("add", help="Add a new task")
    add_parser.add_argument("title", type=str, help="Task title")
    add_parser.add_argument("--tag", action="append", default=[], help="Tag for the task")
    add_parser.add_argument("--priority", choices=["high", "normal", "low"], default="normal", help="Task priority")
    add_parser.add_argument("--due", type=str, help="Due date in YYYY-MM-DD format")

    # list command
    list_parser = subparsers.add_parser("list", help="List tasks")
    list_parser.add_argument("--status", choices=["open", "done", "all"], default="open", help="Filter by status")
    list_parser.add_argument("--tag", action="append", default=[], help="Filter by tag")
    list_parser.add_argument("--overdue", action="store_true", help="Show only overdue open tasks")
    list_parser.add_argument("--sort", choices=["id", "priority", "due"], default="id", help="Sort order")

    # done command
    done_parser = subparsers.add_parser("done", help="Mark tasks as done")
    done_parser.add_argument("ids", nargs="+", type=int, help="Task IDs")

    # remove command
    remove_parser = subparsers.add_parser("remove", help="Remove a task")
    remove_parser.add_argument("id", type=int, help="Task ID")

    # edit command
    edit_parser = subparsers.add_parser("edit", help="Edit a task")
    edit_parser.add_argument("id", type=int, help="Task ID")
    edit_parser.add_argument("--title", type=str, help="New title")
    edit_parser.add_argument("--tag", action="append", default=[], help="Tag to add")
    edit_parser.add_argument("--untag", action="append", default=[], help="Tag to remove")
    edit_parser.add_argument("--priority", choices=["high", "normal", "low"], help="New priority")
    edit_parser.add_argument("--due", type=str, help="New due date in YYYY-MM-DD format")
    edit_parser.add_argument("--no-due", action="store_true", help="Clear due date")

    args = parser.parse_args(argv)

    # Handle --today validation
    today_date = None
    if args.today:
        try:
            today_date = date.fromisoformat(args.today)
        except ValueError:
            print("error: invalid date format for --today", file=sys.stderr)
            return 2

    try:
        store = TodoStore(args.file)
    except StoreError as e:
        print(f"error: {e}", file=sys.stderr)
        return 3

    try:
        if args.command == "add":
            # Validate --due if provided
            due_date = None
            if args.due:
                try:
                    due_date = date.fromisoformat(args.due)
                except ValueError:
                    print(f"error: invalid date format for --due: '{args.due}'", file=sys.stderr)
                    return 2

            task = store.add(args.title, tuple(args.tag), priority=args.priority, due=due_date)
            print(f"added {task.id}")
            return 0

        elif args.command == "list":
            # If --overdue is true but --today wasn't provided via CLI (though we set today_date above)
            # The spec says: "overdue=True without today raises ValueError"
            # Since we parsed --today globally, we have today_date. If overdue flag is set and today_date is None, error.
            if args.overdue and today_date is None:
                 print("error: --overdue requires --today", file=sys.stderr)
                 return 2

            tasks = store.list(
                status=args.status, 
                tags=tuple(args.tag), 
                overdue=args.overdue, 
                today=today_date, 
                sort=args.sort
            )
            for t in tasks:
                status_str = "[x]" if t.done else "[ ]"
                line = f"{t.id} {status_str} {t.title}"

                if t.priority != "normal":
                    line += f" !{t.priority}"
                if t.due:
                    line += f" due:{t.due}"

                if t.tags:
                    line += " " + " ".join(f"#{tg}" for tg in t.tags)

                print(line)

            return 0

        elif args.command == "done":
            missing_ids = []
            for tid in args.ids:
                try:
                    store.mark_done(tid)
                    print(f"done {tid}")
                except KeyError:
                    missing_ids.append(tid)

            if missing_ids:
                print(f"error: no task with id {missing_ids[0]}", file=sys.stderr)
                return 1
            return 0

        elif args.command == "remove":
            try:
                store.remove(args.id)
                print(f"removed {args.id}")
                return 0
            except KeyError:
                print(f"error: no task with id {args.id}", file=sys.stderr)
                return 1

        elif args.command == "edit":
            # Check if at least one edit flag is provided
            has_edit = False
            if args.title: has_edit = True
            if args.tag: has_edit = True
            if args.untag: has_edit = True
            if args.priority: has_edit = True
            if args.due: has_edit = True
            if args.no_due: has_edit = True

            if not has_edit:
                print("error: edit requires at least one of --title, --tag, --untag, --priority, --due, or --no-due", file=sys.stderr)
                return 2

            # Check for conflicting --due and --no-due
            if args.due and args.no_due:
                print("error: cannot specify both --due and --no-due", file=sys.stderr)
                return 2

            # Validate inputs
            edit_errors = []

            if args.title:
                try:
                    # We don't need to actually call normalize_title here if we pass string to store, 
                    # but the store validates it. However, spec says "invalid title ... is a usage error".
                    # Let's validate here.
                    # We can't import model directly easily without circular if not careful, 
                    # but we already imported it in __init__.py logic or can import here.
                    # Since we are in cli.py, we can import from todo.model.
                    from todo.model import normalize_title
                    normalize_title(args.title)
                except ValueError:
                    print(f"error: invalid title: '{args.title}'", file=sys.stderr)
                    return 2

            if args.tag:
                from todo.model import normalize_tag
                for t in args.tag:
                    normalize_tag(t)

            if args.untag:
                from todo.model import normalize_tag
                for t in args.untag:
                    normalize_tag(t)

            if args.priority:
                from todo.model import normalize_priority
                normalize_priority(args.priority)

            if args.due:
                try:
                    date.fromisoformat(args.due)
                except ValueError:
                    print(f"error: invalid date format for --due: '{args.due}'", file=sys.stderr)
                    return 2

            if args.no_due:
                # Just a flag, no validation needed
                pass

            # All validation passed, execute
            from datetime import date as date_class
            due_val = None if args.no_due else date_class.fromisoformat(args.due) if args.due else None

            task = store.edit(
                args.id, 
                title=args.title, 
                add_tags=tuple(args.tag), 
                remove_tags=tuple(args.untag),
                priority=args.priority,
                due=due_val,
                clear_due=args.no_due
            )
            print(f"edited {args.id}")
            return 0

        except ValueError as e:
            print(f"error: {e}", file=sys.stderr)
            return 2
        except KeyError as e:
            # This is caught by specific commands, but if it bubbles up:
            print(f"error: no task with id {e.args[0] if e.args else 'unknown'}", file=sys.stderr)
            return 1

    except StoreError as e:
        print(f"error: {e}", file=sys.stderr)
        return 3

    return 0


if __name__ == "__main__":
    sys.exit(main())
