from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal
from datetime import date
from typing import Optional, List, Dict, Any

from inventory.models import InventoryError, UnknownItemError, InsufficientStockError, Item


@dataclass
class Ledger:
    _items: Dict[str, Item] = field(default_factory=dict)
    _movements: List[Movement] = field(default_factory=list)
    _last_day: Optional[date] = field(default=None)

    def add_item(self, item: Item) -> None:
        if item.sku in self._items:
            raise ValueError(f"Item with SKU {item.sku} already exists")
        self._items[item.sku] = item

    def item(self, sku: str) -> Item:
        if sku not in self._items:
            raise UnknownItemError(f"Unknown item: {sku}")
        return self._items[sku]

    def items(self) -> List[Item]:
        return [self._items[sku] for sku in sorted(self._items.keys())]

    def _validate_day(self, day: date) -> None:
        if self._last_day is not None and day < self._last_day:
            raise ValueError(f"Day {day} is earlier than the last recorded movement {self._last_day}")

    def _get_qty_on_hand(self, sku: str, location: str, as_of: Optional[date] = None) -> int:
        if sku not in self._items:
            raise UnknownItemError(f"Unknown item: {sku}")

        cutoff = as_of if as_of is not None else self._last_day
        current_qty = 0

        for m in self._movements:
            if m.sku != sku:
                continue
            if cutoff is not None and m.day > cutoff:
                continue

            if m.location == location:
                if m.kind == "receive":
                    current_qty += m.qty
                elif m.kind == "issue":
                    current_qty -= m.qty
                elif m.kind == "transfer":
                    if m.to_location == location:
                        current_qty += m.qty
                    elif m.location == location:
                        current_qty -= m.qty
        return current_qty

    def receive(self, day: date, sku: str, location: str, qty: int, unit_cost: Any) -> Movement:
        self.item(sku)
        if not isinstance(qty, int) or isinstance(qty, bool) or qty <= 0:
            raise ValueError("Quantity must be a positive integer")

        if not isinstance(unit_cost, (int, float, Decimal, str)):
            raise TypeError("unit_cost must be int, float, Decimal, or numeric string")
        if isinstance(unit_cost, str):
            try:
                unit_cost = Decimal(unit_cost)
            except:
                raise ValueError("Invalid unit_cost string")
        if isinstance(unit_cost, (int, float)):
            unit_cost = Decimal(str(unit_cost))
        if unit_cost < 0:
            raise ValueError("Unit cost cannot be negative")

        self._validate_day(day)

        movement = Movement(
            seq=len(self._movements) + 1,
            day=day,
            kind="receive",
            sku=sku,
            qty=qty,
            location=location,
            unit_cost=unit_cost
        )
        self._movements.append(movement)
        self._last_day = day
        return movement

    def issue(self, day: date, sku: str, location: str, qty: int) -> Movement:
        self.item(sku)
        if not isinstance(qty, int) or isinstance(qty, bool) or qty <= 0:
            raise ValueError("Quantity must be a positive integer")

        self._validate_day(day)

        available = self._get_qty_on_hand(sku, location)
        if available < qty:
            raise InsufficientStockError(f"Insufficient stock in {location} for SKU {sku}: need {qty}, have {available}")

        movement = Movement(
            seq=len(self._movements) + 1,
            day=day,
            kind="issue",
            sku=sku,
            qty=qty,
            location=location
        )
        self._movements.append(movement)
        self._last_day = day
        return movement

    def transfer(self, day: date, sku: str, from_location: str, to_location: str, qty: int) -> Movement:
        self.item(sku)
        if not isinstance(qty, int) or isinstance(qty, bool) or qty <= 0:
            raise ValueError("Quantity must be a positive integer")

        if from_location == to_location:
            raise ValueError("From and to locations must differ")

        self._validate_day(day)

        available = self._get_qty_on_hand(sku, from_location)
        if available < qty:
            raise InsufficientStockError(f"Insufficient stock in {from_location} for SKU {sku}: need {qty}, have {available}")

        movement = Movement(
            seq=len(self._movements) + 1,
            day=day,
            kind="transfer",
            sku=sku,
            qty=qty,
            location=from_location,
            to_location=to_location
        )
        self._movements.append(movement)
        self._last_day = day
        return movement

    def movements(self, sku: Optional[str] = None, as_of: Optional[date] = None) -> List[Movement]:
        cutoff = as_of if as_of is not None else self._last_day

        result = []
        for m in self._movements:
            if sku is not None and m.sku != sku:
                continue
            if cutoff is not None and m.day > cutoff:
                continue
            result.append(m)

        return result

    def on_hand(self, sku: str, location: Optional[str] = None, as_of: Optional[date] = None) -> int:
        self.item(sku)
        if location is None:
            total = 0
            for loc in self.locations():
                total += self._get_qty_on_hand(sku, loc, as_of)
            return total
        return self._get_qty_on_hand(sku, location, as_of)

    def locations(self) -> List[str]:
        locations = set()
        for m in self._movements:
            locations.add(m.location)
            if m.to_location:
                locations.add(m.to_location)
        return sorted(locations)
