@dataclass(frozen=True)
class Valuation:
    qty: int
    value: Decimal
    cogs: Decimal

    @classmethod
    def round_money(cls, amount: Decimal) -> Decimal:
        return amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

    def __str__(self):
        return f"Valuation(qty={self.qty}, value={self.value}, cogs={self.cogs})"


def fifo(ledger: Ledger, sku: str, as_of: Optional[date] = None) -> Valuation:
    movements = ledger.movements(sku=sku, as_of=as_of)
    if not movements:
        return Valuation(qty=0, value=Decimal("0.00"), cogs=Decimal("0.00"))

    # Build layers: list of (qty, unit_cost)
    layers: List[tuple[int, Decimal]] = []

    for m in movements:
        if m.kind == "receive":
            layers.append((m.qty, m.unit_cost))
        elif m.kind == "issue":
            if not layers:
                # Should not happen if logic is correct, but safety check
                continue

            issue_qty = m.qty
            remaining_issue = issue_qty

            for idx in range(len(layers)):
                if remaining_issue <= 0:
                    break

                layer_qty, layer_cost = layers[idx]
                take = min(remaining_issue, layer_qty)

                layers[idx] = (layer_qty - take, layer_cost)
                remaining_issue -= take

                # Remove empty layers from the front if possible, 
                # but simpler to just filter out empty ones later or skip them during consumption
                if layers[idx] == (0, layer_cost):
                    layers.pop(idx)
                    idx -= 1 # Adjust index since list shrunk

        elif m.kind == "transfer":
            # Transfer does not change cost layers, just moves stock
            pass

    # Calculate remaining stock and COGS
    remaining_qty = 0
    remaining_value = Decimal("0.00")
    cogs = Decimal("0.00")

    # We need to reconstruct the state after all moves
    # Actually, the layer approach above modifies the list in place.
    # Let's restart the layer construction logic to be cleaner.

    # Re-implementing the FIFO logic cleanly:
    # 1. Collect all receives into layers.
    # 2. Iterate through issues and subtract from oldest layers.
    # 3. Calculate final value and COGS.

    # Re-collect layers
    layers: List[tuple[int, Decimal]] = []
    for m in movements:
        if m.kind == "receive":
            layers.append((m.qty, m.unit_cost))
        elif m.kind == "issue":
            pass # Handle below
        elif m.kind == "transfer":
            pass

    # Now process issues
    for m in movements:
        if m.kind != "issue":
            continue

        issue_qty = m.qty

        # Consume from oldest layers
        while issue_qty > 0 and layers:
            layer_qty, layer_cost = layers[0]
            if layer_qty == 0:
                layers.pop(0)
                continue

            take = min(issue_qty, layer_qty)
            issue_qty -= take

            # Add to COGS
            cogs += take * layer_cost

            layers[0] = (layer_qty - take, layer_cost)
            if layers[0][0] == 0:
                layers.pop(0)

    # Calculate final value from remaining layers
    for layer_qty, layer_cost in layers:
        remaining_qty += layer_qty
        remaining_value += layer_qty * layer_cost

    remaining_value = Valuation.round_money(remaining_value)
    cogs = Valuation.round_money(cogs)

    return Valuation(qty=remaining_qty, value=remaining_value, cogs=cogs)


def average(ledger: Ledger, sku: str, as_of: Optional[date] = None) -> Valuation:
    movements = ledger.movements(sku=sku, as_of=as_of)
    if not movements:
        return Valuation(qty=0, value=Decimal("0.00"), cogs=Decimal("0.00"))

    running_qty = 0
    running_value = Decimal("0.00")
    cogs = Decimal("0.00")

    for m in movements:
        if m.kind == "receive":
            running_qty += m.qty
            running_value += m.qty * m.unit_cost
        elif m.kind == "issue":
            if running_qty <= 0:
                # This shouldn't happen with valid logic, but handle gracefully
                continue

            issue_qty = m.qty
            if issue_qty >= running_qty:
                # Issue all remaining stock
                cost = running_value
                running_qty = 0
                running_value = Decimal("0.00")
            else:
                # Issue partial stock
                avg_cost = running_value / running_qty
                # Round cost to cents for this step? 
                # Specification: "rounded to cents, except that issuing all... costs exactly the remaining value"
                # "The cost is subtracted from the running value and added to cogs"
                # Let's round the cost per unit or total? Usually total cost is rounded.
                # "rounded to cents" implies the total cost for the issue.

                total_cost = avg_cost * issue_qty
                # Round total_cost
                total_cost_rounded = Valuation.round_money(total_cost)

                # Adjust running_value slightly to ensure integer qty remains consistent if needed, 
                # but spec says subtract cost from running value.
                # To maintain precision, we subtract the rounded cost.
                running_value -= total_cost_rounded
                cogs += total_cost_rounded
                running_qty -= issue_qty
        elif m.kind == "transfer":
            pass

    running_value = Valuation.round_money(running_value)
    cogs = Valuation.round_money(cogs)

    return Valuation(qty=running_qty, value=running_value, cogs=cogs)


def valuate(ledger: Ledger, sku: str, method: str, as_of: Optional[date] = None) -> Valuation:
    if method == "fifo":
        return fifo(ledger, sku, as_of)
    elif method == "average":
        return average(ledger, sku, as_of)
    else:
        raise ValueError(f"Invalid valuation method: {method}")
