```python
# minisql/parser.py
from dataclasses import dataclass
from typing import List, Optional, Tuple, Union
from .tokens import Token, tokenize, SQLSyntaxError

# Type aliases
LiteralType = Union[int, float, str, bool, None]

@dataclass(frozen=True)
class Column:
    name: str

@dataclass(frozen=True)
class Literal:
    value: LiteralType

@dataclass(frozen=True)
class Compare:
    op: str
    left: Union[Column, Literal]
    right: Union[Column, Literal]

@dataclass(frozen=True)
class And:
    left: Union['Condition', 'Compare', 'Column', 'Literal']
    right: Union['Condition', 'Compare', 'Column', 'Literal']

@dataclass(frozen=True)
class Or:
    left: Union['Condition', 'Compare', 'Column', 'Literal']
    right: Union['Condition', 'Compare', 'Column', 'Literal']

@dataclass(frozen=True)
class Not:
    operand: Union['Condition', 'Compare', 'Column', 'Literal']

@dataclass(frozen=True)
class IsNull:
    operand: Union[Column, Literal]
    negated: bool

Condition = Union[Compare, And, Or, Not, IsNull]

@dataclass(frozen=True)
class Aggregate:
    func: str
    arg: Optional[Column]

@dataclass(frozen=True)
class Join:
    table: str
    left: Column
    right: Column

@dataclass(frozen=True)
class Select:
    columns: Optional[List[str]]
    table: str
    items: List[Tuple[Union[Column, Aggregate], str]]
    join: Optional[Join]
    where: Optional[Condition]
    group_by: List[str]
    order_by: List[Tuple[str, bool]]  # (text, descending)
    limit: Optional[int]

def _parse_operand(tokens: List[Token], pos: int) -> Tuple[Union[Column, Literal], int]:
    tk = tokens[pos]
    if tk.kind == 'IDENT':
        return Column(tk.value), pos + 1
    if tk.kind == 'NUMBER':
        return Literal(tk.value), pos + 1
    if tk.kind == 'STRING':
        return Literal(tk.value), pos + 1
    if tk.kind == 'KEYWORD':
        if tk.value == 'NULL':
            pos += 1
            return Literal(None), pos
        if tk.value == 'TRUE':
            pos += 1
            return Literal(True), pos
        if tk.value == 'FALSE':
            pos += 1
            return Literal(False), pos
    raise SQLSyntaxError(f"Unexpected token in operand: {tk.kind}", pos)

def _parse_condition(tokens: List[Token], pos: int) -> Tuple[Condition, int]:
    left, pos = _parse_atom(tokens, pos)

    while pos < len(tokens):
        tk = tokens[pos]
        if tk.kind == 'KEYWORD' and tk.value == 'OR':
            pos += 1
            right, pos = _parse_atom(tokens, pos)
            left = Or(left, right)
        elif tk.kind == 'KEYWORD' and tk.value == 'AND':
            pos += 1
            right, pos = _parse_atom(tokens, pos)
            left = And(left, right)
        elif tk.kind == 'KEYWORD' and tk.value == 'NOT':
            pos += 1
            right, pos = _parse_atom(tokens, pos)
            left = Not(right)
        else:
            break
    return left, pos

def _parse_atom(tokens: List[Token], pos: int) -> Tuple[Condition, int]:
    tk = tokens[pos]

    # Parenthesized condition
    if tk.kind == 'LPAREN':
        pos += 1
        cond, pos = _parse_condition(tokens, pos)
        if pos >= len(tokens) or tokens[pos].kind != 'RPAREN':
            raise SQLSyntaxError("Expected RPAREN", pos)
        pos += 1
        return cond, pos

    # IS NULL
    if tk.kind == 'KEYWORD' and tk.value == 'IS':
        pos += 1
        negated = False
        if pos < len(tokens) and tokens[pos].kind == 'KEYWORD' and tokens[pos].value == 'NOT':
            negated = True
            pos += 1
        if pos >= len(tokens) or tokens[pos].kind != 'KEYWORD' or tokens[pos].value != 'NULL':
            raise SQLSyntaxError("Expected NULL after IS", pos)
        pos += 1
        operand, pos = _parse_operand(tokens, pos)
        return IsNull(operand, negated), pos

    # Comparison
    left, pos = _parse_operand(tokens, pos)
    if pos < len(tokens) and tokens[pos].kind == 'OP':
        op = tokens[pos].value
        pos += 1
        right, pos = _parse_operand(tokens, pos)
        return Compare(op, left, right), pos

    raise SQLSyntaxError(f"Expected operator or IS after operand", pos)

def _parse_ref_or_agg(tokens: List[Token], pos: int) -> Tuple[Union[Column, Aggregate], int]:
    tk = tokens[pos]

    if tk.kind == 'KEYWORD':
        if tk.value in ('COUNT', 'SUM', 'AVG', 'MIN', 'MAX'):
            func = tk.value
            pos += 1
            if pos >= len(tokens) or tokens[pos].kind != 'LPAREN':
                raise SQLSyntaxError(f"Expected ( after {func}", pos)
            pos += 1
            if pos >= len(tokens) or tokens[pos].kind == 'STAR':
                # COUNT(*)
                pos += 1
                if pos >= len(tokens) or tokens[pos].kind != 'RPAREN':
                    raise SQLSyntaxError("Expected ) after *", pos)
                pos += 1
                return Aggregate(func, None), pos
            else:
                col, pos = _parse_ref(tokens, pos)
                if pos >= len(tokens) or tokens[pos].kind != 'RPAREN':
                    raise SQLSyntaxError("Expected )", pos)
                pos += 1
                return Aggregate(func, col), pos
        raise SQLSyntaxError(f"Unexpected keyword {tk.value} in select list", pos)

    if tk.kind == 'IDENT':
        col, pos = _parse_ref(tokens, pos)
        return col, pos

    raise SQLSyntaxError(f"Expected ref or aggregate, got {tk.kind}", pos)

def _parse_ref(tokens: List[Token], pos: int) -> Tuple[Column, int]:
    # ref := name | table . name
    # We need to handle dots.
    # Start with the first identifier.
    if pos >= len(tokens) or tokens[pos].kind != 'IDENT':
        raise SQLSyntaxError("Expected name", pos)

    parts = [tokens[pos].value]
    pos += 1

    while pos < len(tokens) and tokens[pos].kind == 'DOT':
        pos += 1
        if pos >= len(tokens) or tokens[pos].kind != 'IDENT':
            raise SQLSyntaxError("Expected name after .", pos)
        parts.append(tokens[pos].value)
        pos += 1

    return Column('.'.join(parts)), pos

def _parse_select_item(tokens: List[Token], pos: int) -> Tuple[Union[Column, Aggregate], str, int]:
    expr, pos = _parse_ref_or_agg(tokens, pos)

    alias = None
    if pos < len(tokens) and tokens[pos].kind == 'KEYWORD' and tokens[pos].value == 'AS':
        pos += 1
        if pos >= len(tokens) or tokens[pos].kind != 'IDENT':
            raise SQLSyntaxError("Expected alias name", pos)
        alias = tokens[pos].value
        pos += 1

    return expr, alias, pos

def _parse_select_list(tokens: List[Token], pos: int) -> Tuple[List[Tuple[Union[Column, Aggregate], str]], int]:
    if tokens[pos].kind == 'KEYWORD' and tokens[pos].value == 'STAR':
        pos += 1
        return [], pos

    items = []
    expr, alias, pos = _parse_select_item(tokens, pos)
    items.append((expr, alias))

    seen_keys = set()
    for expr, alias in items:
        # Determine canonical key
        if isinstance(expr, Column):
            key = expr.name
        else:
            key = f"{expr.func}({expr.arg.name if expr.arg else '*'})" if expr.arg else f"{expr.func}(*)"

        # Check for duplicates
        if key in seen_keys:
            raise SQLSyntaxError(f"Duplicate alias/key: {key}", expr.pos if hasattr(expr, 'pos') else pos)
        seen_keys.add(key)

    while pos < len(tokens) and tokens[pos].kind == 'COMMA':
        pos += 1
        expr, alias, pos = _parse_select_item(tokens, pos)
        items.append((expr, alias))

    return items, pos

def _parse_order_item(tokens: List[Token], pos: int) -> Tuple[str, bool, int]:
    text, pos = _parse_ref_or_agg(tokens, pos)

    descending = False
    if pos < len(tokens) and tokens[pos].kind == 'KEYWORD':
        if tokens[pos].value == 'DESC':
            pos += 1
            descending = True
        elif tokens[pos].value == 'ASC':
            pos += 1
            descending = False
        else:
            raise SQLSyntaxError(f"Unexpected keyword {tokens[pos].value} in ORDER BY", pos)

    return text, descending, pos

def _parse_grammar(tokens: List[Token], pos: int) -> Tuple[Select, int]:
    if pos >= len(tokens) or tokens[pos].kind != 'KEYWORD' or tokens[pos].value != 'SELECT':
        raise SQLSyntaxError("Expected SELECT", pos)
    pos += 1

    items, pos = _parse_select_list(tokens, pos)

    if pos >= len(tokens) or tokens[pos].kind != 'KEYWORD' or tokens[pos].value != 'FROM':
        raise SQLSyntaxError("Expected FROM", pos)
    pos += 1

    table_name, pos = _parse_ref(tokens, pos)
    # For single table, ref is just name. We take the first part.
    # But wait, if there's a join, we might have `FROM a JOIN b`. 
    # The grammar says: FROM table [JOIN table ON ...]
    # So the first table is a simple ref.
    if table_name.name.count('.') > 0:
        raise SQLSyntaxError("Table name cannot be qualified in FROM clause", table_name.pos)
    table_name_str = table_name.name.split('.')[0]

    join: Optional[Join] = None
    if pos < len(tokens) and tokens[pos].kind == 'KEYWORD' and tokens[pos].value == 'JOIN':
        pos += 1
        if pos >= len(tokens) or tokens[pos].kind != 'IDENT':
            raise SQLSyntaxError("Expected table name after JOIN", pos)
        join_table_name = tokens[pos].value
        pos += 1

        if pos >= len(tokens) or tokens[pos].kind != 'KEYWORD' or tokens[pos].value != 'ON':
            raise SQLSyntaxError("Expected ON after JOIN", pos)
        pos += 1

        left, pos = _parse_ref(tokens, pos)
        if pos >= len(tokens) or tokens[pos].kind != 'OP' or tokens[pos].value != '=':
            raise SQLSyntaxError("Expected = in ON clause", pos)
        pos += 1
        right, pos = _parse_ref(tokens, pos)
        if pos >= len(tokens) or tokens[pos].kind != 'RPAREN': # Wait, ON is not parenthesized usually
             pass # No RPAREN expected here, just next token
        if pos >= len(tokens):
             raise SQLSyntaxError("Unexpected end of input", pos)

        join = Join(join_table_name, left, right)

    where: Optional[Condition] = None
    if pos < len(tokens) and tokens[pos].kind == 'KEYWORD' and tokens[pos].value == 'WHERE':
        pos += 1
        where, pos = _parse_condition(tokens, pos)

    group_by: List[str] = []
    if pos < len(tokens) and tokens[pos].kind == 'KEYWORD' and tokens[pos].value == 'GROUP':
        pos += 1
        if pos >= len(tokens) or tokens[pos].kind != 'KEYWORD' or tokens[pos].value != 'BY':
            raise SQLSyntaxError("Expected BY after GROUP", pos)
        pos += 1
        group_by.append(_parse_ref(tokens, pos)[0].name)

        while pos < len(tokens) and tokens[pos].kind == 'COMMA':
            pos += 1
            group_by.append(_parse_ref(tokens, pos)[0].name)

    order_by: List[Tuple[str, bool]] = []
    if pos < len(tokens) and tokens[pos].kind == 'KEYWORD' and tokens[pos].value == 'ORDER':
        pos += 1
        if pos >= len(tokens) or tokens[pos].kind != 'KEYWORD' or tokens[pos].value != 'BY':
            raise SQLSyntaxError("Expected BY after ORDER", pos)
        pos += 1
        item_text, item_desc, pos = _parse_order_item(tokens, pos)
        order_by.append((item_text, item_desc))

        while pos < len(tokens) and tokens[pos].kind == 'COMMA':
            pos += 1
            item_text, item_desc, pos = _parse_order_item(tokens, pos)
            order_by.append((item_text, item_desc))

    limit: Optional[int] = None
    if pos < len(tokens) and tokens[pos].kind == 'KEYWORD' and tokens[pos].value == 'LIMIT':
        pos += 1
        num_token, pos = _parse_number_or_error(tokens, pos)
        if not isinstance(num_token.value, int):
            raise SQLSyntaxError("LIMIT requires an integer", num_token.pos)
        limit = num_token.value

    if pos < len(tokens) and tokens[pos].kind != 'EOF':
        raise SQLSyntaxError(f"Unexpected token after statement: {tokens[pos].kind}", pos)

    # Derive columns list
    columns = None
    if items:
        cols = []
        for expr, alias in items:
            if isinstance(expr, Column):
                cols.append(alias if alias else expr.name)
            else:
                # Aggregate canonical text
                arg_str = "*" if not expr.arg else expr.arg.name
                cols.append(f"{expr.func}({arg_str})")
        columns = cols

    return Select(columns=columns, table=table_name_str, items=items, join=join, where=where, group_by=group_by, order_by=order_by, limit=limit), pos

def _parse_number_or_error(tokens: List[Token], pos: int) -> Tuple[Token, int]:
    if pos >= len(tokens) or tokens[pos].kind != 'NUMBER':
        raise SQLSyntaxError(f"Expected number, got {tokens[pos].kind if pos < len(tokens) else 'EOF'}", pos)
    return tokens[pos], pos

def parse(sql: str) -> Select:
    tokens = tokenize(sql)
    select_stmt, pos = _parse_grammar(tokens, 0)
    if pos != len(tokens):
        raise SQLSyntaxError("Unexpected tokens at end of statement", pos)
    return select_stmt

