from typing import Any, Dict, List, Optional, Tuple, Union
from .tokens import Token
from .parser import (
    parse, Select, Column, Literal, Compare, And, Or, Not, IsNull,
    Aggregate, Join, Condition
)
from functools import cmp_to_key

class SQLExecutionError(Exception):
    """Raised by execute for runtime problems."""
    pass

class UnknownResult(Exception):
    pass

def _compare_values(a: Any, b: Any, op: str) -> bool:
    if a is None or b is None:
        raise UnknownResult()

    kind_a = _get_kind(a)
    kind_b = _get_kind(b)

    if kind_a != kind_b:
        if op == '=':
            return False
        elif op == '!=':
            return True
        else:
            raise SQLExecutionError(f"Cannot compare {kind_a} and {kind_b} with {op}")

    if kind_a == 'bool':
        if op == '=': return a == b
        if op == '!=': return a != b
        if op == '<': return a < b
        if op == '<=': return a <= b
        if op == '>': return a > b
        if op == '>=': return a >= b
    elif kind_a == 'str':
        if op == '=': return a == b
        if op == '!=': return a != b
        if op == '<': return a < b
        if op == '<=': return a <= b
        if op == '>': return a > b
        if op == '>=': return a >= b
    elif kind_a == 'num':
        if op == '=': return a == b
        if op == '!=': return a != b
        if op == '<': return a < b
        if op == '<=': return a <= b
        if op == '>': return a > b
        if op == '>=': return a >= b

    raise ValueError(f"Unknown op: {op}")

def _get_kind(val: Any) -> str:
    if val is None: return 'null'
    if isinstance(val, bool): return 'bool'
    if isinstance(val, (int, float)): return 'num'
    if isinstance(val, str): return 'str'
    raise ValueError(f"Unexpected type: {type(val)}")

def _get_value(row: Dict[str, Any], col_ref: Union[Column, Literal]) -> Any:
    if isinstance(col_ref, Column):
        if col_ref.name in row:
            return row[col_ref.name]
        return None
    return col_ref.value

def _evaluate_condition(condition: Condition, row: Dict[str, Any]) -> bool:
    if isinstance(condition, Compare):
        left_val = _get_value(row, condition.left)
        right_val = _get_value(row, condition.right)
        try:
            return _compare_values(left_val, right_val, condition.op)
        except UnknownResult:
            raise
        except Exception:
            raise UnknownResult()

    elif isinstance(condition, IsNull):
        val = _get_value(row, condition.operand)
        if condition.negated:
            return val is not None
        else:
            return val is None

    elif isinstance(condition, And):
        left_res = _evaluate_condition(condition.left, row)
        right_res = _evaluate_condition(condition.right, row)
        if not left_res or not right_res:
            return False
        return True

    elif isinstance(condition, Or):
        left_res = _evaluate_condition(condition.left, row)
        right_res = _evaluate_condition(condition.right, row)
        if left_res or right_res:
            return True
        return False

    elif isinstance(condition, Not):
        inner_res = _evaluate_condition(condition.operand, row)
        return not inner_res

    raise SQLExecutionError(f"Unknown condition type")

def _aggregate_func(func: str, values: List[Any]) -> Any:
    if func == 'COUNT':
        if values:
            return len(values)
        return None

    if func == 'SUM':
        if not values:
            return None
        total = 0
        for v in values:
            if isinstance(v, bool):
                raise SQLExecutionError("SUM over boolean")
            total += v
        # Determine type: int if all ints, else float
        if all(isinstance(v, int) for v in values):
            return int(total)
        return float(total)

    if func == 'AVG':
        if not values:
            return None
        total = 0
        for v in values:
            if isinstance(v, bool):
                raise SQLExecutionError("AVG over boolean")
            total += v
        return float(total / len(values))

    if func in ('MIN', 'MAX'):
        if not values:
            return None
        # Sort values to find min/max
        # We need to handle comparison carefully
        try:
            sorted_vals = sorted(values)
            return sorted_vals[0] if func == 'MIN' else sorted_vals[-1]
        except TypeError:
            raise SQLExecutionError(f"Cannot compare types for {func}")

    raise SQLExecutionError(f"Unknown aggregate: {func}")

def _get_group_key(row: Dict[str, Any], cols: List[str]) -> Tuple:
    parts = []
    for col in cols:
        val = _get_value(row, Column(col))
        parts.append((0 if val is None else 1, val))
    return tuple(parts)

def _compare_group_keys(k1: Tuple, k2: Tuple, is_desc: bool) -> int:
    # Compare tuples of (flag, value)
    for p1, p2 in zip(k1, k2):
        f1, v1 = p1
        f2, v2 = p2
        if f1 != f2:
            if is_desc:
                return (f2 - f1) # We want smaller f to come later if desc? 
                # Wait, flag 0 is NULL, 1 is non-null.
                # ASC: 0 < 1. NULL first.
                # DESC: 1 > 0. Non-null first.
                # So if f1 != f2, we compare flags normally, then reverse if desc.
                # Actually, let's just compare the values directly using a custom comparator for the whole group key.
                pass
        # Compare values
        if v1 is None:
            if v2 is None: continue
            # v1 is null, v2 is not
            if is_desc:
                return 1 # v1 (null) > v2 (val)
            else:
                return -1
        if v2 is None:
            # v1 is not, v2 is null
            if is_desc:
                return -1
            else:
                return 1

        # Both non-null
        try:
            cmp = (v1 > v2) - (v1 < v2)
            if is_desc:
                cmp = -cmp
            return cmp
        except TypeError:
            raise SQLExecutionError(f"Cannot compare group by values")
    return 0

def execute(stmt: Select, tables: Dict[str, List[Dict]]) -> List[Dict]:
    # 1. Fetch tables
    if stmt.table not in tables:
        raise SQLExecutionError(f"Unknown table: {stmt.table}")

    # Handle Join
    rows = tables[stmt.table]
    if stmt.join:
        join_info = stmt.join
        if join_info.table not in tables:
            raise SQLExecutionError(f"Unknown table: {join_info.table}")
        right_rows = tables[join_info.table]

        if join_info.table == stmt.table:
            raise SQLExecutionError("Join table must be different from left table")

        joined = []
        for r1 in rows:
            for r2 in right_rows:
                try:
                    v1 = _get_value(r1, join_info.left)
                    v2 = _get_value(r2, join_info.right)
                    # Must be equal and not unknown
                    try:
                        eq = _compare_values(v1, v2, '=')
                    except UnknownResult:
                        continue # No match
                    except Exception:
                        continue # Error match

                    if eq:
                        # Construct new row
                        # Keys: left keys in order, then right keys in order
                        # But we need to preserve order of keys as they appear in the dict?
                        # Spec: "keys `a.k` for each key of the `a` row, in its order, followed by `b.k`..."
                        # In Python 3.7+, dict order is insertion order.
                        # We construct new dict.
                        new_row = {}
                        # We need to copy keys. 
                        # Since we can't iterate keys of r1 in "order" reliably if we just do dict(r1), 
                        # we assume the provided dict has stable order.
                        # However, to be safe and explicit:
                        # The spec implies the original order.
                        # Let's just copy values.
                        for k, v in r1.items():
                            new_row[k] = v
                        for k, v in r2.items():
                            new_row[k] = v
                        joined.append(new_row)
                except Exception:
                    continue
        rows = joined

    # 2. Filter
    filtered = []
    for row in rows:
        if stmt.where is None or _evaluate_condition(stmt.where, row):
            filtered.append(row)

    # 3. Group
    grouped_rows = []
    is_grouped = len(stmt.group_by) > 0 or any(isinstance(e[0], Aggregate) for e in stmt.items)

    if is_grouped:
        if '*' in [e[0].name if isinstance(e[0], Column) else e[0].func for e in stmt.items]:
             raise SQLExecutionError("Cannot use * in grouped query")

        groups: Dict[Tuple, List[Dict]] = {}
        for row in filtered:
            if is_grouped:
                # Check if select items are valid (refs must be in group_by)
                for expr, alias in stmt.items:
                    if isinstance(expr, Column):
                        if expr.name not in stmt.group_by:
                            raise SQLExecutionError(f"SELECT column {expr.name} not in GROUP BY", expr.pos)

                key = _get_group_key(row, stmt.group_by)
            else:
                key = ()

            if key not in groups:
                groups[key] = []
            groups[key].append(row)

        grouped_rows = [rows_list for rows_list in groups.values()]
    else:
        if filtered:
            grouped_rows = [filtered]
        else:
            grouped_rows = []

    # 4. Aggregates
    aggregated_rows = []
    for group_rows in grouped_rows:
        new_row = {}
        for expr, alias in stmt.items:
            vals = []
            for row in group_rows:
                if isinstance(expr, Column):
                    v = _get_value(row, expr)
                    if v is not None:
                        vals.append(v)
                else: # Aggregate
                    vals.append(None) # Aggregate handled separately

            if isinstance(expr, Aggregate):
                # Re-evaluate aggregate on group_rows
                # COUNT(*): count all rows in group
                # COUNT(col): count non-null in group
                if expr.func == 'COUNT':
                    if expr.arg is None:
                        count = len(group_rows)
                    else:
                        count = sum(1 for r in group_rows if _get_value(r, expr.arg) is not None)
                    new_row[alias if alias else f"{expr.func}({expr.arg.name if expr.arg else '*'})"] = count
                else:
                    # Get values for the specific column
                    if expr.arg is None:
                        raise SQLExecutionError("Aggregate with * only for COUNT")
                    vals = [_get_value(r, expr.arg) for r in group_rows]
                    new_row[alias if alias else f"{expr.func}({expr.arg.name})"] = _aggregate_func(expr.func, vals)
            else:
                # Plain column, must be in group_by
                # We already validated this above
                val = _get_value(group_rows[0], expr)
                new_row[alias if alias else expr.name] = val

        aggregated_rows.append(new_row)

    # 5. Order By
    if stmt.order_by:
        sorted_rows = []
        # We need to map text to values for sorting
        # Create a list of (row, sort_key_tuple)
        sort_data = []
        for row in aggregated_rows:
            key_parts = []
            for text, desc in stmt.order_by:
                # Determine what to sort by
                # If text matches an alias, use the value of that item
                # If text matches a ref, use the value of that column
                # If text matches an aggregate, use the computed value

                found = False
                val = None
                for expr, alias in stmt.items:
                    if alias == text:
                        if isinstance(expr, Aggregate):
                            val = row[alias] # Already computed in aggregated_rows
                        else:
                            val = row[alias]
                        found = True
                        break
                    if expr.name == text:
                        val = row[expr.name]
                        found = True
                        break

                if not found:
                    raise SQLExecutionError(f"ORDER BY item {text} not found in SELECT", 0)

                key_parts.append((0 if val is None else 1, val))
            sort_data.append((row, tuple(key_parts)))

        # Sort
        sort_data.sort(key=lambda x: x[1], reverse=False) # Default ASC logic for tuples handles NULLs correctly?
        # Wait, our key parts are (flag, val). 
        # ASC: (0, None) < (0, 1). NULL first. Correct.
        # If we need DESC, we need to invert the comparison for that column specifically.
        # But the tuple sort doesn't support per-element direction.
        # We must use cmp_to_key again.

        def cmp_rows(r1_data, r2_data):
            key1, key2 = r1_data[1], r2_data[1]
            for p1, p2, desc in zip(key1, key2, stmt.order_by):
                f1, v1 = p1
                f2, v2 = p2
                # Handle nulls
                if v1 is None and v2 is None:
                    continue
                if v1 is None:
                    # v1 is null
                    if desc:
                        return 1 # v1 > v2
                    return -1 # v1 < v2
                if v2 is None:
                    if desc:
                        return -1
                    return 1
                # Both non-null
                try:
                    cmp = (v1 > v2) - (v1 < v2)
                    if desc:
                        cmp = -cmp
                    return cmp
                except TypeError:
                    raise SQLExecutionError(f"Cannot compare ORDER BY values")

        sorted_rows = [item[0] for item in sort_data]

    # 6. Limit
    if stmt.limit is not None:
        sorted_rows = sorted_rows[:stmt.limit]

    # 7. Project (Output keys)
    result = []
    if stmt.columns is None:
        # SELECT *
        for row in sorted_rows:
            result.append(dict(row))
    else:
        for row in sorted_rows:
            new_row = {}
            for key in stmt.columns:
                # Find which item produces this key
                val = None
                for expr, alias in stmt.items:
                    if alias == key:
                        val = row[alias]
                        break
                    if isinstance(expr, Column) and expr.name == key:
                        val = row[expr.name]
                        break
                new_row[key] = val
            result.append(new_row)

    return result

