# fsm/machine.py

from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Optional, Union, Tuple

class MachineError(Exception):
    pass

class InvalidTransition(MachineError):
    def __init__(self, state: str, event: str):
        self.state = state
        self.event = event
        super().__init__(f"No transition for event '{event}' from state '{state}'")

class GuardRejected(MachineError):
    def __init__(self, state: str, event: str):
        self.state = state
        self.event = event
        super().__init__(f"All guards rejected for event '{event}' from state '{state}'")

@dataclass
class State:
    name: str
    on_enter: Optional[Callable] = None
    on_exit: Optional[Callable] = None

@dataclass
class Transition:
    event: str
    source: Union[str, Tuple[str, ...], List[str]]
    target: Optional[str]
    guard: Optional[Callable] = None
    action: Optional[Callable] = None

    def __post_init__(self):
        if isinstance(self.source, str):
            self.source = (self.source,)
        self.source = tuple(self.source)

@dataclass
class Event:
    name: str
    source: str
    target: str
    data: dict = field(default_factory=dict)

class Machine:
    def __init__(self, states: List[Union[str, State]], transitions: List[Transition], initial: str, context: Any = None):
        if not states:
            raise ValueError("States list cannot be empty")

        state_names = {}
        for item in states:
            if isinstance(item, str):
                name = item
                hooks = {}
            else:
                name = item.name
                hooks = {'on_enter': item.on_enter, 'on_exit': item.on_exit}

            if name in state_names:
                raise ValueError(f"Duplicate state name: {name}")
            state_names[name] = hooks

        if initial not in state_names:
            raise ValueError(f"Initial state '{initial}' not found in states")

        self._states = state_names
        self._initial = initial
        self.context = context
        self.history: List[Tuple[str, str, str]] = []
        self._listeners: List[Callable] = []

        # Validate transitions
        for t in transitions:
            if t.source not in state_names:
                raise ValueError(f"Transition source '{t.source}' not in states")
            if t.target is not None and t.target not in state_names:
                raise ValueError(f"Transition target '{t.target}' not in states")
            if not isinstance(t.source, tuple):
                raise ValueError(f"Transition source must be tuple/list/string")

            # Validate guard/action signatures later in fire, but ensure they exist
            if t.guard is not None and not callable(t.guard):
                raise ValueError("Guard must be callable")
            if t.action is not None and not callable(t.action):
                raise ValueError("Action must be callable")

        self._transitions = transitions

    @property
    def state(self) -> str:
        return self._current_state

    @property
    def context(self) -> Any:
        return self._context

    @property
    def history(self) -> List[Tuple[str, str, str]]:
        return self._history

    def _get_state_hooks(self, name: str) -> Dict[str, Callable]:
        return self._states.get(name, {})

    def _get_transition(self, event: str, source_tuple: Tuple[str, ...]) -> Optional[Transition]:
        for t in self._transitions:
            if t.event == event:
                if isinstance(t.source, tuple):
                    if source_tuple[0] in t.source:
                        return t
                return None
        return None

    def _create_event(self, name: str, source: str, target: str, data: dict) -> Event:
        return Event(name=name, source=source, target=target, data=data)

    def _call_hooks(self, hooks: Dict[str, Callable], event: Event, hook_names: List[str]):
        for hook_name in hook_names:
            hook = hooks.get(hook_name)
            if hook:
                hook(self, event)

    def _add_listener(self, listener: Callable):
        self._listeners.append(listener)

    def on_transition(self, listener: Callable):
        self._add_listener(listener)

    def reset(self):
        self._current_state = self._initial
        self._history.clear()

    def can_fire(self, event: str, **data) -> bool:
        candidates = self._get_candidates(event, tuple(self._current_state))
        if not candidates:
            return False

        # Check guards
        for t in candidates:
            if t.guard is None:
                return True
            # Create a temporary event for guard check
            temp_event = self._create_event(event, self._current_state, t.target if t.target else self._current_state, data)
            if t.guard(self, temp_event):
                return True
        return False

    def available_events(self) -> List[str]:
        current = self._current_state
        events = set()
        for t in self._transitions:
            if current in t.source and t.event:
                events.add(t.event)
        return sorted(events)

    def fire(self, event: str, **data) -> str:
        import threading
        if hasattr(self, '_fire_running') and self._fire_running:
            raise MachineError("Machine is already running a fire operation")

        self._fire_running = True
        try:
            candidates = self._get_candidates(event, tuple(self._current_state))
            if not candidates:
                raise InvalidTransition(self._current_state, event)

            event_obj = self._create_event(event, self._current_state, None, data)

            # Evaluate guards
            chosen = None
            for t in candidates:
                if t.guard is None:
                    chosen = t
                    break
                if t.guard(self, event_obj):
                    chosen = t
                    break

            if chosen is None:
                raise GuardRejected(self._current_state, event)

            # Determine if internal
            is_internal = chosen.target is None

            # Execute hooks based on type
            if is_internal:
                # Internal: only action, history, listeners
                if chosen.action:
                    chosen.action(self, event_obj)

                self._history.append((self._current_state, event, self._current_state))
                for listener in self._listeners:
                    listener(self._current_state, event_obj, self._current_state)
            else:
                # Normal transition
                # 1. Current state on_exit
                hooks = self._get_state_hooks(self._current_state)
                if hooks.get('on_exit'):
                    hooks['on_exit'](self, event_obj)

                # 2. Transition action
                if chosen.action:
                    chosen.action(self, event_obj)

                # 3. Update state
                new_state = chosen.target
                self._current_state = new_state

                # 4. Append history
                self._history.append((self._current_state, event, new_state))

                # 5. Target state on_enter
                hooks = self._get_state_hooks(new_state)
                if hooks.get('on_enter'):
                    hooks['on_enter'](self, event_obj)

                # 6. Listeners
                for listener in self._listeners:
                    listener(self._current_state, event_obj, new_state)

            return self._current_state

        finally:
            self._fire_running = False

    def _get_candidates(self, event: str, source: Tuple[str, ...]) -> List[Transition]:
        # Source can be '*' or specific states
        if '*' in source:
            match_states = self._states.keys()
        else:
            match_states = source

        candidates = []
        for t in self._transitions:
            if t.event == event:
                # Check source match
                if '*' in t.source or any(s in t.source for s in match_states):
                    candidates.append(t)
        return candidates

