# vending.py

import math
from fsm import Machine, State, Transition

class VendingError(Exception):
    pass

class SoldOut(VendingError):
    pass

class InsufficientCredit(VendingError):
    pass

COINS = [100, 25, 10, 5]

class VendingMachine:
    def __init__(self, products: dict[str, tuple[int, int]]):
        self._products = dict(products)
        self._sales = {}
        self._revenue = 0
        self._credit = 0
        self._state = 'idle'

        # Build FSM
        states = [
            State('idle'),
            State('credit'),
            State('maintenance')
        ]

        transitions = []

        # Idle -> Credit (insert coin)
        def check_coin(m, e):
            coin = e.data['coin']
            return coin in COINS

        def add_credit(m, e):
            m._credit += e.data['coin']

        # Insert transitions
        for coin in COINS:
            transitions.append(Transition(
                event='insert',
                source='idle',
                target='credit',
                guard=check_coin,
                action=add_credit
            ))

        # Credit -> Idle (select)
        def do_select(m, e):
            code = e.data['code']
            price = m._products.get(code, None)
            if price is None:
                raise KeyError(f"Unknown product: {code}")

            qty = m._products[code][1]
            if qty <= 0:
                raise SoldOut(f"Product {code} is out of stock")

            if m._credit < price:
                raise InsufficientCredit(f"Insufficient credit for {code}")

            # Update stock
            m._products[code] = (price, qty - 1)
            if code not in m._sales:
                m._sales[code] = 0
            m._sales[code] += 1
            m._revenue += price
            m._credit = 0

        transitions.append(Transition(
            event='select',
            source='credit',
            target='idle',
            action=do_select
        ))

        # Credit -> Idle (cancel)
        def do_cancel(m, e):
            change = []
            remaining = m._credit
            for coin in COINS:
                while remaining >= coin:
                    change.append(coin)
                    remaining -= coin
            m._credit = 0
            e.data['change'] = change

        transitions.append(Transition(
            event='cancel',
            source='credit',
            target='idle',
            action=do_cancel
        ))

        # Idle -> Maintenance
        transitions.append(Transition(
            event='service',
            source='idle',
            target='maintenance'
        ))

        # Maintenance -> Idle
        transitions.append(Transition(
            event='resume',
            source='maintenance',
            target='idle'
        ))

        self.machine = Machine(states, transitions, initial='idle', context=self)
        self.machine.on_transition(self._on_fsm_transition)

    def _on_fsm_transition(self, source: str, event: Event, target: str):
        # Helper to update internal state after FSM transition
        self._state = target

    @property
    def state(self) -> str:
        return self._state

    @property
    def credit(self) -> int:
        return self._credit

    def stock(self, code: str) -> int:
        if code not in self._products:
            raise KeyError(f"Unknown product: {code}")
        return self._products[code][1]

    def price(self, code: str) -> int:
        if code not in self._products:
            raise KeyError(f"Unknown product: {code}")
        return self._products[code][0]

    def sales(self) -> dict[str, int]:
        return dict(self._sales)

    @property
    def revenue(self) -> int:
        return self._revenue

    def insert(self, coin: int) -> int:
        if self._state not in ('idle', 'credit'):
            raise VendingError(f"Insert not allowed in state {self._state}")

        if coin not in COINS:
            raise ValueError(f"Invalid coin: {coin}")

        self.machine.fire('insert', coin=coin)
        return self._credit

    def select(self, code: str) -> list[int]:
        if self._state != 'credit':
            raise VendingError(f"Select not allowed in state {self._state}")

        if code not in self._products:
            raise KeyError(f"Unknown product: {code}")

        price = self._products[code][0]
        if self._credit < price:
            raise InsufficientCredit(f"Insufficient credit for {code}")

        # Check stock before committing to avoid race conditions in logic
        if self.stock(code) <= 0:
            raise SoldOut(f"Product {code} is out of stock")

        self.machine.fire('select', code=code)
        change = []
        remaining = self._credit
        for coin in COINS:
            while remaining >= coin:
                change.append(coin)
                remaining -= coin
        return change

    def cancel(self) -> list[int]:
        if self._state != 'credit':
            raise VendingError(f"Cancel not allowed in state {self._state}")

        self.machine.fire('cancel')
        change = []
        remaining = self._credit
        for coin in COINS:
            while remaining >= coin:
                change.append(coin)
                remaining -= coin
        return change

    def service(self) -> None:
        if self._state != 'idle':
            raise VendingError(f"Service not allowed in state {self._state}")

        self.machine.fire('service')

    def restock(self, code: str, qty: int, price: int = None) -> None:
        if self._state != 'maintenance':
            raise VendingError(f"Restock not allowed in state {self._state}")

        if qty < 1:
            raise ValueError("Quantity must be at least 1")

        if code not in self._products:
            if price is None:
                raise KeyError(f"New product {code} requires a price")
            self._products[code] = (price, qty)
        else:
            # Update existing
            current_price = self._products[code][0]
            if price is not None:
                current_price = price
            self._products[code] = (current_price, self._products[code][1] + qty)

    def resume(self) -> None:
        if self._state != 'maintenance':
            raise VendingError(f"Resume not allowed in state {self._state}")

        self.machine.fire('resume')
