# books/accounts.py
from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal
from datetime import date
from enum import Enum, auto
from typing import Optional


class AccountType(Enum):
    ASSET = "asset"
    LIABILITY = "liability"
    EQUITY = "equity"
    INCOME = "income"
    EXPENSE = "expense"


# Helper to normalize amounts
def _normalize_amount(val) -> Decimal:
    if isinstance(val, Decimal):
        pass
    elif isinstance(val, int):
        pass
    elif isinstance(val, str):
        try:
            d = Decimal(val)
        except Exception:
            raise ValueError(f"Invalid amount string: {val}")
    else:
        # Covers float and other numeric types not covered above
        raise TypeError(f"Amount must be Decimal, int, or numeric str, not {type(val).__name__}")

    # Check for more than 2 decimal places
    if d.as_tuple().exponent < -2:
        raise ValueError(f"Amount has more than two decimal places: {d}")

    return d


@dataclass(frozen=True)
class Account:
    code: str
    name: str
    type: AccountType
    parent: Optional[str] = None


class Chart:
    def __init__(self):
        # Map code -> Account
        self._accounts: dict[str, Account] = {}
        # Map code -> list of child codes
        self._children: dict[str, list[str]] = {}
        self._root_codes: set[str] = set()

    def _check_code(self, code: str) -> None:
        if not code:
            raise ValueError("Code must be non-empty")
        if not code.isdigit():
            raise ValueError("Code must be digits only")

    def _check_type(self, type_input) -> AccountType:
        if isinstance(type_input, AccountType):
            return type_input
        elif isinstance(type_input, str):
            try:
                return AccountType(type_input)
            except ValueError:
                raise ValueError(f"Unknown account type: {type_input}")
        else:
            raise ValueError(f"Invalid account type: {type_input}")

    def add(self, code: str, name: str, type_input, parent: Optional[str] = None) -> Account:
        self._check_code(code)
        acc_type = self._check_type(type_input)

        # Check existence
        if code in self._accounts:
            raise ValueError(f"Account code {code} already exists")

        # Check parent existence if provided
        if parent is not None:
            if parent not in self._accounts:
                raise ValueError(f"Parent account {parent} does not exist")
            parent_acc = self._accounts[parent]
            # Check parent type compatibility
            if parent_acc.type != acc_type:
                raise ValueError(f"Parent account {parent} has different type: {parent_acc.type}")

        # Create account
        acc = Account(code=code, name=name, type=acc_type, parent=parent)
        self._accounts[code] = acc

        # Update tree structure
        if parent is None:
            self._root_codes.add(code)
        else:
            if code not in self._children.get(parent, []):
                self._children.setdefault(parent, []).append(code)

        return acc

    def get(self, code: str) -> Account:
        if code not in self._accounts:
            raise KeyError(f"Unknown account code: {code}")
        return self._accounts[code]

    def children(self, code: str) -> list[Account]:
        child_codes = self._children.get(code, [])
        child_codes.sort()  # Sort by code
        return [self._accounts[c] for c in child_codes]

    def roots(self) -> list[Account]:
        codes = sorted(self._root_codes)
        return [self._accounts[c] for c in codes]

    def is_leaf(self, code: str) -> bool:
        if code not in self._accounts:
            raise KeyError(f"Unknown account code: {code}")
        return code not in self._children

    def walk(self) -> list[tuple[Account, int]]:
        result = []

        # Helper for DFS
        def dfs(acc: Account, depth: int):
            result.append((acc, depth))
            # Sort children by code to ensure consistent order
            child_codes = sorted(self._children.get(acc.code, []))
            for c in child_codes:
                dfs(self._accounts[c], depth + 1)

        # Start DFS from roots in code order
        root_codes = sorted(self._root_codes)
        for r in root_codes:
            dfs(self._accounts[r], 0)

        return result
