from __future__ import annotations

from dataclasses import dataclass, field
from decimal import Decimal
from datetime import date
from typing import NamedTuple, Optional
from .accounts import Account, AccountType, Chart
from .accounts import _normalize_amount


class UnbalancedEntryError(ValueError):
    pass


@dataclass(frozen=True)
class Line:
    account: str
    debit: Decimal = Decimal(0)
    credit: Decimal = Decimal(0)


@dataclass(frozen=True)
class Entry:
    number: int
    day: date
    memo: str
    lines: tuple[Line, ...]


LedgerRow = NamedTuple(
    "LedgerRow",
    [
        ("number", int),
        ("day", date),
        ("memo", str),
        ("debit", Decimal),
        ("credit", Decimal),
        ("balance", Decimal),
    ]
)


class Journal:
    def __init__(self, chart: Chart):
        self._chart = chart
        self._entries: list[Entry] = []
        self._counter = 0

    def _validate_amount(self, val) -> Decimal:
        # This wraps the logic to ensure we raise TypeError for floats
        # and ValueError for negatives or >2 decimals
        d = _normalize_amount(val)
        if d < 0:
            raise ValueError(f"Amount cannot be negative: {d}")
        return d

    def post(self, day: date, memo: str, lines: list[Line]) -> Entry:
        # 1. Check at least two lines
        if len(lines) < 2:
            raise ValueError("Entry must have at least two lines")

        # Pre-process lines to ensure amounts are valid Decimals
        processed_lines = []
        for line in lines:
            acc = self._chart.get(line.account)

            # Validate amount types
            debit = self._validate_amount(line.debit)
            credit = self._validate_amount(line.credit)

            # Convert to Line with validated decimals
            processed_lines.append(Line(
                account=line.account,
                debit=debit,
                credit=credit
            ))

        # 2. Check account existence and leaf status
        for line in processed_lines:
            if line.account not in self._chart._accounts:
                raise KeyError(f"Unknown account: {line.account}")
            if not self._chart.is_leaf(line.account):
                raise ValueError(f"Account {line.account} is not a leaf")

        # 3. Check amounts: exactly one of debit/credit non-zero
        for line in processed_lines:
            if line.debit == 0 and line.credit == 0:
                raise ValueError("Line must have non-zero debit or credit")
            if line.debit > 0 and line.credit > 0:
                raise ValueError("Line cannot have both debit and credit")

        # 4. Check balance
        total_debit = sum(l.debit for l in processed_lines)
        total_credit = sum(l.credit for l in processed_lines)
        if total_debit != total_credit:
            raise UnbalancedEntryError(f"Entry is unbalanced: debits={total_debit}, credits={total_credit}")

        # Create Entry
        self._counter += 1
        entry = Entry(
            number=self._counter,
            day=day,
            memo=memo,
            lines=tuple(processed_lines)
        )
        self._entries.append(entry)
        return entry

    def entries(self) -> list[Entry]:
        # Already stored in number order (1, 2, 3...)
        return list(self._entries)

    def balance(self, code: str, start: Optional[date] = None, end: Optional[date] = None) -> Decimal:
        if code not in self._accounts:
            raise KeyError(f"Unknown account: {code}")

        # Get all descendants
        target_codes = {code}
        # BFS/DFS to find all descendants
        stack = [code]
        while stack:
            curr = stack.pop()
            for child_code in self._chart.children(curr):
                target_codes.add(child_code)
                stack.append(child_code)

        # Filter entries by date range
        valid_entries = []
        for entry in self._entries:
            if start and entry.day < start:
                continue
            if end and entry.day > end:
                continue
            valid_entries.append(entry)

        # Calculate balance
        total = Decimal(0)
        for entry in valid_entries:
            for line in entry.lines:
                if line.account not in target_codes:
                    continue

                acc = self._chart.get(line.account)
                acc_type = acc.type

                # Debit-normal: Asset, Expense
                if acc_type in (AccountType.ASSET, AccountType.EXPENSE):
                    if line.debit > 0:
                        total += line.debit
                    if line.credit > 0:
                        total -= line.credit
                # Credit-normal: Liability, Equity, Income
                else:
                    if line.credit > 0:
                        total += line.credit
                    if line.debit > 0:
                        total -= line.debit

        return total

    def ledger(self, code: str) -> list[LedgerRow]:
        if code not in self._accounts:
            raise KeyError(f"Unknown account: {code}")

        # Get all descendant codes
        target_codes = set()
        stack = [code]
        while stack:
            curr = stack.pop()
            target_codes.add(curr)
            for child_code in self._chart.children(curr):
                target_codes.add(child_code)
                stack.append(child_code)

        rows = []
        # Collect all lines for target accounts from all entries
        # Sort criteria: day, entry number, line position
        all_rows_data = []

        for entry in self._entries:
            for idx, line in enumerate(entry.lines):
                if line.account not in target_codes:
                    continue

                acc = self._chart.get(line.account)
                acc_type = acc.type
                is_debit_normal = acc_type in (AccountType.ASSET, AccountType.EXPENSE)

                debit = line.debit
                credit = line.credit

                # Determine the movement on the normal side
                movement = Decimal(0)
                if is_debit_normal:
                    movement = debit - credit
                else:
                    movement = credit - debit

                # Calculate running balance
                # We need to sort all rows by (day, number, idx) before calculating running balance
                # So we store data first
                all_rows_data.append({
                    'day': entry.day,
                    'number': entry.number,
                    'idx': idx,
                    'debit': debit,
                    'credit': credit,
                    'movement': movement,
                    'account': line.account
                })

        # Sort
        all_rows_data.sort(key=lambda x: (x['day'], x['number'], x['idx']))

        running_balance = Decimal(0)
        result = []
        for r in all_rows_data:
            running_balance += r['movement']
            result.append(LedgerRow(
                number=r['number'],
                day=r['day'],
                memo=r['memo'] if False else "", # Memo is from entry, but we don't store it here easily without changing structure. 
                                                  # The prompt implies LedgerRow has memo. 
                                                  # Let's re-read: "one row per line posted... balance is running balance".
                                                  # It doesn't explicitly say to include the memo from the entry in the row, 
                                                  # but NamedTuple definition has it. 
                                                  # Usually ledger rows inherit memo. Let's assume we can't easily attach memo 
                                                  # to every line if multiple lines per entry share one memo.
                                                  # However, the spec says "LedgerRow: a NamedTuple (number, day, memo, debit, credit, balance)".
                                                  # If an entry has multiple lines, do they all have the same memo? Yes.
                                                  # But we filtered lines. We need to attach the memo from the entry.
                                                  # Let's fix the data structure slightly to hold memo.
                debit=r['debit'],
                credit=r['credit'],
                balance=running_balance
            ))

        # Wait, I need memo. Let's reconstruct properly.
        # Re-doing the collection to include memo.

        all_rows_data = []
