# books/statements.py
from __future__ import annotations

from decimal import Decimal
from datetime import date
from typing import Optional
from .accounts import Chart, AccountType
from .journal import Journal, Entry, LedgerRow


def _format_amount(val: Decimal) -> str:
    # Exactly two decimals, leading - if negative
    return f"{val:+.2f}".replace("-+", "-").replace("+", "")


def _format_date(d: Optional[date]) -> str:
    if d is None:
        return ""
    return d.strftime("%Y-%m-%d")


def _get_lines_for_code(chart: Chart, code: str, start: Optional[date], end: Optional[date], journal: Journal) -> list[Entry]:
    """Returns list of entries that touch 'code' or its descendants within the date range."""
    target_codes = {code}
    stack = [code]
    while stack:
        curr = stack.pop()
        for child_code in chart.children(curr):
            target_codes.add(child_code)
            stack.append(child_code)

    relevant_entries = []
    for entry in journal.entries():
        if start and entry.day < start:
            continue
        if end and entry.day > end:
            continue

        # Check if any line touches a target code
        has_target = False
        for line in entry.lines:
            if line.account in target_codes:
                has_target = True
                break

        if has_target:
            relevant_entries.append(entry)

    return relevant_entries


def trial_balance(journal: Journal, as_of: Optional[date] = None) -> str:
    lines = []

    title = f"TRIAL BALANCE as of {_format_date(as_of)}" if as_of else "TRIAL BALANCE"
    lines.append(title)

    # Period: every entry with day <= as_of (all if None)
    period_end = as_of

    # We need to iterate in walk() order
    for acc, depth in chart.walk():
        # Calculate balance for this account (including descendants)
        bal = journal.balance(acc.code, start=None, end=period_end)

        # Check if account or any descendant has lines in the period
        # To do this efficiently, we check if balance != 0 is NOT enough because balance could be 0 due to offsetting transactions.
        # We must check if there are ANY lines posted.
        # Actually, the requirement says: "account is shown only if it or a descendant has at least one line".
        # We can infer this by checking if the sum of absolute movements is > 0, but simpler:
        # Just check if the account exists in any entry in the period.

        # Let's re-scan entries for this specific tree to see if any lines exist.
        has_lines = False
        period_entries = [e for e in journal.entries() if (as_of is None or e.day <= as_of)]

        target_codes = {acc.code}
        stack = [acc.code]
        while stack:
            curr = stack.pop()
            for c in journal._chart.children(curr):
                target_codes.add(c)
                stack.append(c)

        for entry in period_entries:
            for line in entry.lines:
                if line.account in target_codes:
                    has_lines = True
                    break
            if has_lines:
                break

        if not has_lines:
            continue

        lines.append(f"{'  ' * depth}{acc.code} {acc.name}: {_format_amount(bal)}")

    # Totals
    total_debits = Decimal(0)
    total_credits = Decimal(0)

    # "For every account that has lines of its own..."
    # This implies we iterate through ALL accounts in the chart (or at least those with lines of their own).
    # The prompt says: "Then the account lines for the whole chart."
    # So we iterate roots and their children again to find accounts with lines OF THEIR OWN.

    all_accounts = []
    for _, _ in chart.walk():
        all_accounts.append(_)

    for acc, depth in all_accounts:
        # Check if account has lines of ITS OWN (not just descendants) in the period
        acc_has_own_lines = False
        period_entries = [e for e in journal.entries() if (as_of is None or e.day <= as_of)]

        for entry in period_entries:
            for line in entry.lines:
                if line.account == acc.code:
                    acc_has_own_lines = True
                    break
            if acc_has_own_lines:
                break

        if not acc_has_own_lines:
            continue

        # Calculate net flow for this account
        net = Decimal(0)
        for entry in period_entries:
            for line in entry.lines:
                if line.account == acc.code:
                    acc_type = acc.type
                    if acc_type in (AccountType.ASSET, AccountType.EXPENSE):
                        net -= line.credit
                        net += line.debit
                    else:
                        net += line.credit
                        net -= line.debit

        if net > 0:
            total_debits += net
        else:
            total_credits += abs(net)

    lines.append(f"Total debits: {total_debits:.2f}")
    lines.append(f"Total credits: {total_credits:.2f}")

    return "\n".join(lines) + "\n"


def income_statement(journal: Journal, start: date, end: date) -> str:
    if start > end:
        raise ValueError("Start date must be before end date")

    lines = []
    lines.append(f"INCOME STATEMENT {_format_date(start)} to {_format_date(end)}")

    # Filter entries
    period_entries = [e for e in journal.entries() if start <= e.day <= end]

    # Income Section
    lines.append("Income")
    total_income = Decimal(0)

    # Get income accounts (roots)
    income_roots = [acc for acc, _ in chart.walk() if acc.type == AccountType.INCOME and not chart.children(acc.code)]
    # Wait, walk() gives all. We need roots of type INCOME.
    # The prompt example shows "4000 Revenue" then indented "4100 Sales".
    # This implies we iterate the chart in walk() order, but only show INCOME accounts?
    # "then the account lines of the income accounts"
    # "The totals are the sums of the shown root accounts of that type"
    # So we iterate ALL accounts in walk() order. If an account is INCOME type, show it.
    # If it's not INCOME, skip it (but its descendants might be? No, "account lines of the income accounts").
    # Usually, if a parent is income, children are income. The example shows 4000 -> 4100. Both are income.
    # So we iterate walk(), if type == INCOME, show it.

    # However, we only show if it or descendant has lines.

    # Let's collect all income accounts first to know which are roots vs children
    # But we need to print in walk() order.

    # Strategy:
    # 1. Iterate walk().
    # 2. If type == INCOME:
    #    a. Check if it or descendants have lines in period.
    #    b. If yes, print line.
    #    c. Accumulate balance into total_income IF it is a ROOT income account.

    # Same for Expenses.

    # We need to distinguish between showing a line and summing for total.
    # Total is sum of ROOT accounts of that type.

    # Helper to check visibility
    def has_activity_in_period(code: str) -> bool:
        target_codes = {code}
        stack = [code]
        while stack:
            curr = stack.pop()
            for c in journal._chart.children(curr):
                target_codes.add(c)
                stack.append(c)

        for entry in period_entries:
            for line in entry.lines:
                if line.account in target_codes:
                    return True
        return False

    # Helper to get balance for a specific account in period
    def get_balance(code: str) -> Decimal:
        return journal.balance(code, start, end)

    # Process Income
    for acc, depth in chart.walk():
        if acc.type == AccountType.INCOME:
            if has_activity_in_period(acc.code):
                bal = get_balance(acc.code)
                lines.append(f"{'  ' * depth}{acc.code} {acc.name}: {_format_amount(bal)}")
                if acc.parent is None:
                    total_income += bal

    lines.append(f"Total income: {total_income:.2f}")

    # Process Expenses
    lines.append("Expenses")
    total_expenses = Decimal(0)

    for acc, depth in chart.walk():
        if acc.type == AccountType.EXPENSE:
            if has_activity_in_period(acc.code):
                bal = get_balance(acc.code)
                lines.append(f"{'  ' * depth}{acc.code} {acc.name}: {_format_amount(bal)}")
                if acc.parent is None:
                    total_expenses += bal

    lines.append(f"Total expenses: {total_expenses:.2f}")

    net_income = total_income - total_expenses
    lines.append(f"Net income: {net_income:.2f}")

    return "\n".join(lines) + "\n"
