from typing import Optional, Dict, List, Tuple, Any, Iterator

# Reason phrases
REASON_PHRASES = {
    200: 'OK',
    201: 'Created',
    204: 'No Content',
    400: 'Bad Request',
    401: 'Unauthorized',
    404: 'Not Found',
    405: 'Method Not Allowed',
    500: 'Internal Server Error',
}

def get_reason_phrase(status: int) -> str:
    return REASON_PHRASES.get(status, 'Unknown')

class HTTPError(Exception):
    def __init__(self, status: int, reason: str = None):
        self.status = status
        self.reason = reason if reason else get_reason_phrase(status)
        super().__init__(f"{self.status} {self.reason}")

class BadRequest(HTTPError):
    def __init__(self, message: str = None):
        super().__init__(400, message or 'Bad Request')

@dataclass
class Headers:
    _pairs: List[Tuple[str, str]] = field(default_factory=list)

    def add(self, name: str, value: str):
        self._pairs.append((name, value))

    def set(self, name: str, value: str):
        # Remove existing
        self._pairs = [(n, v) for n, v in self._pairs if n.lower() != name.lower()]
        # Add new
        self._pairs.append((name, value))

    def get(self, name: str, default: Any = None) -> Any:
        for n, v in self._pairs:
            if n.lower() == name.lower():
                return v
        return default

    def __getitem__(self, name: str) -> str:
        try:
            return self.get(name)
        except TypeError:
            raise KeyError(name)

    def get_all(self, name: str) -> List[str]:
        result = []
        for n, v in self._pairs:
            if n.lower() == name.lower():
                result.append(v)
        return result

    def __contains__(self, name: str) -> bool:
        for n, v in self._pairs:
            if n.lower() == name.lower():
                return True
        return False

    def __len__(self) -> int:
        return len(self._pairs)

    def items(self) -> Iterator[Tuple[str, str]]:
        return iter(self._pairs)

@dataclass
class Request:
    method: str
    target: str
    path: str
    query_string: str
    version: str
    headers: Headers
    body: bytes
    params: Dict[str, Any] = field(default_factory=dict)
    state: Dict[str, Any] = field(default_factory=dict)

    @property
    def query(self) -> Dict[str, List[str]]:
        if not self.query_string:
            return {}
        result: Dict[str, List[str]] = {}
        for piece in self.query_string.split('&'):
            if not piece:
                continue
            if '=' in piece:
                name, val = piece.split('=', 1)
            else:
                name, val = piece, ''
            # Decode
            name_dec = self._decode_uri_component(name)
            val_dec = self._decode_uri_component(val)
            if name_dec not in result:
                result[name_dec] = []
            result[name_dec].append(val_dec)
        return result

    @property
    def content_type(self) -> Tuple[str, Dict[str, str]]:
        ct = self.headers.get('Content-Type', '')
        if not ct:
            return ('', {})
        parts = ct.split(';')
        media_type = parts[0].strip().lower()
        params: Dict[str, str] = {}
        for part in parts[1:]:
            part = part.strip()
            if not part:
                continue
            if '=' in part:
                key, val = part.split('=', 1)
                key = key.strip().lower()
                val = val.strip()
                if val.startswith('"') and val.endswith('"') and len(val) >= 2:
                    val = val[1:-1]
                params[key] = val
        return (media_type, params)

    def text(self) -> str:
        media_type, params = self.content_type
        charset = params.get('charset', 'utf-8')
        try:
            return self.body.decode(charset)
        except LookupError:
            raise BadRequest(f"Unknown charset: {charset}")
        except UnicodeDecodeError as e:
            raise BadRequest(f"Invalid UTF-8 in body: {e}")

    def json(self) -> Any:
        try:
            return json.loads(self.text())
        except (json.JSONDecodeError, BadRequest):
            raise

    def _decode_uri_component(self, s: str) -> str:
        # + means space
        s = s.replace('+', ' ')
        # %XX
        result = []
        i = 0
        while i < len(s):
            if s[i] == '%':
                if i + 2 >= len(s):
                    raise BadRequest("Malformed percent encoding")
                hex_chars = s[i+1:i+3]
                if not all(c in '0123456789ABCDEFabcdef' for c in hex_chars):
                    raise BadRequest("Invalid hex digit in percent encoding")
                try:
                    decoded_byte = int(hex_chars, 16).to_bytes(1, 'big')
                    result.append(decoded_byte.decode('utf-8'))
                except UnicodeDecodeError:
                    raise BadRequest("Invalid UTF-8 sequence after decoding")
                i += 3
            else:
                result.append(s[i])
                i += 1
        return ''.join(result)

    @classmethod
    def from_bytes(cls, data: bytes) -> 'Request':
        return parse_request(data)

@dataclass
class Response:
    status: int = 200
    headers: Optional[Headers] = None
    body: bytes = b''

    def __post_init__(self):
        if self.headers is None:
            self.headers = Headers()

    @classmethod
    def text(cls, s: str, status: int = 200) -> 'Response':
        return cls(status=status, headers=Headers(), body=s.encode('utf-8'))

    @classmethod
    def json(cls, obj: Any, status: int = 200) -> 'Response':
        body = json.dumps(obj, separators=(',', ':'), sort_keys=True).encode('utf-8')
        headers = Headers()
        headers.add('Content-Type', 'application/json')
        return cls(status=status, headers=headers, body=body)

    def to_bytes(self) -> bytes:
        lines = []
        lines.append(f"HTTP/1.1 {self.status} {get_reason_phrase(self.status)}")
        for name, value in self.headers.items():
            lines.append(f"{name}: {value}")
        # Ensure Content-Length is last, remove if exists
        existing_cl = None
        for i, (n, _) in enumerate(self.headers.items()):
            if n.lower() == 'content-length':
                existing_cl = i
                break

        if existing_cl is not None:
            self.headers._pairs = [p for i, p in enumerate(self.headers._pairs) if i != existing_cl]

        lines.append(f"Content-Length: {len(self.body)}")
        lines.append("")
        return '\r\n'.join(lines) + '\r\n' + self.body

def parse_request(data: bytes) -> Request:
    # Split head and body
    try:
        end_head = data.index(b'\r\n\r\n')
    except ValueError:
        raise BadRequest("Missing empty line separating headers and body")

    head = data[:end_head]
    body = data[end_head + 4:]

    # Parse head lines
    lines = head.decode('iso-8859-1').split('\r\n')
    if not lines:
        raise BadRequest("Empty request")

    # Request line
    req_line = lines[0]
    if not req_line.startswith(' ') and not req_line.startswith('\t'):
        parts = req_line.split(' ')
        if len(parts) != 3:
            raise BadRequest(f"Invalid request line: {req_line}")
        method, target, version = parts
        if not method.isascii() or not method.isupper() or not method.replace(' ', '').isalpha():
             raise BadRequest(f"Invalid method: {method}")
        if not target.startswith('/'):
            raise BadRequest(f"Invalid target: {target}")
        if version not in ('HTTP/1.1', 'HTTP/1.0'):
            raise BadRequest(f"Invalid version: {version}")
    else:
         raise BadRequest("Request line starts with space/tab")

    headers = Headers()
    for i in range(1, len(lines)):
        line = lines[i]
        if line.startswith(' ') or line.startswith('\t'):
            raise BadRequest("Obsolete line folding")
        if not line:
            continue
        if ':' not in line:
            raise BadRequest(f"Invalid header: {line}")
        colon_idx = line.index(':')
        name = line[:colon_idx]
        value = line[colon_idx + 1:]
        # Validate name
        valid_chars = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&\'*+-.^_`|~')
        if not all(c in valid_chars for c in name):
            raise BadRequest(f"Invalid header name: {name}")
        # Strip surrounding spaces and tabs from value
        value = value.strip(' \t')
        headers.add(name, value)

    # Host header check for 1.1
    if version == 'HTTP/1.1':
        if 'host' not in headers:
            raise BadRequest("Missing Host header")

    request = Request(
        method=method,
        target=target,
        path=target.split('?', 1)[0],
        query_string=target.split('?', 1)[1] if '?' in target else '',
        version=version,
        headers=headers,
        body=body
    )

    # Parse body based on headers
    te = headers.get('Transfer-Encoding', '').lower()
    cl = headers.get('Content-Length')

    if te == 'chunked':
        if cl is not None:
            raise BadRequest("Transfer-Encoding: chunked and Content-Length both present")

        idx = 0
        while idx < len(body):
            # Skip whitespace
            while idx < len(body) and (body[idx] == 0x09 or body[idx] == 0x0D or body[idx] == 0x20):
                idx += 1
            if idx >= len(body):
                raise BadRequest("Chunked body ended unexpectedly")

            # Read size
            chunk_size_hex = []
            while idx < len(body):
