            if not hex_str:
                raise BadRequest("Empty chunk size")

            size = int(hex_str, 16)

            # Skip optional params (semicolon)
            if idx < len(body) and body[idx] == 0x3B: # ;
                idx += 1

            # Skip \r\n
            if idx + 1 >= len(body) or body[idx] != 0x0D or body[idx+1] != 0x0A:
                raise BadRequest("Missing CRLF after chunk size")
            idx += 2

            if size > len(body) - idx:
                raise BadRequest("Chunk extends past end of body")

            # Read chunk
            idx += size

            # Skip \r\n
            if idx + 1 >= len(body) or body[idx] != 0x0D or body[idx+1] != 0x0A:
                raise BadRequest("Missing CRLF after chunk")
            idx += 2

            if size == 0:
