        # self._methods_by_pattern[pattern].add(method) # Not needed if we iterate patterns

    def route(self, pattern: str, methods: Optional[List[str]] = None) -> Callable:
        if methods is None:
            methods = ['GET']
        def decorator(func: Callable[[Request], Response]) -> Callable[[Request], Response]:
            self.add(methods[0], pattern, func)
            return func
        return decorator

