    return int(tok)

def _parse_ref(tok: str) -> str:
    m = REF_PATTERN.match(tok)
    if not m:
        raise FormulaError("Invalid reference")
    col = m.group(1).upper()
    row = int(m.group(2))

    # Validate bounds (A-Z, 1-999)
    if len(col) > 26:
        raise FormulaError("Reference out of bounds: column")
    if row == 0 or row > 999:
        raise FormulaError("Reference out of bounds: row")

    # Check leading zeros in the string representation provided in token
    if len(m.group(2)) > 1 and m.group(2)[0] == '0':
        raise FormulaError("Leading zero in row number")

    return col + str(row)

