def _tokenize(source):
    tokens = []
    i = 0
    n = len(source)

    while i < n:
        c = source[i]
        if c.isspace():
            i += 1
            continue

        # Numbers
        if c.isdigit():
            j = i
            while j < n and source[j].isdigit():
                j += 1
            if j < n and source[j] == '.':
                j += 1
                while j < n and source[j].isdigit():
                    j += 1
            if i == j:
                raise FormulaError("Unexpected character")
            tokens.append(('NUM', source[i:j]))
            i = j
            continue

        # Refs (letters followed by digits)
        if c.isalpha():
            j = i
            while j < n and source[j].isalpha():
                j += 1
            if j < n and source[j].isdigit():
                k = j
                while k < n and source[k].isdigit():
                    k += 1
                if i == j or j == k:
                    raise FormulaError("Invalid reference format")
                tokens.append(('REF', source[i:k]))
                i = k
                continue
            else:
                raise FormulaError(f"Invalid character after letters: {c}")

        # Function names (only alphabetic)
        if c.isalpha():
            j = i
            while j < n and source[j].isalpha():
                j += 1
            tokens.append(('NAME', source[i:j]))
            i = j
            continue

        # Operators and parens
        if c == '+':
            tokens.append(('PLUS', c))
            i += 1
            continue
        if c == '-':
            tokens.append(('MINUS', c))
            i += 1
            continue
        if c == '*':
            tokens.append(('MUL', c))
            i += 1
            continue
        if c == '/':
            tokens.append(('DIV', c))
            i += 1
            continue
        if c == '(':
            tokens.append(('LPAREN', c))
            i += 1
            continue
        if c == ')':
            tokens.append(('RPAREN', c))
            i += 1
            continue
        if c == ':':
            tokens.append(('RANGE_SEP', c))
            i += 1
            continue

        raise FormulaError(f"Unexpected character: {c}")

    return tokens

def _parse_call(tokens, idx):
    # call := fname ( arg {, arg} )
    if idx >= len(tokens) or tokens[idx][0] != 'NAME':
        raise FormulaError("Function name expected")
    fname = tokens[idx][1].upper()
    idx += 1

    if idx >= len(tokens) or tokens[idx][0] != 'LPAREN':
        raise FormulaError("Opening parenthesis expected")
    idx += 1

    args = []
    if idx >= len(tokens) or tokens[idx][0] != 'RPAREN':
        # Must have at least one arg
        while idx < len(tokens):
            if tokens[idx][0] == 'RPAREN':
                idx += 1
                break
            if tokens[idx][0] == 'COMMA':
                idx += 1
            # Parse arg
            arg, idx = _parse_arg(tokens, idx)
            args.append(arg)

        if idx >= len(tokens) or tokens[idx][0] != 'RPAREN':
            raise FormulaError("Closing parenthesis expected")
        idx += 1

        if not args:
            raise FormulaError("Function requires arguments")
    else:
        idx += 1
        if not args:
            raise FormulaError("Function requires arguments")

    return CallNode(fname, args), idx

def _parse_arg(tokens, idx):
    # arg := ref : ref | expr
    # We need to look ahead or try to parse range
    # Range is strictly ref : ref (whitespace allowed)
    # But expr can start with ref too.
    # The spec says ":" is only between the two references.
    # So we try to find a :.

    # Skip whitespace already done in tokenizer loop? No, tokenizer skips whitespace between tokens.
    # So tokens are contiguous.

    if idx >= len(tokens):
        raise FormulaError("Incomplete argument")

