    # A range must be REF RANGE_SEP REF
    # But we can't just check the first two tokens because expr could be ( expr )

    # Strategy: Peek ahead.
    # If current is REF or LPAREN (for nested call), check next token.

    current = tokens[idx]

    # Case 1: Range Ref : Ref
    # Must start with REF (or LPAREN wrapping it? No, arg is ref:ref or expr)
    # If current is LPAREN, it must be an expr (nested call or parens).
    # If current is REF, it could be start of range or start of expr.

    if current[0] == 'LPAREN':
        return _parse_expr(tokens, idx)

    if current[0] == 'REF':
        # Peek ahead for RANGE_SEP
        # We need to consume REF, then look for RANGE_SEP
        # But we must ensure the RANGE_SEP is actually the separator and not part of something else?
        # Tokens are distinct.
        # So: REF, RANGE_SEP, REF

        # Check if next token is RANGE_SEP
        if idx + 1 < len(tokens) and tokens[idx+1][0] == 'RANGE_SEP':
