            ref1, idx = _parse_ref(tokens, idx)
            # Consume separator
            idx += 1
            if idx >= len(tokens) or tokens[idx][0] != 'REF':
                raise FormulaError("Expected reference after colon")
            ref2, idx = _parse_ref(tokens, idx)
            return RangeNode(ref1, ref2)
        else:
            # It is an expression starting with ref
            return _parse_expr(tokens, idx)

    # Default to expression
    return _parse_expr(tokens, idx)

