    # Check bounds immediately? 
    # Spec: "parse_formula raises FormulaError for ... reference outside the sheet"
    # Wait, updated spec: "A reference ... outside the sheet ... is no longer a FormulaError: it parses, and evaluating it gives #REF!."
    # So we must NOT raise here. We just return the name.
    # But we need to store the name as is (upper).
    # The helper _parse_ref validates bounds and raises. We need to strip that validation for parsing.
    # Let's fix the helper or create a parser-only version.

    # Let's re-implement the specific parsing logic inline to avoid raising on out-of-bounds
    m = REF_PATTERN.match(tok[1]) # tok is ('REF', 'string')
    if not m:
        raise FormulaError("Invalid reference")
    col = m.group(1).upper()
    row = int(m.group(2))
    name = col + str(row)
    return name, idx + 1

def _parse_expr(tokens, idx):
    # expr := term {(+ | -) term}
    left, new_idx = _parse_term(tokens, idx)
    while new_idx < len(tokens) and tokens[new_idx][0] in ('PLUS', 'MINUS'):
        op = tokens[new_idx][0]
        new_idx += 1
        right, new_idx = _parse_term(tokens, new_idx)
        left = BinOpNode(op, left, right)
    return left, new_idx

def _parse_term(tokens, idx):
    # term := unary {(* | /) unary}
    left, new_idx = _parse_unary(tokens, idx)
    while new_idx < len(tokens) and tokens[new_idx][0] in ('MUL', 'DIV'):
        op = tokens[new_idx][0]
        new_idx += 1
        right, new_idx = _parse_unary(tokens, new_idx)
        left = BinOpNode(op, left, right)
    return left, new_idx

def _parse_unary(tokens, idx):
    # unary := (+ | -) unary | number | ref | call | ( expr )
    if idx >= len(tokens):
        raise FormulaError("Incomplete expression")

    tok_type, tok_val = tokens[idx]

    if tok_type == 'PLUS':
        idx += 1
        operand, idx = _parse_unary(tokens, idx)
        return UnaryOpNode('+', operand), idx
    if tok_type == 'MINUS':
        idx += 1
        operand, idx = _parse_unary(tokens, idx)
        return UnaryOpNode('-', operand), idx
    if tok_type == 'NUM':
        val = _parse_number(tok_val)
        return NumberNode(val), idx + 1
    if tok_type == 'REF':
        # Parser only, no bound check
        ref_name, idx = _parse_ref(tokens, idx)
        return RefNode(ref_name), idx
    if tok_type == 'NAME':
        # Function call
        call, idx = _parse_call(tokens, idx)
        return call, idx
    if tok_type == 'LPAREN':
        idx += 1
        expr, idx = _parse_expr(tokens, idx)
        if idx >= len(tokens) or tokens[idx][0] != 'RPAREN':
            raise FormulaError("Mismatched parentheses")
        idx += 1
        return expr, idx
    raise FormulaError("Unexpected token")

def parse_formula(source: str):
    if not source or not source.strip():
        raise FormulaError("Empty formula")

    source = source.strip()
    if source.startswith('='):
        source = source[1:]

    if not source:
        raise FormulaError("Empty formula")

    tokens = _tokenize(source)
    if not tokens:
        raise FormulaError("Empty formula")

    tree, end_idx = _parse_expr(tokens, 0)
    if end_idx != len(tokens):
        raise FormulaError("Incomplete expression")
    return tree

