# sheet/graph.py

class DependencyGraph:
    def __init__(self):
        # cell_name -> set of precedent cell names
        self._precedents = {}
        # cell_name -> set of cells that depend on it
        self._dependents = {}
        # cell_name -> set of cells on cycles
        self._cycle_cells = set()

    def set_dependencies(self, cell: str, precedents):
        if cell not in self._precedents:
            self._precedents[cell] = set()

        old_precedents = self._precedents[cell]

        # Remove old precedents from dependents
        for p in old_precedents:
            if p in self._dependents:
                self._dependents[p].discard(cell)

        # Update precedents
        self._precedents[cell] = set(precedents)

        # Add new precedents to dependents
        for p in self._precedents[cell]:
            if p not in self._dependents:
                self._dependents[p] = set()
            self._dependents[p].add(cell)

        # Re-evaluate cycles
        self._cycle_cells = self._detect_cycles()

    def _detect_cycles(self):
        # Use Kosaraju's algorithm to find SCCs
        nodes = set(self._precedents.keys()) | set(self._dependents.keys())
        if not nodes:
            return set()

