            for v in self._precedents.get(u, set()):
                if v not in visited:
                    dfs1(v)
            stack.append(u)

        for u in nodes:
            if u not in visited:
                dfs1(u)

        # Step 2: Build reverse graph
        rev_adj = {u: [] for u in nodes}
        for u in self._precedents:
            for v in self._precedents[u]:
                rev_adj[v].append(u)

        visited2 = set()
        sccs = []

        while stack:
            start = stack.pop()
            if start in visited2:
                continue
            component = []
            def dfs2(u):
                visited2.add(u)
                component.append(u)
                for v in rev_adj.get(u, []):
                    if v not in visited2:
                        dfs2(v)
            dfs2(start)
            sccs.append(component)

        # Step 3: Identify cycles
        # SCC size > 1 OR size 1 with self-loop
        cycle_cells = set()
        for scc in sccs:
            if len(scc) > 1:
                cycle_cells.update(scc)
            elif len(scc) == 1:
                u = scc[0]
                if u in self._precedents.get(u, set()):
                    cycle_cells.add(u)

        return cycle_cells

    def precedents(self, cell: str) -> set:
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> set:
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> set:
        result = set()
        queue = list(self._dependents.get(cell, set()))
        visited = set()

        while queue:
            current = queue.pop()
            if current in visited:
                continue
            visited.add(current)
            result.add(current)

            for next_dep in self._dependents.get(current, set()):
                if next_dep not in visited:
                    queue.append(next_dep)

        return result

    def cycle_cells(self) -> set:
        return self._cycle_cells
