                self._values[c] = ERROR_VALUE

            for neighbor in adj_list[c]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        self._raw[cell_name] = raw

        # Return affected cells in row-major order
        result = sorted([cell_name] + list(affected), key=lambda x: (int(x[1]), x[0]))
        return result

    def get(self, name: str):
        _validate_name(name)
        cell_name = name.upper()
        return self._values.get(cell_name, None)

