        _validate_name(name)
        cell_name = name.upper()
        return self._raw.get(cell_name, '')

    def cells(self) -> list[str]:
        candidates = []
        for name, val in self._values.items():
            if val is not None:
                candidates.append(name)

        candidates.sort(key=lambda x: (int(x[1]), x[0]))
        return candidates

    @property
    def evaluations(self) -> int:
        return self._evaluations
