    if idx < len(s) and s[idx] == '.':
        if idx + 1 >= len(s) or s[idx+1] not in '0123456789':
            raise JSONError("Invalid number", line, col)
        has_fraction = True
        while idx < len(s) and s[idx] in '0123456789':
            idx += 1

    # Exponent part
    if idx < len(s) and (s[idx] == 'e' or s[idx] == 'E'):
        has_exp = True
        idx += 1
        if idx < len(s) and s[idx] in '+-':
            idx += 1
        if idx >= len(s) or s[idx] not in '0123456789':
            raise JSONError("Invalid number", line, col)
        while idx < len(s) and s[idx] in '0123456789':
            idx += 1

    if idx != len(s):
        raise JSONError("Invalid number", line, col)

    num_str = s

    # Check for float
    is_float = has_fraction or has_exp

    if is_float:
        val = float(num_str)
        # Python float() handles infinity and NaN. 
        # The prompt says "1e400 is inf". 
        # We return the float directly.
        return Token('NUMBER', val, line, col)
    else:
        # Integer
        # Check if it fits in int? Python ints are arbitrary precision.
        # However, the prompt implies standard parsing.
        # "12345678901234567890 is an int"
        # We just convert.
        return Token('NUMBER', int(num_str), line, col)

def _parse_literal(line: int, col: int) -> Token:
    start = pos
    word = []

    while pos < len(text) and text[pos].isalpha():
        word.append(text[pos])
        pos += 1

    w = ''.join(word)

    if w == 'true':
        return Token('TRUE', True, line, col)
    elif w == 'false':
        return Token('FALSE', False, line, col)
    elif w == 'null':
        return Token('NULL', None, line, col)
    else:
        # Invalid literal, e.g., trueX, nul
        raise JSONError(f"Invalid literal '{w}'", line, col)
