from js.scanner import Token, tokenize, JSONError
from typing import Any, List, Union

def loads(text: str) -> Any:
    tokens = tokenize(text)
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        nonlocal pos
        if pos < len(tokens):
            t = tokens[pos]
            pos += 1
            return t
        return None

    def parse_value() -> Any:
        t = consume()
        if t is None:
            raise JSONError("Expected value", t.line, t.column)

        kind = t.kind
        if kind == 'STRING':
            return t.value
        elif kind == 'NUMBER':
            return t.value
        elif kind == 'TRUE':
            return True
        elif kind == 'FALSE':
            return False
        elif kind == 'NULL':
            return None
        elif kind == '{':
            return parse_object()
        elif kind == '[':
            return parse_array()
        else:
            # This should ideally be caught by scanner, but parser checks context too
            raise JSONError(f"Unexpected token '{kind}'", t.line, t.column)

    def parse_object() -> dict:
        consume() # '{'
        result = {}

        if peek() and peek().kind == '}':
            consume()
            return result

        while True:
            t = consume()
            if t.kind != 'STRING':
                raise JSONError("Object keys must be strings", t.line, t.column)
            key = t.value

            t = consume()
            if t.kind != ':':
                raise JSONError("Expected ':'", t.line, t.column)

            value = parse_value()
            result[key] = value

            t = consume()
            if t is None:
                raise JSONError("Expected ',' or '}'", t.line, t.column)

            if t.kind == '}':
                consume()
                return result
            elif t.kind == ',':
                consume()
                # Check for trailing comma
                if peek() and peek().kind == '}':
                    raise JSONError("Trailing comma in object", t.line, t.column)
            else:
                raise JSONError("Expected ',' or '}'", t.line, t.column)

    def parse_array() -> list:
        consume() # '['
        result = []

        if peek() and peek().kind == ']':
            consume()
            return result

        while True:
            value = parse_value()
            result.append(value)

            t = consume()
            if t is None:
                raise JSONError("Expected ',' or ']', found EOF", t.line, t.column)

            if t.kind == ']':
                consume()
                return result
            elif t.kind == ',':
                consume()
                # Check for trailing comma
                if peek() and peek().kind == ']':
                    raise JSONError("Trailing comma in array", t.line, t.column)
            else:
                raise JSONError("Expected ',' or '']", t.line, t.column)

    first_val = parse_value()

    # Check for trailing content
    if pos < len(tokens):
        remaining = tokens[pos:]
        # If there is non-whitespace after the value, it's an error.
        # Since tokenizer ignores whitespace, remaining tokens are all non-whitespace.
        # We just need to check if any tokens remain.
        raise JSONError("Extra data", first_val.line, first_val.column)

    return first_val
