import math
from typing import Any, List, Optional, Union

def dumps(obj: Any, *, indent: Optional[int] = None, sort_keys: bool = False, ensure_ascii: bool = False) -> str:
    if not isinstance(obj, (dict, list, str, int, float, bool, type(None))):
        raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable")

    # Check for cycles
    # We need to track visited containers.
    # Since we are building a string recursively, we can pass a set of id()s.

    def serialize(o: Any, visited: set, level: int = 0) -> str:
        if id(o) in visited:
            raise ValueError("Circular reference detected")

        if isinstance(o, dict):
            visited.add(id(o))
            items = []
            if sort_keys:
                keys = sorted(o.keys())
            else:
                keys = list(o.keys())

            for k in keys:
                # Dict keys must be strings
                if not isinstance(k, str):
                    raise TypeError(f"Keys must be strings, not {type(k).__name__}")

                items.append(serialize_pair(k, o[k]))

            visited.remove(id(o))
            return join_objects(items, level)

        elif isinstance(o, (list, tuple)):
            visited.add(id(o))
            items = [serialize(v) for v in o]
            visited.remove(id(o))
            return join_arrays(items, level)

        elif isinstance(o, str):
            return serialize_string(o, ensure_ascii)

        elif isinstance(o, bool):
            return 'true' if o else 'false'

        elif o is None:
            return 'null'

        elif isinstance(o, int):
            return str(o)

        elif isinstance(o, float):
            if math.isnan(o) or math.isinf(o):
                raise ValueError(f"Cannot serialize {o}: {o is not o and 'NaN' or 'Infinity'}")
            # Use repr to get enough precision, but ensure it's not scientific notation if possible?
            # The prompt says "repr(f)".
            # repr(1.0) -> '1.0', repr(1e10) -> '1e+10'. This is acceptable.
            return repr(o)

        else:
            raise TypeError(f"Object of type {type(o).__name__} is not JSON serializable")

    def serialize_pair(key: str, val: Any) -> str:
        return f'"{escape_string(key)}": {serialize(val, visited=set())}'

    def serialize_string(s: str, ensure: bool) -> str:
        # Build escape map
        res = []
        for ch in s:
            if ch == '"':
                res.append('\\"')
            elif ch == '\\':
                res.append('\\\\')
            elif ch == '\b':
                res.append('\b')
            elif ch == '\f':
                res.append('\f')
            elif ch == '\n':
                res.append('\n')
            elif ch == '\r':
                res.append('\r')
            elif ch == '\t':
                res.append('\t')
            elif ord(ch) < 32:
                res.append(f'\\u{ord(ch):04x}')
            elif ensure and ord(ch) > 127:
                # Surrogate pair logic for UTF-16
                cp = ord(ch)
                if cp > 0xFFFF:
                    # Split into high and low surrogate
                    high = 0xD800 + ((cp - 0x10000) >> 10)
                    low = 0xDC00 + ((cp - 0x10000) & 0x3FF)
                    res.append(f'\\u{high:04x}\\u{low:04x}')
                else:
                    res.append(f'\\u{cp:04x}')
            else:
                res.append(ch)
        return ''.join(res)

    def join_arrays(items: List[str], level: int) -> str:
        if not items:
            return '[]'

        if indent is None:
            return '[' + ','.join(items) + ']'

        new_level = level + 1
        ind = ' ' * (indent * new_level)
        ind_inner = ' ' * (indent * level)

        lines = [ind + '[']
        for i, item in enumerate(items):
            lines.append(ind_inner + item)
            if i != len(items) - 1:
                lines.append(ind_inner + ',')
        lines.append(ind + ']')
        return '\n'.join(lines)

    def join_objects(items: List[str], level: int) -> str:
        if not items:
            return '{}'

        if indent is None:
            return '{' + ','.join(items) + '}'

        new_level = level + 1
        ind = ' ' * (indent * new_level)
        ind_inner = ' ' * (indent * level)

        lines = [ind + '{']
        for i, item in enumerate(items):
            lines.append(ind_inner + item)
            if i != len(items) - 1:
                lines.append(ind_inner + ',')
        lines.append(ind + '}')
        return '\n'.join(lines)

    # Initial visited set for the top-level object
    visited = {id(obj)} if isinstance(obj, (dict, list, tuple)) else set()
    return serialize(obj, visited)
