                    # Must be followed by 'Infinity'
                    if pos + 8 <= len(text) and text[pos:pos+8] == 'Infinity':
                        tokens.append(Token('NUMBER', float('-inf'), line, col))
                        advance() # consume '-'
                        advance() # consume 'I'
                        for _ in range(7): advance()
                        continue
                    else:
                        # Try to parse as regular number starting with '-'
                        # The logic in _parse_number will handle the rest, but we need to ensure
                        # we don't accidentally consume 'Infinity' as a number if it's invalid here.
                        # Actually, the prompt says: "-Infinity" is valid number if allow_nan.
                        # If it's "-abc", it's invalid number.
                        # So we just let _parse_number handle the run starting with '-'.
                        pass

                # Check for positive 'NaN' or 'Infinity'
                if ch == 'N' or ch == 'I':
                    # Check for NaN
                    if pos + 2 <= len(text) and text[pos:pos+3] == 'NaN':
                        tokens.append(Token('NUMBER', float('nan'), line, col))
                        advance() # consume 'N'
                        for _ in range(2): advance()
                        continue

                    # Check for Infinity
                    if pos + 7 <= len(text) and text[pos:pos+8] == 'Infinity':
                        tokens.append(Token('NUMBER', float('inf'), line, col))
                        advance() # consume 'I'
                        for _ in range(7): advance()
                        continue

            # Fall back to standard number or literal parsing
            if ch in '0123456789-':
                tokens.append(_parse_number(line, col))
                continue

            # Literals (true, false, null)
            tokens.append(_parse_literal(line, col))
            continue

        # Unexpected character
        raise JSONError(f"Unexpected character '{ch}'", line, col)

    tokens.append(Token('EOF', None, line, col))
    return tokens

def _parse_string(line: int, col: int) -> Token:
    # Start of string
    advance() # consume opening quote

    result = []
    is_surrogate_pair = False

    while True:
        if pos >= len(text):
            # Unterminated string
            raise JSONError("Unterminated string", line, col)

        ch = text[pos]

        if ch == '"':
            # End of string
            advance()
            break

        if ch == '\\':
            advance()
            if pos >= len(text):
                raise JSONError("Unterminated string", line, col)

            esc_ch = text[pos]
            if esc_ch == '"':
                result.append('"')
            elif esc_ch == '\\':
                result.append('\\')
            elif esc_ch == '/':
                result.append('/')
            elif esc_ch == 'b':
                result.append('\b')
            elif esc_ch == 'f':
                result.append('\f')
            elif esc_ch == 'n':
                result.append('\n')
            elif esc_ch == 'r':
                result.append('\r')
            elif esc_ch == 't':
                result.append('\t')
            elif esc_ch == 'u':
                # Unicode escape
                advance()
                if pos + 4 > len(text):
                    raise JSONError("Invalid \\u escape", line, col)

                hex_chars = text[pos:pos+4]
                if not all(c in '0123456789abcdefABCDEF' for c in hex_chars):
                    raise JSONError("Invalid \\u escape", line, col)

                code_point = int(hex_chars, 16)
                pos += 4
                advance() # consume the char after the hex digits

                # Surrogate pair logic
                if 0xD800 <= code_point <= 0xDBFF:
                    # High surrogate
                    if pos + 6 > len(text) or text[pos] != '\\':
                        raise JSONError("Invalid \\u escape", line, col)
                    pos += 1
                    advance()
                    if pos + 4 > len(text) or text[pos] != 'u':
                        raise JSONError("Invalid \\u escape", line, col)
                    pos += 1
                    advance()
                    if pos + 4 > len(text):
                        raise JSONError("Invalid \\u escape", line, col)

                    hex_chars2 = text[pos:pos+4]
                    if not all(c in '0123456789abcdefABCDEF' for c in hex_chars2):
                        raise JSONError("Invalid \\u escape", line, col)

                    code_point2 = int(hex_chars2, 16)
                    pos += 4
                    advance()

                    if not (0xDC00 <= code_point2 <= 0xDFFF):
                        raise JSONError("Invalid \\u escape", line, col)

                    # Combine surrogates
                    cp = 0x10000 + ((code_point - 0xD800) << 10) + (code_point2 - 0xDC00)
                    result.append(chr(cp))
                    is_surrogate_pair = True
                elif 0xDC00 <= code_point <= 0xDFFF:
                    # Low surrogate on its own
                    raise JSONError("Invalid \\u escape", line, col)
                else:
                    result.append(chr(code_point))
                    is_surrogate_pair = True

            else:
                # Unknown escape
                raise JSONError(f"Invalid escape '\\{esc_ch}'", line, col)

        elif ord(ch) < 32:
            # Control character
            raise JSONError(f"Unescaped control character U+{ord(ch):04X}", line, col)
        else:
            result.append(ch)
            advance()

    return Token('STRING', ''.join(result), line, col)

def _parse_number(line: int, col: int) -> Token:
    chars = []

    # Optional minus
    if peek() == '-':
        advance()
        chars.append('-')
    elif peek() not in '0123456789':
        # Start with non-digit, non-minus (or minus consumed already)
        # If we consumed minus, we check next char. If we didn't, we check current.
        # Actually, if we are here, peek() returned something else.
        # If peek() was '-' and we advanced, we added '-'. Now check next.
        # If peek() was not '-', we didn't advance.
        pass

    # Collect digits, '.', 'e', 'E', '+'
    while pos < len(text) and text[pos] in '0123456789+-.eE':
        chars.append(text[pos])
        pos += 1

    if not chars:
        raise JSONError("Invalid number", line, col)

    s = ''.join(chars)

    # Validate structure
    # Must start with digit or minus followed by digit
    if s[0] == '-':
        if len(s) == 1:
            raise JSONError("Invalid number", line, col)
        if s[1] not in '0123456789':
            raise JSONError("Invalid number", line, col)
    elif s[0] not in '0123456789':
        raise JSONError("Invalid number", line, col)

    # Parse components to ensure validity
    idx = 0
    has_fraction = False
    has_exp = False

    # Integer part
    int_part_end = 0
    while idx < len(s) and s[idx] in '0123456789':
        int_part_end += 1
        idx += 1

    if int_part_end == 0:
        raise JSONError("Invalid number", line, col)

    # Fraction part
    if idx < len(s) and s[idx] == '.':
        if idx + 1 >= len(s) or s[idx+1] not in '0123456789':
            raise JSONError("Invalid number", line, col)
        has_fraction = True
        while idx < len(s) and s[idx] in '0123456789':
            idx += 1

    # Exponent part
    if idx < len(s) and (s[idx] == 'e' or s[idx] == 'E'):
        has_exp = True
        idx += 1
        if idx < len(s) and s[idx] in '+-':
            idx += 1
        if idx >= len(s) or s[idx] not in '0123456789':
            raise JSONError("Invalid number", line, col)
        while idx < len(s) and s[idx] in '0123456789':
            idx += 1

    if idx != len(s):
        raise JSONError("Invalid number", line, col)

    num_str = s

    is_float = has_fraction or has_exp

    if is_float:
        val = float(num_str)
        return Token('NUMBER', val, line, col)
    else:
        return Token('NUMBER', int(num_str), line, col)

def _parse_literal(line: int, col: int) -> Token:
    word = []

    while pos < len(text) and text[pos].isalpha():
        word.append(text[pos])
        pos += 1

    w = ''.join(word)

    if w == 'true':
        return Token('TRUE', True, line, col)
    elif w == 'false':
        return Token('FALSE', False, line, col)
    elif w == 'null':
        return Token('NULL', None, line, col)
    else:
        # Invalid literal, e.g., trueX, nul, NaN, Infinity (if allow_nan is false)
        raise JSONError(f"Invalid literal '{w}'", line, col)
