from js.scanner import Token, tokenize, JSONError
from typing import Any, List, Optional, Union

def loads(text: str, *, duplicate_keys: str = 'last', max_depth: Optional[int] = None, allow_nan: bool = False) -> Any:
    if duplicate_keys not in ('last', 'first', 'error'):
        raise ValueError("duplicate_keys must be 'last', 'first', or 'error'")

    if max_depth is not None and (max_depth < 1):
        raise ValueError("max_depth must be None or an integer >= 1")

    tokens = tokenize(text, allow_nan=allow_nan)
    pos = 0
    depth = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        nonlocal pos
        if pos < len(tokens):
            t = tokens[pos]
            pos += 1
            return t
        return None

    def check_depth():
        nonlocal depth, max_depth
        if max_depth is not None and depth > max_depth:
            # The error should point to the opening bracket of the container that exceeds the limit.
            # However, we are inside a container. The container that *would* exceed the limit is the one we just entered.
            # But we are checking *before* entering the inner one.
            # The prompt says: "A container whose depth would be greater than max_depth raises ... pointing at its opening [...]".
            # This means when we are about to enter a container that would make depth = max_depth + 1.
            # Currently depth is d. If we enter, it becomes d+1. If d+1 > max_depth, error at current opening bracket.
            # But we track depth after entering.
            # So if depth == max_depth and we see a '{' or '[', we must raise.
            pass

    def parse_value() -> Any:
        nonlocal depth
        t = consume()
        if t is None:
            raise JSONError("Expected value", t.line, t.column)

        kind = t.kind
        if kind == 'STRING':
            return t.value
        elif kind == 'NUMBER':
            return t.value
        elif kind == 'TRUE':
            return True
        elif kind == 'FALSE':
            return False
        elif kind == 'NULL':
            return None
        elif kind == '{':
            depth += 1
            check_depth()
            return parse_object()
        elif kind == '[':
            depth += 1
            check_depth()
            return parse_array()
        else:
            raise JSONError(f"Unexpected token '{kind}'", t.line, t.column)

    def parse_object() -> dict:
        # consume('{') already done by caller
        result = {}

        if peek() and peek().kind == '}':
            consume()
            return result

        while True:
            t = consume()
            if t.kind != 'STRING':
                raise JSONError("Object keys must be strings", t.line, t.column)
            key = t.value

            t = consume()
            if t.kind != ':':
                raise JSONError("Expected ':'", t.line, t.column)

            value = parse_value()

            # Handle duplicate keys
            if duplicate_keys == 'error':
                # The key has already been parsed. We need to check if it exists in result.
                # But result[k] = value overwrites.
                # We need to check before overwriting?
                # Prompt: "a repeated key raises JSONError pointing at the opening quote of the repeated key."
                # So if key in result: raise error.
                if key in result:
                    raise JSONError(f"Duplicate key '{key}'", t.line, t.column)

            result[key] = value

            t = consume()
            if t is None:
                raise JSONError("Expected ',' or '}'", t.line, t.column)

            if t.kind == '}':
                consume()
                return result
            elif t.kind == ',':
                consume()
                # Check for trailing comma
                if peek() and peek().kind == '}':
                    raise JSONError("Trailing comma in object", t.line, t.column)
            else:
                raise JSONError("Expected ',' or '}'", t.line, t.column)

    def parse_array() -> list:
        # consume('[') already done by caller
        result = []

        if peek() and peek().kind == ']':
            consume()
            return result

        while True:
            value = parse_value()
            result.append(value)

            t = consume()
            if t is None:
                raise JSONError("Expected ',' or ']', found EOF", t.line, t.column)

            if t.kind == ']':
                consume()
                return result
            elif t.kind == ',':
                consume()
                # Check for trailing comma
                if peek() and peek().kind == ']':
                    raise JSONError("Trailing comma in array", t.line, t.column)
            else:
                raise JSONError("Expected ',' or '']", t.line, t.column)

    first_val = parse_value()

    # Check for trailing content
    if pos < len(tokens):
        remaining = tokens[pos:]
        raise JSONError("Extra data", first_val.line, first_val.column)

    return first_val
