import math
from typing import Any, List, Optional, Union

def dumps(obj: Any, *, indent: Optional[int] = None, sort_keys: bool = False, ensure_ascii: bool = False, allow_nan: bool = False) -> str:
    if not isinstance(obj, (dict, list, str, int, float, bool, type(None))):
        raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable")

    if indent is not None and indent < 0:
        raise ValueError("indent must be None or an integer >= 0")

    # Check for cycles
    def serialize(o: Any, visited: set, level: int = 0) -> str:
        if id(o) in visited:
            raise ValueError("Circular reference detected")

        if isinstance(o, dict):
            visited.add(id(o))
            items = []
            if sort_keys:
                keys = sorted(o.keys())
            else:
                keys = list(o.keys())

            for k in keys:
                if not isinstance(k, str):
                    raise TypeError(f"Keys must be strings, not {type(k).__name__}")
                items.append(f'"{escape_string(k)}": {serialize(o[k], visited.copy(), level+1)}')

            visited.remove(id(o))
            return join_objects(items, level)

        elif isinstance(o, (list, tuple)):
            visited.add(id(o))
            items = [serialize(v, visited.copy(), level+1) for v in o]
            visited.remove(id(o))
            return join_arrays(items, level)

        elif isinstance(o, str):
            return escape_string(o)

        elif isinstance(o, bool):
            return 'true' if o else 'false'

        elif o is None:
            return 'null'

        elif isinstance(o, int):
            return str(o)

        elif isinstance(o, float):
            if math.isnan(o) or math.isinf(o):
                if not allow_nan:
                    raise ValueError(f"Cannot serialize {o}: {'NaN' if math.isnan(o) else 'Infinity'}")
                if math.isnan(o):
                    return 'NaN'
                return ('-Infinity' if o < 0 else 'Infinity')

            # Use repr to get enough precision
            s = repr(o)
            # Ensure no scientific notation if possible? Prompt says "repr(f)". 
            # Python's repr for floats uses scientific notation for large/small numbers. 
            # We follow the prompt strictly: "A finite float becomes repr(f)".
            return s

        else:
            raise TypeError(f"Object of type {type(o).__name__} is not JSON serializable")

    def escape_string(s: str) -> str:
        res = []
        for ch in s:
            if ch == '"':
                res.append('\\"')
            elif ch == '\\':
                res.append('\\\\')
            elif ch == '\b':
                res.append('\b')
            elif ch == '\f':
                res.append('\f')
            elif ch == '\n':
                res.append('\n')
            elif ch == '\r':
                res.append('\r')
            elif ch == '\t':
                res.append('\t')
            elif ord(ch) < 32:
                res.append(f'\\u{ord(ch):04x}')
            elif ensure_ascii and ord(ch) > 127:
                cp = ord(ch)
                if cp > 0xFFFF:
                    high = 0xD800 + ((cp - 0x10000) >> 10)
                    low = 0xDC00 + ((cp - 0x10000) & 0x3FF)
                    res.append(f'\\u{high:04x}\\u{low:04x}')
                else:
                    res.append(f'\\u{cp:04x}')
            else:
                res.append(ch)
        return ''.join(res)

    def join_arrays(items: List[str], level: int) -> str:
        if not items:
            return '[]'

        if indent is None:
            return '[' + ','.join(items) + ']'

        new_level = level + 1
        ind = ' ' * (indent * new_level)
        ind_inner = ' ' * (indent * level)

        lines = [ind + '[']
        for i, item in enumerate(items):
            lines.append(ind_inner + item)
            if i != len(items) - 1:
                lines.append(ind_inner + ',')
        lines.append(ind + ']')
        return '\n'.join(lines)

    def join_objects(items: List[str], level: int) -> str:
        if not items:
            return '{}'

        if indent is None:
            return '{' + ','.join(items) + '}'

        new_level = level + 1
        ind = ' ' * (indent * new_level)
        ind_inner = ' ' * (indent * level)

        lines = [ind + '{']
        for i, item in enumerate(items):
            lines.append(ind_inner + item)
            if i != len(items) - 1:
                lines.append(ind_inner + ',')
        lines.append(ind + '}')
        return '\n'.join(lines)

    return serialize(obj, set())
