# resolve/versions.py
from dataclasses import dataclass
from functools import total_ordering
import re

@dataclass(frozen=True, eq=True)
class Version:
    major: int
    minor: int
    patch: int

    def __post_init__(self):
        if self.major < 0 or self.minor < 0 or self.patch < 0:
            raise ValueError("Version parts must be non-negative")

    @staticmethod
    def parse(text: str):
        parts = text.split('.')
        if len(parts) != 3:
            raise ValueError(f"Invalid version format: {text}")

        for i, part in enumerate(parts):
            if not part:
                raise ValueError(f"Empty part in version: {text}")
            if not part.isdigit():
                raise ValueError(f"Non-digit in version: {text}")
            if len(part) > 1 and part[0] == '0':
                raise ValueError(f"Leading zero in version part: {text}")

            val = int(part)
            object.__setattr__(Version, f'_{i}', val)

        return Version(
            major=Version._0,
            minor=Version._1,
            patch=Version._2
        )

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"

    def __hash__(self):
        return hash((self.major, self.minor, self.patch))

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) == (other.major, other.minor, other.patch)

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)

    def __le__(self, other):
        return self == other or self < other

    def __gt__(self, other):
        return not self <= other

    def __ge__(self, other):
        return not self < other

    @property
    def parts(self):
        return (self.major, self.minor, self.patch)

    @property
    def major(self):
        return self._0

    @property
    def minor(self):
        return self._1

    @property
    def patch(self):
        return self._2

class Range:
    def __init__(self, spec: str):
        self.spec = spec
        self._constraints = self._parse(spec)

    def _parse(self, spec: str):
        # Remove all whitespace
        spec = spec.replace(' ', '').replace('\t', '').replace('\n', '')
        if not spec:
            raise ValueError("Empty range specification")

        constraints = []
        # Split by comma, but handle the spec as a whole first
        raw_parts = spec.split(',')

        for part in raw_parts:
            if not part:
                raise ValueError("Empty constraint in range")
            constraints.append(self._parse_constraint(part))

        return constraints

    def _parse_constraint(self, part: str):
        part = part.strip()
        if not part:
            raise ValueError("Empty constraint")

        # Match operator and version
        # Operators: ==, !=, >, <, >=, <=, ^, ~, *
        match = re.match(r'^(==|!=|>|<|>=|<=|\^|~|\*)?(.+)$', part)
        if not match:
            raise ValueError(f"Invalid constraint syntax: {part}")

        op = match.group(1)
        ver_str = match.group(2)

        if not ver_str:
            raise ValueError(f"Missing version in constraint: {part}")

        # Check for *
        if op == '*':
            return ('any',)

        # Parse version
        try:
            version = Version.parse(ver_str)
        except ValueError:
            raise ValueError(f"Invalid version in constraint: {ver_str}")

        # Determine the upper bound for ^ and ~
        upper = None
        if op == '^':
            # Caret range
            # ^1.2.3 -> >=1.2.3, <2.0.0
            # ^0.2.3 -> >=0.2.3, <0.3.0
            # ^0.0.3 -> >=0.0.3, <0.0.4
            # ^0.0.0 -> >=0.0.0, <0.0.1
            parts = version.parts
            # Find the leftmost non-zero part
            for i in range(3):
                if parts[i] > 0:
                    # Decrement the next part
                    new_parts = list(parts)
                    if i + 1 < 3:
                        new_parts[i+1] += 1
                    upper = Version(new_parts[0], new_parts[1], new_parts[2])
                    break
                # If all are zero (0.0.0), the upper bound is 0.0.1
                if i == 2:
                    upper = Version(0, 0, 1)
                    break

        elif op == '~':
            # Tilde range
            # ~1.2.3 -> >=1.2.3, <1.3.0
            parts = version.parts
            upper = Version(parts[0], parts[1] + 1, 0)

        if upper is None:
            # Exact or comparison operators without upper bound
            return ((op, version),)

        return ((op, version), ('<', upper))

    def contains(self, version: Version) -> bool:
        for op, bound in self._constraints:
            if op == 'any':
                continue

            if op == '<':
                if not (version < bound):
                    return False
            elif op == '<=':
                if not (version <= bound):
                    return False
            elif op == '>':
                if not (version > bound):
                    return False
            elif op == '>=':
                if not (version >= bound):
                    return False
            elif op == '==':
                if version != bound:
                    return False
            elif op == '!=':
                if version == bound:
                    return False

        return True

    def __contains__(self, version: Version):
        return self.contains(version)

    def __str__(self):
        return self.spec

    def __repr__(self):
        return f"Range({self.spec!r})"
