# resolve/index.py
from typing import Dict, List, Optional, Any
from .versions import Version, Range

class PackageIndex:
    def __init__(self):
        # Structure: {package_name: {version_str: {dep_name: range_spec_str, ...}}}
        self._data: Dict[str, Dict[str, Dict[str, str]]] = {}

    def add(self, name: str, version: str, requires: Optional[Dict[str, str]] = None):
        if not isinstance(name, str) or not isinstance(version, str):
            raise ValueError("Name and version must be strings")

        # Validate version string
        try:
            Version.parse(version)
        except ValueError:
            raise ValueError(f"Invalid version string: {version}")

        if requires is not None:
            for dep, spec in requires.items():
                try:
                    Range(spec)
                except ValueError:
                    raise ValueError(f"Invalid dependency spec for {dep}: {spec}")

        if name not in self._data:
            self._data[name] = {}

        if version in self._data[name]:
            raise ValueError(f"Duplicate release: {name} {version}")

        self._data[name][version] = requires or {}

    def versions(self, name: str) -> List[Version]:
        if name not in self._data:
            return []

        result = []
        for ver_str in self._data[name]:
            result.append(Version.parse(ver_str))

        # Sort by version descending
        result.sort(reverse=True)
        return result

    def requirements(self, name: str, version: Version) -> Dict[str, Range]:
        ver_str = str(version)
        if name not in self._data or ver_str not in self._data[name]:
            raise KeyError(name)

        return {dep: Range(spec) for dep, spec in self._data[name][ver_str].items()}

    @classmethod
    def from_dict(cls, data: Dict[str, Any]):
        index = cls()
        for name, releases in data.items():
            for ver_str, deps in releases.items():
                index.add(name, ver_str, deps)
        return index
