# resolve/solver.py
from typing import Dict, List, Set, Optional, Tuple
from .versions import Version, Range
from .index import PackageIndex

class ResolutionError(Exception):
    def __init__(self, package: str, explanation: str):
        self.package = package
        self.explanation = explanation
        super().__init__(explanation)

    def __str__(self):
        return self.explanation

def resolve(index: PackageIndex, requirements: Dict[str, str]) -> Dict[str, Version]:
    # Parse root requirements
    root_reqs = {}
    for name, spec in requirements.items():
        root_reqs[name] = Range(spec)

    # Order: list of package names to consider, initially root names sorted
    order: List[str] = sorted(root_reqs.keys())

    # Selected: {name: version}
    selected: Dict[str, Version] = {}

    # Track which packages have been added to order
    in_order: Set[str] = set(order)

    def get_constraints(package_name: str) -> List[Tuple[str, Range]]:
