from dataclasses import dataclass, field
from typing import Dict, Tuple, Optional
from enum import Enum

DIRECTIONS = ('north', 'south', 'east', 'west', 'up', 'down')

class WorldError(ValueError):
    """Raised when a world definition is invalid."""
    pass

@dataclass(frozen=True)
class Item:
    id: str
    name: str
    description: str
    portable: bool = True

@dataclass(frozen=True)
class Room:
    id: str
    name: str
    description: str
    exits: Dict[str, str] = field(default_factory=dict)
    items: Tuple[str, ...] = field(default_factory=tuple)

class World:
    def __init__(self, start: str, rooms: Dict[str, Room], items: Dict[str, Item]):
        self.start = start
        self.rooms = rooms
        self.items = items

    @classmethod
    def from_dict(cls, data: dict) -> 'World':
        if 'start' not in data:
            raise WorldError("World missing 'start' key.")

        start_id = data['start']
        if start_id not in data.get('rooms', {}):
            raise WorldError(f"Start room '{start_id}' does not exist.")

        rooms_data = data.get('rooms', {})
        items_data = data.get('items', {})

        # First pass: validate room existence and collect item references
        room_refs: Dict[str, set] = {rid: set() for rid in rooms_data}
        for rid in rooms_data:
            room_info = rooms_data[rid]
            if 'name' not in room_info:
                raise WorldError(f"Room '{rid}' lacks 'name'.")
            if 'description' not in room_info:
                raise WorldError(f"Room '{rid}' lacks 'description'.")

            exits = room_info.get('exits', {})
            for direction, target_id in exits.items():
                if direction not in DIRECTIONS:
                    raise WorldError(f"Room '{rid}' has invalid exit direction '{direction}'.")
                if target_id not in rooms_data:
                    raise WorldError(f"Exit in room '{rid}' points to unknown room '{target_id}'.")
                room_refs[target_id].add(rid) # Track which rooms reference target_id as exit destination? No, just checking existence.

            items = room_info.get('items', [])
            for item_id in items:
                if item_id not in items_data:
                    raise WorldError(f"Room '{rid}' references unknown item '{item_id}'.")
                room_refs[rid].add(item_id)

        # Check for duplicate item references across all rooms
        all_item_refs: Dict[str, int] = {}
        for rid, item_set in room_refs.items():
            for item_id in item_set:
                if item_id in all_item_refs:
                    all_item_refs[item_id] += 1
                else:
                    all_item_refs[item_id] = 1

        for item_id, count in all_item_refs.items():
            if count > 1:
                raise WorldError(f"Item '{item_id}' is listed in more than one room.")

        # Construct Rooms
        rooms: Dict[str, Room] = {}
        for rid, room_info in rooms_data.items():
            item_ids = tuple(room_info.get('items', []))
            # Validate item objects exist later
            rooms[rid] = Room(
                id=rid,
                name=room_info['name'],
                description=room_info['description'],
                exits=room_info.get('exits', {}),
                items=item_ids
            )

        # Construct Items
        items: Dict[str, Item] = {}
        for item_id, item_info in items_data.items():
            if 'portable' in item_info:
                portable = item_info['portable']
            else:
                portable = True

            if not isinstance(portable, bool):
                raise WorldError(f"Item '{item_id}' has non-boolean 'portable'.")

            items[item_id] = Item(
                id=item_id,
                name=item_info['name'],
                description=item_info['description'],
                portable=portable
            )

        return cls(start=start_id, rooms=rooms, items=items)
