from dataclasses import dataclass
from typing import NamedTuple, Optional
from adventure.world import DIRECTIONS

class ParseError(ValueError):
    """Raised when a command cannot be parsed."""
    pass

@dataclass(frozen=True)
class Command(NamedTuple):
    verb: str
    arg: Optional[str]

def parse(line: str) -> Command:
    line_lower = line.lower().strip()
    if not line_lower:
        raise ParseError("Say something.")

    words = line_lower.split()
    if not words:
        raise ParseError("Say something.")

    first_word = words[0]
    rest_words = words[1:]

    # Remove articles 'the', 'a', 'an' from rest_words
    filtered_rest = [w for w in rest_words if w not in ('the', 'a', 'an')]

    if first_word in ('look', 'l'):
        if not filtered_rest:
            return Command('look', None)
        elif len(filtered_rest) == 1:
            return Command('look', filtered_rest[0])
        else:
            raise ParseError("I don't understand that.")

    elif first_word in ('inventory', 'inv', 'i'):
        if not filtered_rest:
            return Command('inventory', None)
        else:
            raise ParseError("I don't understand that.")

    elif first_word == 'go':
        if not filtered_rest:
            raise ParseError("Go where?")
        elif len(filtered_rest) >= 1:
            dir_arg = filtered_rest[0]
            if dir_arg in DIRECTIONS:
                return Command('go', dir_arg)
            else:
                arg_str = ' '.join(filtered_rest)
                raise ParseError(f"'{arg_str}' is not a direction.")
        else:
            raise ParseError("Go where?")

    elif first_word in ('take', 'get'):
        if not filtered_rest:
            raise ParseError("Take what?")
        arg_str = ' '.join(filtered_rest)
        return Command('take', arg_str)

    elif first_word == 'drop':
        if not filtered_rest:
            raise ParseError("Drop what?")
        arg_str = ' '.join(filtered_rest)
        return Command('drop', arg_str)

    elif first_word in ('examine', 'x'):
        if not filtered_rest:
            raise ParseError("Examine what?")
        arg_str = ' '.join(filtered_rest)
        return Command('look', arg_str)

    elif first_word == 'look at':
        if not filtered_rest:
            raise ParseError("Examine what?")
        arg_str = ' '.join(filtered_rest)
        return Command('look', arg_str)

    else:
        raise ParseError(f"I don't know the word \"{first_word}\".")
