                exits_clean[direction] = target_room

                if key_item is not None:
                    locks[direction] = key_item

            rooms[rid] = Room(
                id=rid,
                name=room_info['name'],
                description=room_info['description'],
                exits=exits_clean,
                items=item_ids,
                locks=locks
            )

        # Construct Items
        items: Dict[str, Item] = {}
        for item_id, item_info in items_data.items():
            portable = item_info.get('portable', True)
            if not isinstance(portable, bool):
                raise WorldError(f"Item '{item_id}' has non-boolean 'portable'.")

            treasure = item_info.get('treasure', 0)
            if not isinstance(treasure, int) or treasure < 0:
                raise WorldError(f"Item '{item_id}' has invalid 'treasure'.")

            items[item_id] = Item(
                id=item_id,
                name=item_info['name'],
                description=item_info['description'],
                portable=portable,
                treasure=treasure
            )

        return cls(start=start_id, rooms=rooms, items=items)
