import json
from adventure.world import World, Room, Item, DIRECTIONS
from adventure.parser import Command, ParseError

class SaveError(ValueError):
    """Raised when save/load fails."""
    pass

class Game:
    def __init__(self, world: World):
        self.world = world
        self.room = world.start
        self.moves = 0
        self.score = 0
        self.inventory: list[str] = []

        # Initialize room item states
        self.room_items: dict[str, list[str]] = {rid: list(room.items) for rid, room in world.rooms.items()}

        # Track visited rooms (starts with start room visited? 
        # Spec: "start room counts as visited from the beginning and scores nothing."
        # So visited includes start.
        self.visited_rooms: set[str] = {world.start}

        # Track unlocked exits: list of (room_id, direction)
        self.unlocked_exits: list[tuple[str, str]] = []

        # Track scored items: set of item ids
        self.scored_items: set[str] = set()

    def _get_room_obj(self, room_id: str) -> Room:
        return self.world.rooms[room_id]

    def _get_item_obj(self, item_id: str) -> Item:
        return self.world.items[item_id]

    def items_in(self, room_id: str) -> list[str]:
        if room_id not in self.room_items:
            return []
        return list(self.room_items[room_id])

    def _is_exit_locked(self, room_id: str, direction: str) -> bool:
        if direction not in self.world.rooms[room_id].exits:
            return False # No exit at all
        # Check if this specific (room, dir) is in unlocked list
        return (room_id, direction) not in self.unlocked_exits

    def _room_desc(self, room_id: str) -> str:
        room = self._get_room_obj(room_id)
        lines = [room.name, room.description]

        exits = room.exits
        if exits:
            dir_strs = []
            for d in DIRECTIONS:
                if d in exits:
                    if self._is_exit_locked(room_id, d):
                        dir_strs.append(f"{d} (locked)")
                    else:
                        dir_strs.append(d)
            lines.append(f"Exits: {', '.join(dir_strs)}.")
        else:
            lines.append("Exits: none.")

        # Check items currently in the room
        visible_ids = self.items_in(room_id)
        if visible_ids:
            names = [self._get_item_obj(vid).name for vid in visible_ids]
            lines.append(f"You see: {', '.join(names)}.")

        return "\n".join(lines)

    def _look_item(self, arg: str) -> str:
        # Search room first
        room_ids = self.items_in(self.room)
        for vid in room_ids:
            item = self._get_item_obj(vid)
            if vid == arg or item.name.lower() == arg:
                return item.description

        # Search inventory
        for vid in self.inventory:
            item = self._get_item_obj(vid)
            if vid == arg or item.name.lower() == arg:
                return item.description

        return f"You see no {arg} here."

    def _find_item(self, arg: str, source_ids: list[str]):
        for vid in source_ids:
            item = self._get_item_obj(vid)
            if vid == arg or item.name.lower() == arg:
                return vid
        return None

    def do(self, line: str) -> str:
        try:
            cmd = parse(line)
        except ParseError as e:
            return str(e)

        if cmd.verb == 'look':
            if cmd.arg is None:
                return self._room_desc(self.room)
            else:
                return self._look_item(cmd.arg)

        elif cmd.verb == 'go':
            direction = cmd.arg
            current_room_obj = self._get_room_obj(self.room)

            if direction not in current_room_obj.exits:
                return "You can't go that way."

            # Check if locked
            if self._is_exit_locked(self.room, direction):
                return f"The way {direction} is locked."

            target_room = current_room_obj.exits[direction]
            self.room = target_room
            self.moves += 1

            # Score entering new room
            if target_room not in self.visited_rooms:
                self.visited_rooms.add(target_room)
                self.score += 10
                self._save_state_internal()

            return self._room_desc(target_room)

        elif cmd.verb == 'take':
            target = cmd.arg
            item_id = self._find_item(target, self.items_in(self.room))
            if item_id is None:
                return "You see no X here."

            item_obj = self._get_item_obj(item_id)
            if not item_obj.portable:
                return f"You can't take the {item_obj.name}."

            # Score treasure if taken for first time
            if item_id not in self.scored_items and item_obj.treasure > 0:
                self.scored_items.add(item_id)
                self.score += item_obj.treasure
                self._save_state_internal()

            self.inventory.append(item_id)
            # Remove from room state
            self.room_items[self.room].remove(item_id)
            return f"Taken: {item_obj.name}."

        elif cmd.verb == 'drop':
            target = cmd.arg
            item_id = self._find_item(target, self.inventory)
            if item_id is None:
                return "You aren't carrying that."

            item_obj = self._get_item_obj(item_id)
            self.room_items[self.room].append(item_id)
            self.inventory.remove(item_id)
            return f"Dropped: {item_obj.name}."

        elif cmd.verb == 'inventory':
            if not self.inventory:
                return "You are carrying nothing."
            names = [self._get_item_obj(vid).name for vid in self.inventory]
            return f"You are carrying: {', '.join(names)}."

        elif cmd.verb == 'use':
            target = cmd.arg
            item_id = self._find_item(target, self.inventory)
            if item_id is None:
                return "You aren't carrying that."

            item_obj = self._get_item_obj(item_id)

            # Find locked exits in current room that use this item as key
            room_obj = self._get_room_obj(self.room)
            unlocked_dirs = []

            for direction, key_id in room_obj.locks.items():
                if key_id == item_id and self._is_exit_locked(self.room, direction):
                    unlocked_dirs.append(direction)

            if unlocked_dirs:
                # Unlock them
                self.unlocked_exits.extend([(self.room, d) for d in unlocked_dirs])
                # Sort DIRECTIONS order
                unlocked_dirs.sort() # DIRECTIONS is already sorted, but ensure consistency
                response = f"Unlocked: {', '.join(unlocked_dirs)}."
                return response

            return f"Nothing here to use the {item_obj.name} on."

        elif cmd.verb == 'score':
            return f"Your score is {self.score}."

        return "I don't understand that."

    def _save_state_internal(self):
        """Update persistent tracking structures."""
        pass # State is updated immediately in do()

    def save(self) -> str:
        # Sort lists for deterministic output
        unlocked_sorted = sorted(self.unlocked_exits)
        visited_sorted = sorted(self.visited_rooms)
        scored_sorted = sorted(self.scored_items)

        room_items_state = {rid: self.room_items[rid] for rid in self.world.rooms.keys()}

        save_obj = {
            "version": 2,
            "room": self.room,
            "inventory": self.inventory.copy(),
            "items": room_items_state,
            "moves": self.moves,
            "unlocked": unlocked_sorted,
            "visited": visited_sorted,
            "scored": scored_sorted,
            "score": self.score
        }

        return json.dumps(save_obj)

    @classmethod
    def load(cls, world: World, text: str) -> 'Game':
        try:
            data = json.loads(text)
        except json.JSONDecodeError:
            raise SaveError("Invalid JSON.")

        if not isinstance(data, dict):
            raise SaveError("JSON is not an object.")

        required_keys = {"version", "room", "inventory", "items", "moves"}
        if not required_keys.issubset(data.keys()):
            raise SaveError("Missing keys in save data.")

        version = data["version"]

        # Handle Version 1 (backward compatibility)
        if version == 1:
            # Check old keys exist
            if not {"room", "inventory", "items", "moves"}.issubset(data.keys()):
                raise SaveError("Missing keys in save data.")
            # Validate old keys logic...
            # We will re-use validation logic below but with empty new keys

            # Initialize state for V1
            room_id = data["room"]
            inventory = data["inventory"]
            moves = data["moves"]
            items_data = data["items"]

            # Validate items, rooms, moves, etc (same as V2 base checks)
            if room_id not in world.rooms:
                raise SaveError(f"Room {room_id} not in world.")

            if not isinstance(inventory, list):
                raise SaveError("Inventory is not a list.")

            if not isinstance(moves, int) or moves < 0:
                raise SaveError("Moves is not a non-negative integer.")

            if not isinstance(items_data, dict):
                raise SaveError("Items is not an object.")

            for rid, item_list in items_data.items():
                if rid not in world.rooms:
                    raise SaveError(f"Room key {rid} not in world.")
                if not isinstance(item_list, list):
                    raise SaveError(f"Items for room {rid} are not a list.")
                for iid in item_list:
                    if iid not in world.items:
                        raise SaveError(f"Item {iid} not in world.")

            all_ids = inventory.copy()
            for item_list in items_data.values():
                all_ids.extend(item_list)
            if len(all_ids) != len(set(all_ids)):
                raise SaveError("Item appears more than once across inventory and rooms.")

            game = cls(world)
            game.room = room_id
            game.inventory = list(inventory)
            game.moves = moves
            # V1: All locks locked, only start and current room visited, nothing scored, score 0
            game.visited_rooms = {world.start, room_id}
            game.unlocked_exits = []
            game.scored_items = set()
            game.score = 0
            game.room_items = {rid: list(item_list) for rid, item_list in items_data.items()}
            return game

        elif version == 2:
            # Validate new keys
            new_keys = {"unlocked", "visited", "scored", "score"}
            if not new_keys.issubset(data.keys()):
                raise SaveError("Missing keys in save data.")

            room_id = data["room"]
            inventory = data["inventory"]
            moves = data["moves"]
            items_data = data["items"]

            # Validate basic structure
            if room_id not in world.rooms:
                raise SaveError(f"Room {room_id} not in world.")

            if not isinstance(inventory, list):
                raise SaveError("Inventory is not a list.")

            if not isinstance(moves, int) or moves < 0:
                raise SaveError("Moves is not a non-negative integer.")

            if not isinstance(items_data, dict):
                raise SaveError("Items is not an object.")

            # Validate items in rooms
            for rid, item_list in items_data.items():
                if rid not in world.rooms:
                    raise SaveError(f"Room key {rid} not in world.")
                if not isinstance(item_list, list):
                    raise SaveError(f"Items for room {rid} are not a list.")
                for iid in item_list:
                    if iid not in world.items:
                        raise SaveError(f"Item {iid} not in world.")

            # Validate new keys
            unlocked = data["unlocked"]
            visited = data["visited"]
            scored = data["scored"]
            game_score = data["score"]

            if not isinstance(game_score, int) or game_score < 0:
                raise SaveError("Score is not a non-negative integer.")

            if not isinstance(unlocked, list):
                raise SaveError("'unlocked' is not a list.")
            if not isinstance(visited, list):
                raise SaveError("'visited' is not a list.")
            if not isinstance(scored, list):
                raise SaveError("'scored' is not a list.")

            # Validate unlocked pairs
            for r, d in unlocked:
                if r not in world.rooms:
                    raise SaveError(f"Unlocked exit room {r} not in world.")
                if d not in world.rooms[r].exits:
                    raise SaveError(f"Unlocked exit direction {d} not in room {r}.")
                # Also check if it was a locked exit (has a key defined in world)
                # Spec: "unlocked pair is not a locked exit of the world"
                # If an exit wasn't locked in the world, can it be in unlocked? 
                # Technically yes, but logically it shouldn't be. 
                # Let's interpret "locked exit" as "an exit that had a key defined".
                room_obj = world.rooms[r]
                if d not in room_obj.locks:
                    raise SaveError(f"Unlocked pair ({r}, {d}) is not a locked exit of the world.")

            # Validate visited rooms
            for r in visited:
                if r not in world.rooms:
                    raise SaveError(f"Visited room {r} not in world.")

            # Validate scored items
            for i in scored:
                if i not in world.items:
                    raise SaveError(f"Scored item {i} not in world.")

            # Check for duplicates across inventory and rooms
            all_ids = inventory.copy()
            for item_list in items_data.values():
                all_ids.extend(item_list)
            if len(all_ids) != len(set(all_ids)):
                raise SaveError("Item appears more than once across inventory and rooms.")

            game = cls(world)
            game.room = room_id
            game.inventory = list(inventory)
            game.moves = moves
            game.visited_rooms = set(visited)
            game.unlocked_exits = list(unlocked)
            game.scored_items = set(scored)
            game.score = game_score
            game.room_items = {rid: list(item_list) for rid, item_list in items_data.items()}

            return game

        else:
            raise SaveError(f"Invalid version {version}.")

    @classmethod
    def _init_state_helper(cls, world: World):
        self = cls(world)
        # Helper logic if needed, but __init__ handles it.
        return self
