@dataclass(frozen=True)
class Record:
    time: datetime
    client: str
    method: str
    path: str
    status: int
    size: int
    latency_ms: Optional[float]

class ParseError(ValueError):
    pass

_MONTHS = {
    'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6,
    'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12
}

def _normalize_path(path: str) -> str:
    # Remove query string and fragment
    if '?' in path:
        path = path.split('?')[0]
    if '#' in path:
        path = path.split('#')[0]

    # Collapse runs of '/' into one
    while '//' in path:
        path = path.replace('//', '/')

    # Ensure it starts with /
    if not path.startswith('/'):
        path = '/' + path

    return path

def normalize(time: datetime, client: str, method: str, path: str, 
              status: Any, size: Any, latency_ms: Any) -> Record:
    # Validate and convert time
    if not isinstance(time, datetime):
        raise ParseError("time must be a datetime")
    if time.tzinfo is None:
        raise ParseError("time must be timezone-aware")
    time_utc = time.astimezone(timezone.utc)

    # Validate client
    if not isinstance(client, str) or not client.strip():
        raise ParseError("client must be a non-empty string")
    client = client.strip()

    # Validate method
    if not isinstance(method, str) or not method.strip():
        raise ParseError("method must be a non-empty string")
    method = method.strip().upper()
    if not method.isascii():
        raise ParseError("method must contain only ASCII letters")

    # Validate and normalize path
    if not isinstance(path, str):
        raise ParseError("path must be a string")
    path = _normalize_path(path)
    if not path.startswith('/'):
        raise ParseError("path must start with /")

    # Validate status
    status_val = None
    if isinstance(status, int):
        if status < 100 or status > 599:
            raise ParseError("status must be between 100 and 599")
        status_val = status
    elif isinstance(status, str):
        if status.isdigit():
            status_val = int(status)
            if status_val < 100 or status_val > 599:
                raise ParseError("status must be between 100 and 599")
        else:
            raise ParseError("status must be an integer or string of digits")
    else:
        raise ParseError("status must be an integer or string")

    # Validate size
    size_val = 0
    if size is None or size == "-":
        size_val = 0
    elif isinstance(size, int):
        if size < 0:
            raise ParseError("size must be non-negative")
        size_val = size
    elif isinstance(size, str):
        if size.isdigit():
            size_val = int(size)
        else:
            raise ParseError("size must be a non-negative integer or '-'")
    else:
        raise ParseError("size must be an integer or string")

    # Validate latency
    latency = None
    if latency_ms is None:
        latency = None
    elif isinstance(latency_ms, (int, float)):
        if latency_ms < 0:
            raise ParseError("latency_ms must be non-negative")
        latency = float(latency_ms)
    elif isinstance(latency_ms, str):
        try:
            f = float(latency_ms)
            if f < 0:
                raise ValueError()
            latency = f
        except ValueError:
            raise ParseError("latency_ms must be a non-negative number")
    else:
        raise ParseError("latency_ms must be a number")

    return Record(
        time=time_utc,
        client=client,
        method=method,
        path=path,
        status=status_val,
        size=size_val,
