    )

def parse_clf(line: str) -> Record:
    # Format: client ident user [time] "method path protocol" status size [latency_us]
    # Regex to capture components
    pattern = r'^(\S+)\s+(\S+)\s+(\S+)\s+\[([^\]]+)\]\s+"([^"]*)"?\s+(\d+)\s+(\S+)(?:\s+(\d+))?$'
    match = re.match(pattern, line)

    if not match:
        raise ParseError("Invalid CLF format")

    client, ident, user, time_str, request, status_str, size_str, latency_str = match.groups()

    # Parse request line
    req_parts = request.split()
    if len(req_parts) != 3:
        raise ParseError("Request line must have 3 parts: method path protocol")

    method, path, protocol = req_parts
    # Validate protocol roughly
    if not protocol.startswith('HTTP/'):
        raise ParseError("Invalid protocol")

    # Parse time: DD/Mon/YYYY:HH:MM:SS ±HHMM
    time_pattern = r'(\d{2})/(\w{3})/(\d{4}):(\d{2}):(\d{2}):(\d{2})\s+([+-]\d{4})'
    time_match = re.match(time_pattern, time_str)
    if not time_match:
        raise ParseError("Invalid time format in CLF")

    day, month_str, year, hour, minute, second, tz_offset = time_match.groups()

    month = _MONTHS.get(month_str)
    if not month:
        raise ParseError(f"Unknown month: {month_str}")

    try:
        dt = datetime(
            int(year), month, int(day),
            int(hour), int(minute), int(second),
            tzinfo=timezone(timedelta(hours=int(tz_offset[:3]), minutes=int(tz_offset[0]) * 60 + int(tz_offset[1:])) if tz_offset[0] == '+' else timezone(timedelta(hours=-int(tz_offset[:3]), minutes=-int(tz_offset[1:]))))
        )
    except ValueError:
        raise ParseError("Invalid date/time values")

    # Convert to UTC
    dt_utc = dt.astimezone(timezone.utc)

    # Parse status
    try:
        status = int(status_str)
        if status < 100 or status > 599:
            raise ValueError()
    except ValueError:
        raise ParseError("Status must be numeric")

    # Parse size
    if size_str == '-':
        size = 0
    else:
        try:
            size = int(size_str)
            if size < 0:
                raise ValueError()
        except ValueError:
            raise ParseError("Size must be numeric or '-'")

    # Parse latency (if present)
    latency_ms = None
    if latency_str is not None:
        try:
            latency_us = int(latency_str)
            latency_ms = latency_us / 1000.0
        except ValueError:
            raise ParseError("Latency must be numeric")

