    if ts_str.endswith('Z'):
        try:
            ts_str = ts_str[:-1] + '+00:00'
        except:
            raise ParseError("Invalid timestamp format")

    try:
        ts = datetime.fromisoformat(ts_str)
        if ts.tzinfo is None:
            raise ValueError()
    except ValueError:
        raise ParseError("Invalid timestamp format")

    # Check optional keys
    size = obj.get('bytes', 0)
    latency_ms = obj.get('latency_ms')

    return normalize(ts, client, method, path, status, size, latency_ms)

def parse_line(line: str, fmt: str = 'auto') -> Record:
    line = line.strip()
    if not line:
        raise ParseError("Empty line")

    if fmt == 'clf':
        return parse_clf(line)
    elif fmt == 'jsonl':
        return parse_jsonl(line)
    elif fmt == 'auto':
        # Check if JSON
        if line.startswith('{'):
            return parse_jsonl(line)
        else:
            return parse_clf(line)
    else:
        raise ValueError(f"Unknown format: {fmt}")

def read_records(lines: Iterable[str], fmt: str = 'auto') -> Tuple[List[Record], List[int]]:
    records = []
    bad_lines = []

    for idx, line in enumerate(lines, start=1):
        # Strip newline chars for processing but keep track of original
        # The input lines might have trailing newlines
        stripped = line.strip()

        # Skip empty/whitespace lines
        if not stripped:
            continue

        try:
            record = parse_line(stripped, fmt)
            records.append(record)
        except ParseError:
            bad_lines.append(idx)

    return records, bad_lines
