# logagg/stats.py
from typing import Optional, List, Dict, Any, Union
from datetime import datetime

from logagg.parsers import Record, ParseError

def percentile(values: List[float], p: float) -> float:
    if not values:
        raise ValueError("Values list cannot be empty")
    if p <= 0 or p > 100:
        raise ValueError("Percentile p must be in (0, 100]")

    sorted_vals = sorted(values)
    n = len(sorted_vals)
    # Nearest-rank: ceil(p / 100 * n)
    rank = int(-(- (p / 100 * n) // 1)) # Equivalent to ceil
    # If p/100*n is exactly integer, ceil returns that int.
    # Python's math.ceil is safer:
    import math
    rank = math.ceil(p / 100 * n)

    # 1-based index, so subtract 1 for 0-based list
    return sorted_vals[rank - 1]

def filter_records(records: List[Record], since: Optional[datetime] = None, 
                   until: Optional[datetime] = None, 
                   status: Optional[str] = None) -> List[Record]:
    if status is not None:
        # Validate status format
        if status in ('1xx', '2xx', '3xx', '4xx', '5xx'):
            min_s, max_s = int(status[0]) * 100, (int(status[0]) + 1) * 99
            # Actually 4xx is 400-499.
            # 1xx -> 100-199, etc.
            # Simple check: start with digit, rest is x
            # But spec says "class like '4xx' (any status from 400 to 499)"
            # So we parse the first digit.
            base = int(status[0])
            if base < 1 or base > 5:
                raise ValueError("Invalid status class")
            min_s = base * 100
            max_s = min_s + 99
        else:
            # Exact code
            if not status.isdigit():
                raise ValueError("Invalid status code")
            exact = int(status)
            if exact < 100 or exact > 599:
                raise ValueError("Invalid status code")
            min_s = exact
            max_s = exact

        def check_status(r: Record) -> bool:
            return min_s <= r.status <= max_s
    else:
        def check_status(r: Record) -> bool:
            return True

    filtered = []
    for r in records:
        if not check_status(r):
            continue

        if since is not None:
            if r.time < since:
                continue
        if until is not None:
            if r.time >= until:
                continue

        filtered.append(r)

    return filtered

def summarize(records: List[Record], top: int) -> Dict[str, Any]:
    if top < 0:
        raise ValueError("top must be >= 0")

    if not records:
        return {
            "requests": 0,
            "bytes": 0,
            "classes": {"1xx": 0, "2xx": 0, "3xx": 0, "4xx": 0, "5xx": 0},
            "codes": {},
            "latency_ms": {"count": 0, "p50": None, "p95": None, "max": None},
            "top_paths": [],
            "first": None,
            "last": None
        }

    # Basic counts
    req_count = len(records)
    total_bytes = sum(r.size for r in records)

    # Status classes
    classes = {"1xx": 0, "2xx": 0, "3xx": 0, "4xx": 0, "5xx": 0}
    status_counts: Dict[int, int] = {}
    for r in records:
        classes[f"{r.status // 100}xx"] += 1
        status_counts[r.status] = status_counts.get(r.status, 0) + 1

    # Latency stats
    latencies = [r.latency_ms for r in records if r.latency_ms is not None]
    lat_count = len(latencies)

    lat_stats = {"count": lat_count}
    if lat_count > 0:
        lat_stats["p50"] = percentile(latencies, 50)
        lat_stats["p95"] = percentile(latencies, 95)
        lat_stats["max"] = max(latencies)

    # Top paths
    path_counts: Dict[str, int] = {}
    for r in records:
        path_counts[r.path] = path_counts.get(r.path, 0) + 1

    # Sort by count desc, then path asc
    sorted_paths = sorted(path_counts.items(), key=lambda x: (-x[1], x[0]))
    top_paths = [(p, c) for p, c in sorted_paths[:top]]

    # Time range
    times = [r.time for r in records]
    first_time = min(times).isoformat()
    last_time = max(times).isoformat()

    return {
        "requests": req_count,
        "bytes": total_bytes,
        "classes": classes,
        "codes": {str(k): v for k, v in sorted(status_counts.items())},
        "latency_ms": lat_stats,
        "top_paths": top_paths,
        "first": first_time,
        "last": last_time
    }
