# logagg/cli.py
import sys
import argparse
import json
from datetime import datetime, timezone
from typing import List, Optional

from logagg.parsers import read_records, Record
from logagg.stats import filter_records, summarize

def parse_cli_time(s: str) -> datetime:
    try:
        # If no offset, assume UTC
        if '+' not in s and '-' not in s:
            s += '+00:00'
        return datetime.fromisoformat(s)
    except ValueError:
        raise argparse.ArgumentTypeError(f"Invalid time format: {s}")

def parse_status(s: str) -> str:
    return s

def main(argv: Optional[List[str]] = None) -> int:
    parser = argparse.ArgumentParser(description="Aggregate and summarize web server logs")
    parser.add_argument('files', nargs='+', help='Log files to process')
    parser.add_argument('--format', choices=['auto', 'clf', 'jsonl'], default='auto',
                        help='Log format (default: auto)')
    parser.add_argument('--since', type=parse_cli_time, help='Filter start time (ISO 8601)')
    parser.add_argument('--until', type=parse_cli_time, help='Filter end time (ISO 8601)')
    parser.add_argument('--status', type=parse_status, help='Filter by status class (1xx..5xx) or code')
    parser.add_argument('--top', type=int, default=3, help='Number of top paths to show')
    parser.add_argument('--json', action='store_true', help='Output as JSON')

    try:
        args = parser.parse_args(argv)
    except SystemExit:
        return 2

    if args.top < 0:
        print("error: --top must be non-negative", file=sys.stderr)
        return 2

    if args.status is not None and not args.status:
        print("error: --status cannot be empty", file=sys.stderr)
        return 2

    all_records: List[Record] = []
    bad_lines_total = 0

    try:
        for file_path in args.files:
            try:
                with open(file_path, 'r', encoding='utf-8') as f:
                    lines = f.readlines()
            except Exception as e:
                print(f"error: cannot read {file_path}: {e}", file=sys.stderr)
                return 2

            records, bad = read_records(lines, args.format)
            all_records.extend(records)
            bad_lines_total += len(bad)

    except Exception as e:
        print(f"error: unexpected error reading files: {e}", file=sys.stderr)
        return 2

    # Filter
    filtered = filter_records(
        all_records, 
        since=args.since, 
        until=args.until, 
        status=args.status
    )

    # Summarize
    summary = summarize(filtered, args.top)
    summary['bad_lines'] = bad_lines_total

    if args.json:
        print(json.dumps(summary, indent=2))
        return 0

    # Text output
    lines_out = []

    lines_out.append(f"requests: {summary['requests']}")
    lines_out.append(f"bad lines: {summary['bad_lines']}")
    lines_out.append(f"bytes: {summary['bytes']}")

    # Status line
    status_parts = []
    for k in ['1xx', '2xx', '3xx', '4xx', '5xx']:
        val = summary['classes'][k]
        status_parts.append(f"{k}={val}")
    lines_out.append(f"status: {' '.join(status_parts)}")

    # Latency line
    lat = summary['latency_ms']
    if lat['count'] == 0:
        lines_out.append("latency: n/a")
    else:
        p50 = lat['p50']
        p95 = lat['p95']
        mx = lat['max']
        # Format with one decimal place
        lines_out.append(f"latency: p50={p50:.1f} ms p95={p95:.1f} ms max={mx:.1f} ms")

    # Top paths
    lines_out.append("top paths:")
    top_paths = summary['top_paths']
    if not top_paths:
        lines_out.append("  none")
    else:
        for path, count in top_paths:
            lines_out.append(f"  {count} {path}")

    print('\n'.join(lines_out))
    return 0

if __name__ == '__main__':
    sys.exit(main())
