import re

# Internal helper to split a path into parts
def _split_parts(path):
    if path == '/':
        return ['']
    if not path:
        return []
    # Split by '/', filter out empty strings caused by leading/trailing slashes or consecutive slashes
    parts = [p for p in path.split('/') if p]
    return parts

def normalize(path, cwd='/'):
    """
    Returns an absolute path with no '.', '..', repeated '/', or trailing '/'
    (except for root). Relative paths are resolved against cwd.
    Raises ValueError if path is empty.
    """
    if not path:
        raise ValueError("Empty path")

    # Normalize cwd first if it's not already normalized (though caller should ensure it)
    # We assume cwd is always a normalized absolute path as per spec.
    cwd_parts = _split_parts(cwd)

    # Combine cwd and relative path parts
    all_parts = cwd_parts + _split_parts(path)

    result = []
    for part in all_parts:
        if part == '.':
            continue
        elif part == '..':
            if result:
                result.pop()
            # If result is empty and we hit .. at root, we stay at root (empty result for root logic)
        else:
            result.append(part)

    # Construct the path
    if not result:
        return '/'

    # Join parts back
    res = '/'.join(result)
    # Ensure it starts with / since we started with cwd (absolute)
    if not res.startswith('/'):
        res = '/' + res

    return res

def join(base, *parts):
    """
    Joins paths like posixpath.join. If a part starts with '/', it overrides the base.
    Returns the result normalized.
    """
    if not parts:
        return base

    # If the first part is absolute, ignore base
    if parts[0].startswith('/'):
        parts = (parts[0],) + parts[1:]

    combined = base
    for p in parts:
        if p.startswith('/'):
            combined = p
        else:
            combined = normalize(combined + '/' + p)

    return combined

def split(path):
    """
    Takes a normalized absolute path and returns (parent, name).
    split('/') returns ('/', '').
    """
    if path == '/':
        return ('/', '')

    # Find the last slash
    idx = path.rfind('/')
    if idx == -1:
        # Should not happen for normalized paths unless it's just a name without slash
        # But normalized paths always start with /
        parent = '/'
        name = path
        return (parent, name)

    parent = path[:idx]
    name = path[idx+1:]

    # Normalize parent if it ends up being empty (shouldn't happen with valid input) or if it's just '/'
    if not parent:
        parent = '/'

    return (parent, name)

def is_within(path, ancestor):
    """
    Tells whether the normalized path is ancestor itself or lies below it.
    Both path and ancestor must be normalized.
    """
    # Check if they are the same
    if path == ancestor:
        return True

    # Check if path starts with ancestor + '/'
    # Example: /a/bc is not within /a, but /a/b is.
    if path.startswith(ancestor + '/'):
        return True

    return False
