            if dst_abs in self.files:
                # Destination is a file, but we are moving a dir? Or file into file?
                # Spec: "AlreadyExists(target) if the target exists"
                raise AlreadyExists(dst_abs)
            # If dst is a dir, we move src INTO dst
            pass

        if dst_abs in self.files:
            raise AlreadyExists(dst_abs)

        # Determine if dst is a directory
        # If dst_abs is a key in self.dirs, it's a dir.
        # But we might be moving a file INTO a dir (dst is dir, src is file)
        # In that case, target becomes dst + src_name

        src_name = src_abs.rsplit('/', 1)[-1]

        final_dst = dst_abs
        if dst_abs in self.dirs:
            final_dst = join(dst_abs, src_name)

        # Check if final_dst parent exists
        # If final_dst is root, parent is root.
        if final_dst == '/':
            pass
        else:
            p, n = split(final_dst)
            if p not in self.dirs:
                raise NotFound(p)

        # Perform move
        if src_abs in self.dirs:
            # Moving a directory
            self.dirs[final_dst] = self.dirs[src_abs]
            del self.dirs[src_abs]
        else:
            # Moving a file
            self.files[final_dst] = self.files[src_abs]
            del self.files[src_abs]

    def find(self, path='.', pattern='*'):
        import fnmatch

        target = self._resolve(path)
        if target not in self.dirs:
            raise NotFound(target)

        results = []

        def walk(current_path):
            if current_path not in self.dirs:
                return
            for name in self.dirs[current_path]:
                child_path = join(current_path, name)
                # Match name against pattern
                if fnmatch.fnmatchcase(name, pattern):
                    # If child is a directory, recurse
                    if child_path in self.dirs:
                        walk(child_path)
                    else:
                        # It's a file
                        results.append(child_path)

        # Spec: "below path (not path itself)"
        # So we start children of target
        if target == '/':
            walk('/')
        else:
            p, n = split(target)
            # We need to traverse the tree starting from children of target
            # If target is a file, loop won't run, returns [] (correct)
            if target in self.dirs:
                 walk(target)
            else:
                 # Target is a file, find returns [] unless its name matches pattern?
                 # Spec: "for a file, [its path] if its name matches, else []"
                 # Wait, "below path (not path itself)" implies recursive descent.
                 # If path itself is a file, we check it separately?
                 # "for a file, [its path] if its name matches, else []"
                 # This implies if the starting point is a file, we check it.
                 # But "below path" usually means descendants.
                 # Let's re-read: "the absolute paths of everything below path (not path itself) ... for a file, [its path] if its name matches, else []"
                 # This is slightly contradictory.
                 # Interpretation:
                 # If path points to a directory: return descendants matching pattern.
                 # If path points to a file: 
                 #    If it matches pattern, return [path].
                 #    Else return [].
                 # This matches the "for a file" clause.
                 pass

        # Re-evaluating the logic based on "below path (not path itself)"
        # If path is a directory, we look at its children and descendants.
        # If path is a file, we look at... itself? The spec says "for a file, [its path] if...".
        # So:
        if target in self.dirs:
            # Directory
            def _walk(dir_path):
                for name in self.dirs[dir_path]:
                    full_path = join(dir_path, name)
                    if fnmatch.fnmatchcase(name, pattern):
                        results.append(full_path)
                        if full_path in self.dirs:
                            _walk(full_path)

            _walk(target)
        else:
            # File
            if fnmatch.fnmatchcase(self.dirs[target].__class__.__name__, pattern): # Wait, we need to check name
                # We need the name of the file
                p, n = split(target)
                if fnmatch.fnmatchcase(n, pattern):
                    results.append(target)

        return sorted(results)

    def exists(self, path):
        target = self._resolve(path)
        return target in self.dirs or target in self.files

    def is_dir(self, path):
        target = self._resolve(path)
        return target in self.dirs and target not in self.files
