class Shell:
    def __init__(self, fs=None):
        if fs is None:
            self.fs = FileSystem()
        else:
            self.fs = fs
            # Update current_dir if fs has one? 
            # Spec: "state carries over". So we keep fs.current_dir.

    def run(self, script):
        """
        Runs a script string. Returns (output_string, status_code).
        """
        lines = script.splitlines()
        output = []
        status = 0
        line_num = 0

        for line in lines:
            line_num += 1
            stripped = line.strip()

            # Skip empty lines and comments
            if not stripped or stripped.startswith('#'):
                continue

            try:
                # Split into words
                parts = shlex.split(stripped)
                if not parts:
                    continue

                cmd = parts[0]
                args = parts[1:]

                self._execute_cmd(cmd, args, line_num)

            except FSError as e:
                output.append(f"line {line_num}: {cmd}: {type(e).__name__}: {str(e)}")
                status = 1
                # Stop execution on first error
                break
            except Exception as e:
                # Unknown error, treat as usage? Or crash?
                # Spec says: "unknown command", "wrong arguments".
                # This covers shlex errors or unexpected args.
                # If shlex fails, it's a quoting error -> usage.
                # If logic fails unexpectedly, maybe usage.
                output.append(f"line {line_num}: {cmd}: usage")
                status = 2
                break

        return "\n".join(output), status

    def _execute_cmd(self, cmd, args, line_num):
        # Handle flags like -p, -r only as first arg
        # If args[0] is -p or -r, remove it and set flag.
        # If args[0] starts with - but is not -p or -r, it's usage.

        use_p = False
        use_r = False

        if args and args[0] in ['-p', '-r']:
            opt = args.pop(0)
            if opt == '-p':
                use_p = True
            elif opt == '-r':
                use_r = True

        # Check for invalid flags
        if args and args[0].startswith('-') and args[0] not in ['-p', '-r']:
            # Check if it's a known flag disguised? No, only -p and -r.
            raise ValueError("usage")

        try:
            if cmd == 'pwd':
                print(self.fs.pwd())

            elif cmd == 'cd':
                if not args:
                    raise ValueError("usage")
                path = args[0]
                self.fs.cd(path)

            elif cmd == 'mkdir':
                if not args:
                    raise ValueError("usage")
                paths = args
                for p in paths:
                    self.fs.mkdir(p, parents=use_p)

            elif cmd == 'ls':
                if args:
                    path = args[0]
                    items = self.fs.ls(path)
                    for item in items:
                        print(item)
                else:
                    items = self.fs.ls('.')
                    for item in items:
                        print(item)

            elif cmd == 'rm':
                if not args:
                    raise ValueError("usage")
                for p in args:
                    self.fs.rm(p, recursive=use_r)

            elif cmd == 'mv':
                if len(args) != 2:
                    raise ValueError("usage")
                src, dst = args
                self.fs.mv(src, dst)

            elif cmd == 'write':
                if not args:
                    raise ValueError("usage")
                path = args[0]
                content = ' '.join(args[1:]) + '\n'
                self.fs.write(path, content)

            elif cmd == 'append':
                if not args:
                    raise ValueError("usage")
                path = args[0]
                content = ' '.join(args[1:]) + '\n'
                self.fs.write(path, content, append=True)

            elif cmd == 'cat':
                if not args:
                    raise ValueError("usage")
                for p in args:
                    text = self.fs.read(p)
                    print(text, end='')

            elif cmd == 'find':
                path = '.'
                pattern = '*'
                # Check for -name
                i = 0
                while i < len(args):
                    if args[i] == '-name' and i + 1 < len(args):
                        pattern = args[i+1]
                        i += 2
                    elif args[i].startswith('-'):
                        # Unknown flag
                        raise ValueError("usage")
                    else:
                        path = args[i]
                        i += 1

                if not args:
                    path = '.'

                # Reset i logic: simpler to parse manually
                # Re-parse args for find
                find_args = list(args) # Copy
                # Find last positional arg that is not a flag start
                # Actually spec: "find [PATH] [-name PATTERN]"
                # Path is first positional. -name is flag.
                # If multiple args, first is path? Or can be -name first?
                # "find [PATH] [-name PATTERN]" implies optional path, optional flag.
                # Usually path is first if present.

                final_path = '.'
                final_pattern = '*'

                # Re-scan
                idx = 0
                while idx < len(args):
                    if args[idx] == '-name' and idx + 1 < len(args):
                        final_pattern = args[idx+1]
                        idx += 2
                    elif not args[idx].startswith('-'):
                        final_path = args[idx]
                        idx += 1
                    else:
                        # Unknown flag
                        raise ValueError("usage")

                results = self.fs.find(final_path, final_pattern)
                for r in results:
                    print(r)

            else:
                raise ValueError("unknown command")

        except ValueError:
            raise ValueError("usage")
        except Exception as e:
            # Wrap any unexpected exception into FSError with path?
            # If it's a known FSError, we re-raise.
            if isinstance(e, FSError):
                raise
            # If something else happened, maybe usage?
            # Let's assume strict: if not FSError, it's usage or crash.
            # To be safe for teaching: usage.
            raise ValueError("usage")

def main():
    if len(sys.argv) != 2:
        print("Usage: python -m vfs.shell SCRIPT", file=sys.stderr)
        sys.exit(2)

    script_path = sys.argv[1]

    try:
        with open(script_path, 'r') as f:
            script_content = f.read()
    except Exception:
        print(f"error: cannot read {script_path}", file=sys.stderr)
        sys.exit(2)

    shell = Shell()
    output, status = shell.run(script_content)
    print(output)
    sys.exit(status)

if __name__ == '__main__':
    main()
